                    thought = "Read 1. Incrementing to 2.";
                    tool = "file_write";
                    args = { path: "counter.txt", content: "2" };
                } else if (prompt.includes("content\": \"2")) {
                    // Step 4: Done
                    thought = "Task complete.";
                    done = true;
                } else {
                    // Default fallback
                    thought = "Thinking...";
                    done = true;
                }

                return {
                    choices: [{
                        message: {
