type Id = string;

export interface MockRun {
  id: Id;
  sessionId?: Id;
  status: 'pending' | 'running' | 'done' | 'blocked' | 'failed';
  steps: Array<{ name: string; status: 'pending' | 'running' | 'done' | 'blocked' | 'failed'; why?: string }>;
}
export interface MockToolExec {
  id: Id;
  runId: Id;
  name: string;
  input: any;
  output?: any;
  ok: boolean;
  logs: string[];
  createdAt: number;
}
export interface MockArtifact {
  id: Id;
  runId: Id;
  name: string;
  href: string;
}
export interface MockApproval {
  id: Id;
  runId: Id;
  action: string;
  risk: string;
  status: 'pending' | 'approved' | 'denied';
  planName: string;
  planInput: any;
}

export interface MockFolder {
  _id: Id;
  name: string;
  createdAt: number;
  updatedAt: number;
}

const runs: MockRun[] = [];
const execs: MockToolExec[] = [];
const artifacts: MockArtifact[] = [];
const approvals: MockApproval[] = [];
const folders: MockFolder[] = [];
const sessions: Array<{ id: Id; title: string; mode: 'ADVISOR' | 'BUILDER' | 'SAFE' | 'OWNER'; kind?: 'chat' | 'agent'; lastSnippet?: string; lastUpdatedAt?: number }> = [];
const summaries: Array<{ sessionId: Id; content: string; ts: number }> = [];
const messages: Array<{ id: Id; sessionId: Id; role: 'user' | 'assistant' | 'system'; content: string; ts: number; runId?: Id }> = [];

function nextId(prefix: string, n: number) {
  return `${prefix}${n}`;
}

export const store = {
  createRun(sessionId?: Id): MockRun {
    const id = nextId('run_', runs.length + 1);
    const run: MockRun = { id, sessionId, status: 'running', steps: [] };
    runs.push(run);
    return run;
  },
  updateRun(id: Id, patch: Partial<MockRun>) {
    const r = runs.find(x => x.id === id);
    if (r) Object.assign(r, patch);
    return r;
  },
  addStep(runId: Id, name: string, status: MockRun['status'], why?: string) {
    const r = runs.find(x => x.id === runId);
    if (!r) return;
    r.steps.push({ name, status, why });
  },
  addExec(runId: Id, name: string, input: any, output: any, ok: boolean, logs: string[]) {
    const id = nextId('exec_', execs.length + 1);
    const e: MockToolExec = { id, runId, name, input, output, ok, logs, createdAt: Date.now() };
    execs.push(e);
    return e;
  },
  addArtifact(runId: Id, name: string, href: string) {
    const id = nextId('art_', artifacts.length + 1);
    const a: MockArtifact = { id, runId, name, href };
    artifacts.push(a);
    return a;
  },
  createApproval(runId: Id, action: string, risk: string, planName: string, planInput: any) {
    const id = nextId('appr_', approvals.length + 1);
    const ap: MockApproval = { id, runId, action, risk, status: 'pending', planName, planInput };
    approvals.push(ap);
    return ap;
  },
  updateApproval(id: Id, patch: Partial<MockApproval>) {
    const a = approvals.find(x => x.id === id);
    if (a) Object.assign(a, patch);
    return a;
  },
  getApproval(id: Id) {
    return approvals.find(x => x.id === id) || null;
  },
  listFolders() {
    return folders.slice().sort((a, b) => a.createdAt - b.createdAt);
  },
  createFolder(name: string) {
    const id = nextId('fold_', folders.length + 1);
    const now = Date.now();
    const f: MockFolder = { _id: id, name, createdAt: now, updatedAt: now };
    folders.push(f);
    return f;
  },
  updateFolder(id: Id, patch: Partial<Pick<MockFolder, 'name'>>) {
    const f = folders.find(x => x._id === id);
    if (!f) return null;
    if (typeof patch.name === 'string') f.name = patch.name;
    f.updatedAt = Date.now();
    return f;
  },
  deleteFolder(id: Id) {
    const idx = folders.findIndex(x => x._id === id);
    if (idx !== -1) folders.splice(idx, 1);
    return true;
  },
  listRuns(sessionId?: Id) { return runs.filter(r => !sessionId || r.sessionId === sessionId); },
  listExecs(runId?: Id) { return execs.filter(e => !runId || e.runId === runId); },
  listArtifacts(runId?: Id) { return artifacts.filter(a => !runId || a.runId === runId); },
  createSession(
    title: string,
    mode: 'ADVISOR' | 'BUILDER' | 'SAFE' | 'OWNER' = 'ADVISOR',
    kind: 'chat' | 'agent' = 'chat'
  ) {
    const existing = sessions.find(s => s.title === title && (s.kind || 'chat') === kind);
    if (existing) return existing;
    const id = nextId('sess_', sessions.length + 1);
    const s = { id, title, mode, kind };
    sessions.push(s);
    return s;
  },
  listSessions() { return sessions; },
  getSession(id: Id) {
    return sessions.find(s => s.id === id);
  },
  deleteSession(id: Id) {
    const idx = sessions.findIndex(s => s.id === id);
    if (idx !== -1) sessions.splice(idx, 1);
  },
  addMessage(sessionId: Id, role: 'user' | 'assistant' | 'system', content: string, runId?: Id) {
    const id = nextId('msg_', messages.length + 1);
    const m = { id, sessionId, role, content, runId, ts: Date.now() };
    messages.push(m);
    const s = sessions.find(s => s.id === sessionId);
    if (s) { s.lastSnippet = content.slice(0, 140); s.lastUpdatedAt = Date.now(); }
    return m;
  },
  listMessages(sessionId: Id) {
    return messages.filter(m => m.sessionId === sessionId);
  },
  getSummary(sessionId: Id) {
    return summaries.find(x => x.sessionId === sessionId) || null;
  },
  upsertSummary(sessionId: Id, content: string) {
    const existing = summaries.find(x => x.sessionId === sessionId);
    if (existing) {
      existing.content = content;
      existing.ts = Date.now();
      return existing;
    }
    const s = { sessionId, content, ts: Date.now() };
    summaries.push(s);
    return s;
  }
  ,
  mergeSessions(sourceId: Id, targetId: Id) {
    let movedMessages = 0;
    messages.forEach(m => {
      if (m.sessionId === sourceId) {
        m.sessionId = targetId;
        movedMessages++;
      }
    });
    runs.forEach(r => {
      if (r.sessionId === sourceId) {
        r.sessionId = targetId;
      }
    });
    const idx = sessions.findIndex(s => s.id === sourceId);
    if (idx >= 0) sessions.splice(idx, 1);
    return { movedMessages };
  }
};

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

type Role = 'OWNER' | 'ADMIN' | 'USER';
interface MockUser {
  id: string;
  email: string;
  passwordHash: string;
  role: Role;
  name?: string;
  picture?: string;
}

const dbPath = process.env.MOCK_DB_PATH || path.join(os.tmpdir(), 'joe-mock-db.json');

function normalizeEmail(email: string) {
  return String(email || '').trim().toLowerCase();
}

function safeParseJson<T>(raw: string): T | null {
  try {
    return JSON.parse(raw) as T;
  } catch {
    return null;
  }
}

let users: MockUser[] = [];

function loadFromDisk() {
  try {
    if (!fs.existsSync(dbPath)) return;
    const raw = fs.readFileSync(dbPath, 'utf8');
    const parsed = safeParseJson<{ users?: MockUser[] }>(raw);
    if (!parsed || !Array.isArray(parsed.users)) return;
    users = parsed.users
      .filter((u) => u && typeof u.id === 'string' && typeof u.email === 'string' && typeof u.passwordHash === 'string' && typeof u.role === 'string')
      .map((u) => ({ ...u, email: normalizeEmail(u.email) })) as MockUser[];
  } catch {
  }
}

function saveToDisk() {
  try {
    fs.writeFileSync(dbPath, JSON.stringify({ users }, null, 2), 'utf8');
  } catch {
  }
}

loadFromDisk();

export const mockDb = {
  findUserByEmail(email: string) {
    const e = normalizeEmail(email);
    return users.find(u => u.email === e) || null;
  },
  createUser(email: string, passwordHash: string, role: Role) {
    const id = String(users.length + 1);
    const u = { id, email: normalizeEmail(email), passwordHash, role };
    users.push(u);
    saveToDisk();
    return u;
  },
  countUsers() {
    return users.length;
  }
};

/**
 * Long-Term Memory System
 * Vector-based memory storage for conversation history and user preferences
 */

import fs from 'fs/promises';
import path from 'path';

export interface MemoryEntry {
    id: string;
    userId: string;
    type: 'conversation' | 'preference' | 'fact' | 'file' | 'code';
    content: string;
    metadata: Record<string, any>;
    embedding?: number[]; // Will be generated later when we add vector DB
    timestamp: number;
    importance: number; // 0-1, higher = more important
    accessCount: number;
    lastAccessed: number;
}

export interface UserProfile {
    userId: string;
    name?: string;
    preferences: {
        language?: 'ar' | 'en' | 'mixed';
        programmingLanguages?: string[];
        frameworks?: string[];
        codeStyle?: string;
        projectTypes?: string[];
    };
    facts: Map<string, any>; // Known facts about user
    conversationSummaries: string[];
    createdAt: number;
    updatedAt: number;
}

class LongTermMemory {
    private memoryStore: Map<string, MemoryEntry[]> = new Map(); // userId -> memories
    private profiles: Map<string, UserProfile> = new Map(); // userId -> profile
    private memoryDir: string;

    constructor(memoryDir: string = './data/memory') {
        this.memoryDir = memoryDir;
        this.initialize();
    }

    private async initialize() {
        try {
            await fs.mkdir(this.memoryDir, { recursive: true });
            await this.loadFromDisk();
        } catch (error) {
            console.error('[LongTermMemory] Initialization failed:', error);
        }
    }

    /**
     * Store a new memory
     */
    async remember(userId: string, entry: Omit<MemoryEntry, 'id' | 'userId' | 'timestamp' | 'accessCount' | 'lastAccessed'>): Promise<void> {
        const memory: MemoryEntry = {
            ...entry,
            id: `mem_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
            userId,
            timestamp: Date.now(),
            accessCount: 0,
            lastAccessed: Date.now()
        };

        if (!this.memoryStore.has(userId)) {
            this.memoryStore.set(userId, []);
        }

        const userMemories = this.memoryStore.get(userId)!;
        userMemories.push(memory);

        // Keep only last 1000 memories per user
        if (userMemories.length > 1000) {
            userMemories.shift();
        }

        await this.saveToDisk(userId);
    }

    /**
     * Recall memories relevant to a query
     */
    async recall(userId: string, query: string, limit: number = 10): Promise<MemoryEntry[]> {
        const userMemories = this.memoryStore.get(userId) || [];

        if (userMemories.length === 0) return [];

        // Simple keyword matching (will be replaced with vector similarity later)
        const queryLower = query.toLowerCase();
        const queryWords = queryLower.split(/\s+/).filter(w => w.length > 2);

        const scored = userMemories.map(memory => {
            const contentLower = memory.content.toLowerCase();

            // Calculate relevance score
            let score = 0;

            // Keyword matching
            for (const word of queryWords) {
                if (contentLower.includes(word)) {
                    score += 2;
                }
            }

            // Recency bonus (newer = better)
            const ageHours = (Date.now() - memory.timestamp) / (1000 * 60 * 60);
            score += Math.max(0, 1 - (ageHours / 168)); // Decay over 1 week

            // Importance bonus
            score += memory.importance * 3;

            // Access frequency bonus
            score += Math.min(memory.accessCount / 10, 1);

            return { memory, score };
        });

        // Sort by score and return top results
        const ranked = scored
            .filter(s => s.score > 0)
            .sort((a, b) => b.score - a.score)
            .slice(0, limit)
            .map(s => s.memory);

        // Update access counters
        for (const memory of ranked) {
            memory.accessCount++;
            memory.lastAccessed = Date.now();
        }

        return ranked;
    }

    /**
     * Get or create user profile
     */
    async getProfile(userId: string): Promise<UserProfile> {
        if (!this.profiles.has(userId)) {
            const profile: UserProfile = {
                userId,
                preferences: {} as UserProfile['preferences'],
                facts: new Map(),
                conversationSummaries: [],
                createdAt: Date.now(),
                updatedAt: Date.now()
            };
            this.profiles.set(userId, profile);
            await this.saveProfile(userId);
        }

        return this.profiles.get(userId)!;
    }

    /**
     * Update user profile
     */
    async updateProfile(userId: string, updates: Partial<UserProfile>): Promise<void> {
        const profile = await this.getProfile(userId);

        Object.assign(profile, updates);
        profile.updatedAt = Date.now();

        await this.saveProfile(userId);
    }

    /**
     * Learn from conversation
     */
    async learnFromConversation(userId: string, messages: any[]): Promise<void> {
        const profile = await this.getProfile(userId);

        // Extract learnings
        for (const msg of messages) {
            if (msg.role !== 'user') continue;

            const content = typeof msg.content === 'string' ? msg.content : JSON.stringify(msg.content);

            // Learn name
            const nameMatch = content.match(/(?:اسمي|انا|أنا|name is|i am|i'm)\s+([أ-يa-z]+)/i);
            if (nameMatch) {
                profile.name = nameMatch[1];
                profile.facts.set('name', nameMatch[1]);
            }

            // Learn programming preferences
            const progLangs = content.match(/\b(javascript|typescript|python|java|golang|rust|c\+\+|react|vue|angular)\b/gi);
            if (progLangs) {
                profile.preferences.programmingLanguages = [
                    ...(profile.preferences.programmingLanguages || []),
                    ...progLangs.map((l: string) => l.toLowerCase())
                ];
                // Remove duplicates
                profile.preferences.programmingLanguages = Array.from(new Set(profile.preferences.programmingLanguages));
            }

            // Learn project types
            if (/\b(website|web app|api|mobile app)\b/i.test(content)) {
                const type = content.match(/\b(website|web app|api|mobile app)\b/i)?.[0].toLowerCase();
                if (type) {
                    profile.preferences.projectTypes = [
                        ...(profile.preferences.projectTypes || []),
                        type
                    ];
                    profile.preferences.projectTypes = Array.from(new Set(profile.preferences.projectTypes));
                }
            }

            // Store important conversations
            if (content.length > 50) {
                await this.remember(userId, {
                    type: 'conversation',
                    content: content.substring(0, 500),
                    metadata: { timestamp: Date.now() },
                    importance: 0.5
                });
            }
        }

        await this.updateProfile(userId, profile);
    }

    /**
     * Get conversation summary for context
     */
    async getContextSummary(userId: string): Promise<string> {
        const profile = await this.getProfile(userId);
        const recentMemories = await this.recall(userId, '', 5);

        const parts: string[] = [];

        if (profile.name) {
            parts.push(`User name: ${profile.name}`);
        }

        if (profile.preferences.programmingLanguages?.length) {
            parts.push(`Prefers: ${profile.preferences.programmingLanguages.join(', ')}`);
        }

        if (recentMemories.length > 0) {
            parts.push(`Recent context: ${recentMemories.map(m => m.content.substring(0, 100)).join('; ')}`);
        }

        return parts.join(' | ');
    }

    /**
     * Save memories to disk
     */
    private async saveToDisk(userId: string): Promise<void> {
        try {
            const userMemories = this.memoryStore.get(userId) || [];
            const filePath = path.join(this.memoryDir, `${userId}.json`);
            await fs.writeFile(filePath, JSON.stringify(userMemories, null, 2));
        } catch (error) {
            console.error('[LongTermMemory] Save failed:', error);
        }
    }

    /**
     * Save profile to disk
     */
    private async saveProfile(userId: string): Promise<void> {
        try {
            const profile = this.profiles.get(userId);
            if (!profile) return;

            // Convert Map to Object for JSON
            const serializable = {
                ...profile,
                facts: Object.fromEntries(profile.facts)
            };

            const filePath = path.join(this.memoryDir, `${userId}_profile.json`);
            await fs.writeFile(filePath, JSON.stringify(serializable, null, 2));
        } catch (error) {
            console.error('[LongTermMemory] Profile save failed:', error);
        }
    }

    /**
     * Load memories from disk
     */
    private async loadFromDisk(): Promise<void> {
        try {
            const files = await fs.readdir(this.memoryDir);

            for (const file of files) {
                if (file.endsWith('_profile.json')) {
                    const userId = file.replace('_profile.json', '');
                    const content = await fs.readFile(path.join(this.memoryDir, file), 'utf-8');
                    const data = JSON.parse(content);

                    this.profiles.set(userId, {
                        ...data,
                        facts: new Map(Object.entries(data.facts || {}))
                    });
                } else if (file.endsWith('.json')) {
                    const userId = file.replace('.json', '');
                    const content = await fs.readFile(path.join(this.memoryDir, file), 'utf-8');
                    const memories = JSON.parse(content);

                    this.memoryStore.set(userId, memories);
                }
            }

            console.info(`[LongTermMemory] Loaded ${this.profiles.size} profiles and ${this.memoryStore.size} memory stores`);
        } catch (error) {
            console.error('[LongTermMemory] Load failed:', error);
        }
    }
}

// Singleton instance
export const longTermMemory = new LongTermMemory();

export default longTermMemory;

import OpenAI from 'openai';
import path from 'path';
import fs from 'fs';

const OPENAI_API_KEY = process.env.OPENAI_API_KEY;
const MEMORY_DB_PATH = path.join(process.cwd(), 'data', 'lance_memory');

if (!fs.existsSync(path.dirname(MEMORY_DB_PATH))) {
    fs.mkdirSync(path.dirname(MEMORY_DB_PATH), { recursive: true });
}

interface MemoryRecord {
    id: string;
    vector: number[];
    text: string;
    metadata: string; // LanceDB handles complex types best if serialized or specific columns
    timestamp: number;
}

export class VectorMemory {
    private openai: OpenAI | null = null;
    private db: any = null;
    private table: any = null;
    private tableName = 'joe_memory';

    constructor() {
        if (OPENAI_API_KEY) {
            this.openai = new OpenAI({ apiKey: OPENAI_API_KEY });
        }
    }

    async init() {
        try {
            console.log('[VectorMemory] Attempting to load LanceDB...');
            const lancedb = require('@lancedb/lancedb');

            this.db = await lancedb.connect(MEMORY_DB_PATH);

            const existingTables = await this.db.tableNames();

            if (existingTables.includes(this.tableName)) {
                this.table = await this.db.openTable(this.tableName);
            } else {
                // Initial schema creation with a dummy row to define types, then delete it or keep it?
                // LanceDB usually infers from data. We can pass a schema but infer is easier for JS.
                // We'll lazy init on first add if not exists, OR create with empty data if possible.
                // For simplified flow: We won't create 'table' here if it doesn't exist.
                // We will handle it in `add`.
                console.log('[VectorMemory] Table does not exist yet. Will create on first add.');
            }

            console.log(`[VectorMemory] Connected to LanceDB at ${MEMORY_DB_PATH}`);
        } catch (e) {
            console.error('[VectorMemory] Failed to init LanceDB (Module might be missing or broken). Memory features disabled.', e);
        }
    }

    async createEmbedding(text: string): Promise<number[]> {
        if (!this.openai) {
            throw new Error('[VectorMemory] OpenAI API key not configured. Memory features unavailable.');
        }
        try {
            const response = await this.openai.embeddings.create({
                model: "text-embedding-3-small",
                input: text,
                encoding_format: "float",
            });
            return response.data[0].embedding;
        } catch (e) {
            console.error('[VectorMemory] Embedding failed:', e);
            throw new Error(`Failed to create embedding: ${e instanceof Error ? e.message : 'Unknown error'}`);
        }
    }

    async add(id: string, text: string, metadata: Record<string, any> = {}) {
        if (!this.db) await this.init();
        if (!this.db) {
            throw new Error('[VectorMemory] Database not available. Cannot add memory.');
        }

        const vector = await this.createEmbedding(text);
        const record = {
            id,
            vector,
            text,
            metadata: JSON.stringify(metadata),
            timestamp: Date.now()
        };

        if (!this.table) {
            const tables = await this.db.tableNames();
            if (tables.includes(this.tableName)) {
                this.table = await this.db.openTable(this.tableName);
            } else {
                this.table = await this.db.createTable(this.tableName, [record]);
                return; // Created with the record
            }
        }

        // Add to existing
        await this.table.add([record]);
    }

    async search(query: string, limit: number = 5) {
        if (!this.db) await this.init();
        if (!this.table || !this.db) {
            // Table doesn't exist = no memory
            return { ids: [[]], documents: [[]], distances: [[]] };
        }

        const queryVector = await this.createEmbedding(query);

        try {
            const results = await this.table.vectorSearch(queryVector)
                .limit(limit)
                .toArray();

            // Map to old API format for compatibility
            const ids = results.map((r: any) => r.id as string);
            const docs = results.map((r: any) => r.text as string);
            // LanceDB returns 'score' or '_distance' depending on version/config. 
            // Usually '_distance'. Lower is better (L2) or Higher (Cosine)? 
            // Default is usually L2. We need to check docs or observe.
            // Assuming Euclidean distance for now (lower is better).
            // We'll normalize or just pass it through.
            const dists = results.map((r: any) => (r._distance || 0) as number);

            return {
                ids: [ids],
                documents: [docs],
                distances: [dists] // Note: Metrics might differ from Cosine Sim
            };
        } catch (e) {
            console.error('[VectorMemory] Search failed:', e);
            return { ids: [[]], documents: [[]], distances: [[]] };
        }
    }
}

import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { config } from '../config';

export interface AuthPayload {
  sub: string;
  role: 'OWNER' | 'ADMIN' | 'USER';
}

export function authenticate(req: Request, res: Response, next: NextFunction) {
  // FALLBACK: Only allow bypass if explicitly check env var, NO HARDCODED TOKENS.
  if (process.env.ENABLE_AUTH_BYPASS === 'true') {
    (req as any).auth = { sub: 'offline_admin', role: 'OWNER' };
    return next();
  }

  const header = req.headers.authorization;
  if (!header || !header.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  const token = header.slice('Bearer '.length);
  try {
    const payload = jwt.verify(token, config.jwtSecret) as AuthPayload;
    (req as any).auth = payload;
    return next();
  } catch {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

export function authenticateOptional(req: Request, res: Response, next: NextFunction) {
  if (process.env.ENABLE_AUTH_BYPASS === 'true') {
    (req as any).auth = { sub: 'offline_admin', role: 'OWNER' };
    return next();
  }

  const header = req.headers.authorization;
  if (!header || !header.startsWith('Bearer ')) {
    return next();
  }
  const token = header.slice('Bearer '.length);
  try {
    const payload = jwt.verify(token, config.jwtSecret) as AuthPayload;
    (req as any).auth = payload;
    return next();
  } catch {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

/**
 * Context Analyzer
 * Analyzes conversation context to determine task type, complexity, and required capabilities
 */

export interface ConversationContext {
    taskType: 'coding' | 'research' | 'debugging' | 'browsing' | 'planning' | 'mixed';
    complexity: 'simple' | 'medium' | 'complex';
    phase: 'planning' | 'execution' | 'verification' | 'learning';
    intent: string[];
    projectType?: 'web' | 'api' | 'mobile' | 'fullstack' | 'library' | 'unknown';
    requiredCapabilities: string[];
    suggestedTools: string[];
}

/**
 * Analyze messages to determine conversation context
 */
export function analyzeContext(messages: Array<{ role: string; content: string | any[] }>): ConversationContext {
    const recentMessages = messages.slice(-5);
    const fullText = recentMessages
        .map(m => typeof m.content === 'string' ? m.content : JSON.stringify(m.content))
        .join('\n')
        .toLowerCase();

    // Detect task type
    const taskType = detectTaskType(fullText);

    // Detect complexity
    const complexity = detectComplexity(fullText, messages.length);

    // Detect phase
    const phase = detectPhase(fullText, messages);

    // Extract intent signals
    const intent = extractIntent(fullText);

    // Detect project type
    const projectType = detectProjectType(fullText);

    // Determine required capabilities
    const requiredCapabilities = determineCapabilities(fullText, taskType);

    // Suggest optimal tools
    const suggestedTools = suggestTools(taskType, requiredCapabilities, fullText);

    return {
        taskType,
        complexity,
        phase,
        intent,
        projectType,
        requiredCapabilities,
        suggestedTools
    };
}

function detectTaskType(text: string): ConversationContext['taskType'] {
    const lower = text.toLowerCase();

    const patterns = {
        coding: /(code|implement|build|create|component|function|class|file|edit|refactor|optimize|برمج|كود|انشئ|أنشئ|بناء)/gi,
        research: /(research|find|search|compare|analyze|investigate|what is|how does|أفضل|مقارنة|ابحث|بحث|قارن|ما هو|كيف)/gi,
        debugging: /(bug|error|fail|failure|crash|fix|debug|issue|problem|broken|not working|خطأ|مشكلة|عطل|يفشل)/gi,
        browsing: /(browser|website|web|open|login|click|navigate|scrape|افتح|متصفح|موقع|تصفح)/gi,
        planning: /(plan|design|architect|structure|organize|strategy|approach|خطة|تصميم|هيكل)/gi
    };

    const scores: Record<string, number> = {};

    // Count matches for each type
    for (const [type, pattern] of Object.entries(patterns)) {
        const matches = lower.match(pattern);
        scores[type] = matches ? matches.length : 0;
    }

    const maxScore = Math.max(...Object.values(scores));
    if (maxScore === 0) return 'mixed';

    // Get all types with max score
    const topTypes = Object.entries(scores)
        .filter(([_, score]) => score === maxScore)
        .map(([type]) => type);

    // If only one dominant type
    if (topTypes.length === 1) {
        return topTypes[0] as ConversationContext['taskType'];
    }

    // Priority when multiple types have same score
    // Research and debugging are more specific, prioritize them
    const priority = ['research', 'debugging', 'coding', 'browsing', 'planning'];
    for (const type of priority) {
        if (topTypes.includes(type)) {
            return type as ConversationContext['taskType'];
        }
    }

    return 'mixed';
}

function detectComplexity(text: string, messageCount: number): ConversationContext['complexity'] {
    const complexitySignals = {
        simple: /(quick|simple|just|only|small|single)/,
        complex: /(complex|comprehensive|detailed|full|complete|entire|all|multiple|scalable|production)/
    };

    const hasComplexSignals = complexitySignals.complex.test(text);
    const hasSimpleSignals = complexitySignals.simple.test(text);

    // Long conversations tend to be complex
    if (messageCount > 10) return 'complex';

    // Text length indicator
    if (text.length > 500) {
        return hasSimpleSignals ? 'medium' : 'complex';
    }

    if (hasComplexSignals) return 'complex';
    if (hasSimpleSignals) return 'simple';

    return 'medium';
}

function detectPhase(text: string, messages: any[]): ConversationContext['phase'] {
    const phasePatterns = {
        planning: /(plan|design|how should|what's the best way|approach|strategy)/,
        execution: /(do it|build|create|implement|make|write|add|update)/,
        verification: /(test|verify|check|validate|ensure|confirm|works)/,
        learning: /(explain|how does|why|what is|teach|learn|understand)/
    };

    for (const [phase, pattern] of Object.entries(phasePatterns)) {
        if (pattern.test(text)) {
            return phase as ConversationContext['phase'];
        }
    }

    // Check if previous messages had tool outputs (likely execution phase)
    const hasToolOutputs = messages.slice(-3).some(m =>
        m.role === 'tool' || (typeof m.content === 'string' && m.content.includes('ok:'))
    );

    if (hasToolOutputs) return 'verification';

    return 'execution';
}

function extractIntent(text: string): string[] {
    const intents: string[] = [];

    const intentPatterns = {
        'file_operations': /(read|write|edit|delete|create) (file|folder)/,
        'web_research': /(search|find|look up|research)/,
        'browser_automation': /(browse|open|login|click|navigate)/,
        'code_generation': /(generate|create|build|scaffold)/,
        'code_analysis': /(analyze|review|check|inspect)/,
        'testing': /(test|verify|validate|ensure)/,
        'deployment': /(deploy|publish|release|build)/,
        'learning': /(explain|how|why|what is)/
    };

    for (const [intent, pattern] of Object.entries(intentPatterns)) {
        if (pattern.test(text)) {
            intents.push(intent);
        }
    }

    return intents;
}

function detectProjectType(text: string): ConversationContext['projectType'] {
    const projectPatterns = {
        web: /(react|vue|next|vite|html|css|frontend|website|web app)/,
        api: /(api|backend|server|express|fastify|endpoint|rest|graphql)/,
        mobile: /(mobile|ios|android|react native|flutter)/,
        fullstack: /(fullstack|full stack|full-stack|frontend.*backend|backend.*frontend)/,
        library: /(library|package|npm|module|sdk)/
    };

    for (const [type, pattern] of Object.entries(projectPatterns)) {
        if (pattern.test(text)) {
            return type as ConversationContext['projectType'];
        }
    }

    return 'unknown';
}

function determineCapabilities(text: string, taskType: string): string[] {
    const capabilities: string[] = [];

    // Based on text patterns
    if (/file|folder|path|directory/.test(text)) capabilities.push('file_system');
    if (/npm|node|shell|command|terminal/.test(text)) capabilities.push('shell');
    if (/browser|web|http|url/.test(text)) capabilities.push('browser');
    if (/test|jest|vitest|cypress/.test(text)) capabilities.push('testing');
    if (/git|github|commit|branch/.test(text)) capabilities.push('git');
    if (/database|db|sql|mongo/.test(text)) capabilities.push('database');
    if (/search|research|find information/.test(text)) capabilities.push('web_search');

    // Based on task type
    if (taskType === 'coding') {
        capabilities.push('file_system', 'shell');
    } else if (taskType === 'research') {
        capabilities.push('web_search');
    } else if (taskType === 'browsing') {
        capabilities.push('browser');
    } else if (taskType === 'debugging') {
        capabilities.push('file_system', 'shell', 'testing');
    }

    return [...new Set(capabilities)];
}

function suggestTools(taskType: string, capabilities: string[], text: string): string[] {
    const tools: string[] = ['echo']; // Always available

    // Add tools based on capabilities
    if (capabilities.includes('file_system')) {
        tools.push('file_read', 'file_write', 'file_edit', 'ls', 'grep_search');
    }

    if (capabilities.includes('shell')) {
        tools.push('shell_execute', 'command_policy_check');
    }

    if (capabilities.includes('browser')) {
        tools.push('browser_run', 'browser_open');
    }

    if (capabilities.includes('web_search')) {
        tools.push('web_search', 'deep_research', 'html_extract');
    }

    if (capabilities.includes('testing')) {
        tools.push('quality_run', 'generate_tests');
    }

    if (capabilities.includes('git')) {
        tools.push('git_ops', 'github_create_repo');
    }

    // Add task-specific tools
    if (taskType === 'coding') {
        tools.push('analyze_codebase', 'scaffold_project', 'check_syntax');
    } else if (taskType === 'research') {
        tools.push('knowledge_search', 'deep_research');
    }

    return [...new Set(tools)];
}

export default {
    analyzeContext
};

/**
 * Joe Enterprise Integration Layer
 * Connects all systems: Context, Memory, Agents, Browser, Vision, Voice, Code Generation
*/

import { buildConversationContext, analyzeContextualIntent, matchPatternWithContext } from '../llm/context-engine';
import { longTermMemory } from '../memory/long-term-memory';
import { orchestrator } from '../agents/orchestrator';
import { analyzeImage, screenshotToCode } from '../vision/image-analyzer';
import { transcribeAudio, synthesizeSpeech, detectVoiceCommand } from '../voice/interface';
import { codeGenerator } from '../codegen/large-scale-generator';
import { routeToModel, analyzeTask } from '../llm/intelligent-router';

export interface EnhancedRequest {
    userId: string;
    sessionId: string;
    message: string;
    audio?: Buffer;
    image?: Buffer;
    history: any[];
    preferences?: Record<string, any>;
}

export interface EnhancedResponse {
    text: string;
    audio?: Buffer;
    tool?: string;
    artifacts?: string[];
    nextSteps?: string[];
    confidence: number;
}

/**
 * Main enterprise  processing pipeline
 */
export async function processEnterpriseRequest(request: EnhancedRequest): Promise<EnhancedResponse> {
    const { userId, sessionId, message, audio, image, history } = request;

    console.info(`[Enterprise] Processing request for user ${userId}`);

    // Step 1: Handle multimodal inputs
    let finalMessage = message;

    if (audio) {
        console.info('[Enterprise] Transcribing audio...');
        const transcription = await transcribeAudio(audio);
        finalMessage = transcription.text;

        // Check for voice command
        const voiceCmd = detectVoiceCommand(finalMessage);
        if (voiceCmd.isCommand) {
            console.info(`[Enterprise] Voice command detected: ${voiceCmd.command}`);
        }
    }

    if (image) {
        console.info('[Enterprise] Analyzing image...');
        const imageAnalysis = await analyzeImage(image);

        if (imageAnalysis.type === 'screenshot' || imageAnalysis.type === 'ui') {
            // Generate code from UI
            const code = await screenshotToCode('buffer', 'react');
            return {
                text: 'I analyzed the UI screenshot and generated React code:',
                tool: 'vision_to_code',
                artifacts: ['generated_component.tsx'],
                confidence: 0.85
            };
        }

        // Add image context to message
        finalMessage += `\n[Image: ${imageAnalysis.description}]`;
    }

    // Step 2: Build conversation context
    const context = buildConversationContext(userId, sessionId, history);

    // Step 3: Learn from conversation
    await longTermMemory.learnFromConversation(userId, history);

    // Step 4: Check for contextual patterns
    const contextMatch = matchPatternWithContext(finalMessage, context);

    if (contextMatch.matched) {
        console.info(`[Enterprise] Context match: ${contextMatch.action}`);

        // Execute matched action
        return {
            text: `Executing ${contextMatch.action}...`,
            tool: contextMatch.action!,
            confidence: contextMatch.confidence
        };
    }

    // Step 5: Analyze intent
    const intent = analyzeContextualIntent(finalMessage, context);
    console.info(`[Enterprise] Intent: ${intent.primary} (${intent.confidence})`);

    // Step 6: Check for project building request
    if (/\b(build|create|make)\s+(a\s+)?(website|app|api|application|project|system)\b/i.test(finalMessage)) {
        console.info('[Enterprise] Project building request detected');

        // Use orchestrator to build complete application
        const result = await orchestrator.buildApplication(finalMessage);

        return {
            text: `I'll build your ${result.plan.projectType} application with ${result.plan.tasks.length} tasks.\n\nFiles created: ${result.totalFiles}`,
            tool: 'build_application',
            artifacts: result.results.flatMap(r => r.artifacts || []),
            nextSteps: result.plan.tasks.slice(0, 3).map(t => t.description),
            confidence: 0.9
        };
    }

    // Step 7: Check for code generation
    if (/\b(generate|create|write)\s+(code|component|function|class|api)\b/i.test(finalMessage)) {
        console.info('[Enterprise] Code generation request');

        // Determine project config from context
        const config = {
            name: context.projectContext?.type || 'my-app',
            type: (context.projectContext?.type || 'web') as any,
            framework: context.entities.get('programmingLanguages')?.[0] || 'react',
            features: [],
            testing: true
        };

        const { files, structure } = await codeGenerator.generateProject(config);

        return {
            text: `Generated ${files.size} files:\n\`\`\`\n${structure}\n\`\`\``,
            tool: 'code_generation',
            artifacts: Array.from(files.keys()),
            confidence: 0.85
        };
    }

    // Step 8: Intelligent model routing for general questions
    const taskAnalysis = analyzeTask(finalMessage, history);
    console.info(`[Enterprise] Task: ${taskAnalysis.type} | Complexity: ${taskAnalysis.complexity}`);

    // Get user context summary for better responses
    const contextSummary = await longTermMemory.getContextSummary(userId);

    const messages = [
        {
            role: 'system' as const,
            content: `You are Joe, an advanced enterprise AI assistant. ${contextSummary ? `Context: ${contextSummary}` : ''}`
        },
        ...history.map(h => ({
            role: h.role as 'user' | 'assistant',
            content: h.content
        })),
        {
            role: 'user' as const,
            content: finalMessage
        }
    ];

    const response = await routeToModel(messages, taskAnalysis);

    // Step 9: Remember this interaction
    await longTermMemory.remember(userId, {
        type: 'conversation',
        content: finalMessage,
        metadata: {
            intent: intent.primary,
            taskType: taskAnalysis.type,
            timestamp: Date.now()
        },
        importance: taskAnalysis.complexity === 'high' ? 0.8 : 0.5
    });

    return {
        text: response,
        confidence: 0.75
    };
}

/**
 * Simplified helper for Auto mode
 */
export async function enhanceAutoMode(
    userMessage: string,
    userId: string,
    sessionId: string,
    history: any[]
): Promise<{ name: string; input: any } | null> {

    try {
        const request: EnhancedRequest = {
            userId,
            sessionId,
            message: userMessage,
            history
        };

        const response = await processEnterpriseRequest(request);

        if (response.tool) {
            return {
                name: response.tool,
                input: { ...response }
            };
        }

        return {
            name: 'echo',
            input: { text: response.text }
        };

    } catch (error: any) {
        console.error('[Enterprise] Enhancement failed:', error);
        return null;
    }
}

