}`;

        let responseText = "";
        if (provider === 'groq') {
            responseText = await callGroq(analyst, [{ role: 'system', content: systemPrompt }, { role: 'user', content: userMessage }]);
        } else {
            if (!hack) {
                // Use require to bypass TS1323 and handle circular dependency
