                hack = llm.pollinationsProvider;
            }
            responseText = await hack.chatComplete([{ role: 'system', content: systemPrompt }, { role: 'user', content: userMessage }], 'openai');
        }

        // Clean JSON response
        const jsonMatch = responseText.match(/\{[\s\S]*\}/);
