/**
 * Make API call to Groq (free Llama/Mixtral/Gemma models)
 */
/**
 * Make API call to Groq (free Llama/Mixtral/Gemma models)
 */
async function callGroq(model: string, messages: any[], onPartial?: (delta: string) => void): Promise<string> {
    const GROQ_API_KEY = process.env.GROQ_API_KEY || 'gsk_placeholder';

    try {
        const stream = !!onPartial;
        const response = await fetch('https://api.groq.com/openai/v1/chat/completions', {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${GROQ_API_KEY}`,
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                model,
                messages,
                temperature: 0.7,
                max_tokens: 8000,
                stream
            })
        });

        if (!response.ok) {
            throw new Error(`Groq API error: ${response.status}`);
        }

        if (stream && response.body) {
            const reader = response.body.getReader();
            const decoder = new TextDecoder('utf-8');
            let fullText = '';
            let buffer = '';

            try {
                while (true) {
                    const { done, value } = await reader.read();
                    if (done) break;
                    const chunk = decoder.decode(value, { stream: true });
                    buffer += chunk;

                    const lines = buffer.split('\n');
                    buffer = lines.pop() || '';

                    for (const line of lines) {
                        const trimmed = line.trim();
                        if (trimmed === 'data: [DONE]') continue;
                        if (trimmed.startsWith('data: ')) {
                            try {
                                const json = JSON.parse(trimmed.slice(6));
                                const content = json.choices[0]?.delta?.content || '';
                                if (content) {
                                    fullText += content;
                                    onPartial?.(content);
                                }
                            } catch { }
                        }
                    }
                }
            } catch (err) {
                console.error('Stream reading failed', err);
            }
            return fullText;
        } else {
            const data = await response.json();
            return data.choices[0]?.message?.content || '';
        }

    } catch (err: any) {
        console.error('[Groq] API call failed:', err.message);
        throw err;
    }
}

