function extractJsonLike(text: string) {
  const raw = String(text || '').trim();
  if (!raw) return '';
  if (raw.startsWith('{') && raw.endsWith('}')) return raw;
  if (raw.startsWith('[') && raw.endsWith(']')) return raw;
  const m = raw.match(/\{[\s\S]*\}/);
  return String(m?.[0] || '').trim();
}

function deepRedactForDebug(v: any): any {
  if (v == null) return v;
  if (typeof v === 'string') return redactSecretsFromString(v);
  if (typeof v === 'number' || typeof v === 'boolean') return v;
  if (Array.isArray(v)) return v.map((x) => deepRedactForDebug(x));
  if (typeof v === 'object') {
    const out: any = {};
    for (const k of Object.keys(v)) out[k] = deepRedactForDebug((v as any)[k]);
    return out;
  }
  return redactSecretsFromString(String(v));
}

async function collectUiGroundingSnapshot(sessionId: string) {
  const sid = String(sessionId || '').trim();
  if (!sid) return null;
  try {
    const s = await getBrowserSession(sid);
    touchSession(sid);
    const page = s.page;
    const viewport = { w: s.viewport?.w || 0, h: s.viewport?.h || 0 };
    const url = (() => {
      try {
        return page.url();
      } catch {
        return '';
      }
    })();
    const raw = await page.evaluate(() => {
      const maxTextLen = 120;
      const maxAttrLen = 120;
      const clampText = (v: any) =>
        String(v || '')
          .replace(/\s+/g, ' ')
          .trim()
          .slice(0, maxTextLen);

      const isVisible = (el: Element, rect: DOMRect) => {
        if (rect.width < 2 || rect.height < 2) return false;
        const s = window.getComputedStyle(el as any);
        if (!s) return false;
        if (s.display === 'none' || s.visibility === 'hidden') return false;
        const o = Number(s.opacity || '1');
        if (Number.isFinite(o) && o < 0.02) return false;
        if ((el as any).hasAttribute?.('hidden')) return false;
        return true;
      };

      const pickAttr = (el: Element, name: string) => {
        try {
          const v = (el as any).getAttribute?.(name);
          if (typeof v !== 'string') return '';
          return v.slice(0, maxAttrLen);
        } catch {
          return '';
        }
      };

      const tag = (el: Element) => String((el as any).tagName || '').toLowerCase();
      const role = (el: Element) => pickAttr(el, 'role');

      const kindOf = (el: Element) => {
        const t = tag(el);
        const r = role(el);
        if (t === 'button') return 'button';
        if (t === 'a' && pickAttr(el, 'href')) return 'link';
        if (t === 'input') {
          const ty = pickAttr(el, 'type').toLowerCase();
          if (ty === 'submit' || ty === 'button' || ty === 'reset') return 'button';
          return 'input';
        }
        if (t === 'textarea') return 'textarea';
        if (t === 'select') return 'select';
        if (t === 'img') return 'image';
        if (r === 'button') return 'button';
        if (r === 'link') return 'link';
        if (r === 'textbox') return 'input';
        if ((el as any).isContentEditable) return 'input';
        const txt = clampText((el as any).innerText || '');
        if (txt) return 'text';
        return 'unknown';
      };

      const elements: any[] = [];
      const candidates = Array.from(
        document.querySelectorAll(
          [
            'a[href]',
            'button',
            'input',
            'textarea',
            'select',
            '[role="button"]',
            '[role="link"]',
            '[role="textbox"]',
            '[contenteditable="true"]',
            '[tabindex]',
            '[class*="btn"]',
            '[class*="button"]',
            '[id*="login"]',
            '[id*="signin"]',
            '[aria-label]',
            'label',
            'summary',
            'h1,h2,h3,h4,h5,h6,p,li,span',
          ].join(','),
        ),
      );

      for (const el of candidates) {
        try {
          const rect = (el as any).getBoundingClientRect?.();
          if (!rect) continue;
          if (!isVisible(el, rect)) continue;
          const k = kindOf(el);
          if (k === 'unknown') continue;

          const t = tag(el);
          const text =
            k === 'input' || k === 'textarea' || k === 'select'
              ? clampText((el as any).value || pickAttr(el, 'placeholder') || pickAttr(el, 'aria-label') || '')
              : clampText((el as any).innerText || pickAttr(el, 'aria-label') || pickAttr(el, 'title') || '');

          if (k === 'text') {
            if (!text) continue;
            if (text.length > 80) continue;
            const childCount = (el as any).children?.length || 0;
            if (childCount > 3) continue;
          }

          const ariaLabel = pickAttr(el, 'aria-label');
          const placeholder = t === 'input' || t === 'textarea' ? pickAttr(el, 'placeholder') : '';
          const nameAttr = pickAttr(el, 'name');
          const idAttr = pickAttr(el, 'id');
          const href = t === 'a' ? pickAttr(el, 'href') : '';
          const typeAttr = t === 'input' ? pickAttr(el, 'type') : '';

          elements.push({
            kind: k,
            tag: t,
            role: role(el),
            text,
            ariaLabel,
            placeholder,
            nameAttr,
            idAttr,
            href,
            typeAttr,
            rect: { x: rect.x, y: rect.y, width: rect.width, height: rect.height },
          });
        } catch { }
      }

      const byPos = (a: any, b: any) => (a.rect.y === b.rect.y ? a.rect.x - b.rect.x : a.rect.y - b.rect.y);
      elements.sort(byPos);

      const viewport = {
        w: window.innerWidth || 0,
        h: window.innerHeight || 0,
        scrollX: window.scrollX || 0,
        scrollY: window.scrollY || 0,
        dpr: window.devicePixelRatio || 1,
      };

      return { viewport, elements: elements.slice(0, 400) };
    });

    const els = Array.isArray(raw?.elements) ? raw.elements : [];
    const elements = els.map((e: any, i: number) => {
      const rect = e?.rect || {};
      const x = Number(rect?.x || 0);
      const y = Number(rect?.y || 0);
      const w = Number(rect?.width || 0);
      const h = Number(rect?.height || 0);
      const cx = Math.round(x + w / 2);
      const cy = Math.round(y + h / 2);
      return {
        id: `e${i + 1}`,
        kind: String(e?.kind || 'unknown'),
        tag: String(e?.tag || ''),
        role: String(e?.role || ''),
        text: String(e?.text || ''),
        ariaLabel: String(e?.ariaLabel || ''),
        placeholder: String(e?.placeholder || ''),
        nameAttr: String(e?.nameAttr || ''),
        idAttr: String(e?.idAttr || ''),
        href: String(e?.href || ''),
        typeAttr: String(e?.typeAttr || ''),
        rect: { x, y, width: w, height: h },
        center: { x: cx, y: cy },
      };
    });

    const boxes = elements.slice(0, 350).map((e: any) => ({
      x: e.rect.x,
      y: e.rect.y,
      width: e.rect.width,
      height: e.rect.height,
      label: `${e.id}:${e.kind}`,
    }));
    broadcastBrowserEvent(sid, { type: 'highlight_boxes', ts: now(), boxes } as any);

    return { url, viewport, elements };
  } catch {
    return null;
  }
}

function plannedFromUnknown(r: any): Planned | null {
  if (!r || typeof r !== 'object') return null;

  const input = (r as any).input;
  if (input && typeof input === 'object' && Array.isArray((input as any).actions)) {
    return { actions: (input as any).actions };
  }

  if (String((r as any).name || '') === 'echo') {
    const text =
      typeof input === 'string'
        ? input
        : typeof input?.text === 'string'
          ? input.text
          : typeof (r as any)?.text === 'string'
            ? (r as any).text
            : '';
    const jsonLike = extractJsonLike(text);
    if (!jsonLike) return null;
    try {
      const parsed = JSON.parse(jsonLike);
      if (parsed && typeof parsed === 'object' && Array.isArray((parsed as any).actions)) {
        return { actions: (parsed as any).actions };
      }
    } catch { }
  }

  return null;
}

function fallbackActionsFromInstruction(text: string): Planned['actions'] {
  const s = String(text || '').trim();
  if (!s) return [];

  const actions: Planned['actions'] = [];

  const wantsLogin =
    /(login|log\s*in|sign\s*in|signin|تسجيل\s*الدخول|سجل\s*دخول|سجّل\s*دخول|دخول|تسجيل|ولوج|لوج\s*ان|لوجن|ساين\s*ان|ساين|ساين-?إن)/i.test(
      s,
    );
  const wantsYahoo = /(yahoo|ياهو)/i.test(s);
  const wantsOpenAI = /(open\s*a\s*i|open\s*ai|openai|اوبن\s*اي\s*اي|اوبن\s*اي)/i.test(s);
  const wantsPricing = /(price|pricing|سعر|الاسعار|الأسعار|تكلفة|cost)/i.test(s);
  const wantsMicrosoft = /(microsoft|مايكروسوفت|مايكروسوت)/i.test(s);
  const wantsRender = /(render\.com|\brender\b|ريندر)/i.test(s);
  const wantsGithub = /(github|جيتهاب|قيتهب|كتهاب|كيتهاب)/i.test(s);
  const wantsYoutube = /(youtube|يوتيوب)/i.test(s);
  const wantsX = /(x\.com|\btwitter\b|تويتر)/i.test(s);
  const wantsFacebook = /(facebook|فيس\s*بوك|الفيس\s*بوك)/i.test(s);
  const wantsLinkedIn = /(linkedin|لينكد\s*ان|لينكدإن)/i.test(s);
  const wantsExplicitGoogle =
    /(google|جوجل)/i.test(s) || /(ابحث|بحث|search|find|lookup)\s+(?:في|على|ب)\s*(?:google|جوجل)/i.test(s);
  const hasSearchIntent = /(ابحث|بحث|search|find|lookup)/i.test(s);

  if (wantsExplicitGoogle && hasSearchIntent) {
    const queryMatch = s.match(/(?:search|find|lookup|research|بحث|عن|for)\s+["'“”]?([^"“”']+)["'“”]?/i);
    if (queryMatch && queryMatch[1]) {
      const q = encodeURIComponent(queryMatch[1].trim());
      actions.push({ type: 'goto', url: `https://www.google.com/search?q=${q}` });
      return actions;
    }
  }

  const url =
    extractUrl(s) ||
    (wantsOpenAI
      ? wantsPricing
        ? 'https://openai.com/pricing'
        : 'https://platform.openai.com/'
      : wantsRender
        ? 'https://render.com'
        : wantsMicrosoft
          ? 'https://www.microsoft.com'
          : wantsGithub
            ? 'https://github.com'
            : wantsYoutube
              ? 'https://www.youtube.com'
              : wantsX
                ? 'https://x.com'
                : wantsFacebook
                  ? 'https://www.facebook.com'
                  : wantsLinkedIn
                    ? 'https://www.linkedin.com'
                    : wantsYahoo
                      ? 'https://www.yahoo.com'
                      : wantsExplicitGoogle
                        ? 'https://www.google.com'
                        : null);
  if (url) actions.push({ type: 'goto', url });

  const clickMatches = [
    ...Array.from(s.matchAll(/\b(?:click|tap|press)\s+(?:on\s+)?["“”']?([^"“”'\n\r]+)["“”']?/gi)),
    ...Array.from(
      s.matchAll(
        /(?:بالضغط\s+على|اضغط\s+على|انقر\s+على|انقر|اضغط|دوس|اكبس|كبس|كبّس|كليك|اضغطلي)\s+["“”']?([^"“”'\n\r]+)["“”']?/gi,
      ),
    ),
  ];
  for (const m of clickMatches) {
    const label = String(m?.[1] || '')
      .trim()
      .replace(/^(?:ال)?زر\s+/i, '')
      .replace(/^(?:على|علي)\s+/, '')
      .replace(/^(?:the\s+)?button\s+/i, '')
      .replace(/[)\].,;:!?]+$/g, '')
      .trim();
    if (!label) continue;
    actions.push({ type: 'click', text: label });
  }

  const typeMatches = [
    ...Array.from(s.matchAll(/\b(?:type|write|enter|input|paste)\s+["“”']([^"“”']+)["“”']/gi)),
    ...Array.from(s.matchAll(/(?:اكتب|اكتبلي|ادخل|أدخل|حط|املأ|عبّي|عبئ)\s+["“”']([^"“”']+)["“”']/gi)),
  ];
  for (const m of typeMatches) {
    const val = String(m?.[1] || '');
    if (!val) continue;
    actions.push({ type: 'type', text: val });
  }

  const wantsUiAudit =
    /(audit|ui\s*audit|لقطة|صورة|سكرين|screenshot|فحص|عاين|اعرض|عرض)/i.test(s) &&
    !/(click|type|scroll|assert|انقر|اضغط|اكتب|تمرير|تحقق)/i.test(s);

  if (actions.length >= 2 && actions[0]?.type === 'goto') {
    const second = actions[1] as any;
    if (!second || String(second.type || '') !== 'wait') {
      actions.splice(1, 0, { type: 'wait', ms: cfg.defaultWaitMs });
    }
  }

  if (wantsYahoo && wantsLogin) {
    const base: Planned['actions'] = [];
    base.push({ type: 'goto', url: 'https://www.yahoo.com' });
    base.push({ type: 'wait', ms: cfg.defaultWaitMs });
    base.push({ type: 'click', selector: 'a[href*="login.yahoo.com"]', optional: true });
    base.push({ type: 'click', selector: 'a[href*="signin"],a[href*=\"sign-in\"],a[href*=\"sign_in\"]', optional: true });
    base.push({ type: 'click', text: 'Sign in', optional: true });
    base.push({ type: 'click', text: 'Log in', optional: true });
    base.push({ type: 'click', text: 'تسجيل الدخول', optional: true });
    base.push({ type: 'wait', ms: cfg.shortWaitMs, optional: true });
    base.push({ type: 'assert', selector: '#login-username, input[name=\"username\"], input#login-username' });
    return base;
  }

  if (wantsGithub && wantsLogin) {
    const base: Planned['actions'] = [];
    base.push({ type: 'goto', url: 'https://github.com/login' });
    base.push({ type: 'wait', ms: cfg.defaultWaitMs });
    base.push({ type: 'assert', selector: 'input#login_field, input[name="login"], input[autocomplete="username"]' });
    base.push({ type: 'type', text: '{{SECRET:JOE_LOGIN_EMAIL}}' });
    base.push({ type: 'type', text: '{{SECRET:JOE_LOGIN_PASSWORD}}' });
    base.push({
      type: 'click',
      selector: 'input[type="submit"][name="commit"], button[type="submit"]:has-text("Sign in"), button:has-text("Sign in")',
    });
    base.push({ type: 'wait', ms: cfg.longWaitMs });
    base.push({ type: 'ui_audit', optional: true });
    return base;
  }

  if (wantsLogin) {
    actions.push({ type: 'click', text: 'Sign in', optional: true });
    actions.push({ type: 'click', text: 'Log in', optional: true });
    actions.push({ type: 'click', text: 'تسجيل الدخول', optional: true });
    actions.push({ type: 'click', text: 'تسجيل دخول', optional: true });
    actions.push({ type: 'wait', ms: cfg.shortWaitMs, optional: true });
    actions.push({ type: 'type', text: '{{SECRET:JOE_LOGIN_EMAIL}}', optional: true });
    actions.push({ type: 'type', text: '{{SECRET:JOE_LOGIN_PASSWORD}}', optional: true });
    actions.push({ type: 'click', selector: 'button[type="submit"], input[type="submit"]', optional: true });
    actions.push({ type: 'click', text: 'Sign in', optional: true });
    actions.push({ type: 'click', text: 'Log in', optional: true });
    actions.push({ type: 'click', text: 'تسجيل الدخول', optional: true });
    actions.push({ type: 'wait', ms: cfg.longWaitMs, optional: true });
    actions.push({ type: 'ui_audit', optional: true });
    return actions;
  }

  if (wantsUiAudit) actions.push({ type: 'ui_audit' });

  if (actions.length === 0) return [{ type: 'ui_audit' }];
  if (hasSearchIntent && !wantsExplicitGoogle && actions.length === 1 && actions[0]?.type === 'goto') return actions;
  return actions;
}

function extractUrl(text: string) {
  const t = String(text || '').trim();
  if (!t) return null;

  const direct = t.match(/https?:\/\/[^\s"'<>]+/i)?.[0];
  if (direct) return direct;

  const www = t.match(/\bwww\.[^\s"'<>]+\b/i)?.[0];
  if (www) return `https://${www}`;

  const m = t.match(/\b[a-z0-9][a-z0-9-]{0,62}(?:\.[a-z0-9-]{1,63})+\b(?:\/[^\s"'<>]*)?/i);
  if (!m) return null;
  return `https://${m[0]}`;
}

function shouldFastOpen(text: string) {
  const s = String(text || '').trim();
  if (!s) return false;
  const hasOtherSteps =
    /(click|type|scroll|assert|انقر|اضغط|اكتب|تمرير|تحقق|login|log\s*in|sign\s*in|signin|تسجيل\s*الدخول|سجل\s*دخول|سجّل\s*دخول)/i.test(
      s,
    );
  if (hasOtherSteps) return false;
  const hasOpenKeyword = /(افتح|افتحي|افتحوا|اذهب|زيارة|open|go to|visit)/i.test(s);
  const u = extractUrl(s);
  if (!u) return false;
  if (hasOpenKeyword) return true;
  if (s === u) return true;
  if (s.toLowerCase() === u.toLowerCase()) return true;
  return false;
}

function classifyBrowserRuntimeError(e: any) {
  const msg = String(e?.message || e || '').trim();
  const lower = msg.toLowerCase();
  if (/executable doesn't exist|playwright install/i.test(msg)) return { code: 'chromium_missing', message: msg };
  if (/no such file or directory/i.test(msg) && /chrome|chromium/i.test(lower)) return { code: 'chromium_missing', message: msg };
  if (/target page, context or browser has been closed/i.test(msg)) return { code: 'browser_closed', message: msg };
  if (/xvfb|display|cannot open display|missing x server/i.test(lower)) return { code: 'display_missing', message: msg };
  if (/sandbox|setuid/i.test(lower)) return { code: 'sandbox_blocked', message: msg };
  if (/glibc|gtk|nss|gbm|fontconfig/i.test(lower)) return { code: 'deps_missing', message: msg };
  return { code: 'browser_failed', message: msg || 'browser_failed' };
}

function shouldCloseAfterRun() {
  const raw = process.env.BROWSER_CLOSE_AFTER_RUN;
  if (raw === undefined) return false; // Default to FALSE to keep sessions alive
  const s = String(raw).trim().toLowerCase();
  return ['1', 'true', 'yes', 'y', 'on'].includes(s);
}

export async function runBrowserInstruction(params: {
  userId: string;
  sessionId: string;
  instructionText: string;
}) {
  const userId = String(params.userId || '').trim();
  const sessionId = String(params.sessionId || '').trim();
  const instructionTextRaw = String(params.instructionText || '').trim();

  if (!userId) throw new Error('userId_required');
  if (!sessionId) throw new Error('sessionId_required');
  if (!instructionTextRaw) throw new Error('instructionText_required');

  let instructionText = instructionTextRaw;
  try {
    const r = rewriteInlineLoginCredentialsToSecrets(instructionTextRaw);
    if (r.ok) {
      if (r.email) setSessionSecretEncrypted(sessionId, 'JOE_LOGIN_EMAIL', r.email, 60 * 60);
      if (r.password) setSessionSecretEncrypted(sessionId, 'JOE_LOGIN_PASSWORD', r.password, 60 * 60);
      instructionText = String(r.sanitizedText || instructionTextRaw).trim();
    }
  } catch { }

  const secretsCheck = await resolveSecretsInText(userId, sessionId, instructionText);
  if (!secretsCheck.ok) {
    const msg = `missing_secrets: ${secretsCheck.missing.join(', ')}`;
    const ev: BrowserWsEvent = {
      type: 'final_report',
      ts: now(),
      ok: false,
      summary: msg,
      steps: [],
      evidence: [],
    };
    broadcastBrowserEvent(sessionId, ev);
    broadcastBrowserEvent(sessionId, { type: 'final_failed', ts: now(), summary: msg, reason: 'missing_secrets' });
    return { ok: false as const, error: 'missing_secrets', missingSecrets: secretsCheck.missing };
  }


  const safeInstruction = redactSecretsFromString(instructionText);
  const closeAfterRun = shouldCloseAfterRun();
  const debugBase = {
    instruction: safeInstruction,
    compiled_plan_json: null as any,
    actions_json: null as any,
    action_count: 0,
    stop_reason: '',
  };
  const allowDebugSnapshot = (() => {
    const raw = String(process.env.BROWSER_DEBUG_SNAPSHOT || '').trim().toLowerCase();
    return ['1', 'true', 'yes', 'y', 'on'].includes(raw);
  })();
  const emitDebugSnapshot = () => {
    if (!allowDebugSnapshot) return;
    try {
      broadcastBrowserEvent(sessionId, {
        type: 'debug_snapshot',
        ts: now(),
        compiledPlanJson: debugBase.compiled_plan_json,
        actionsJson: debugBase.actions_json,
        actionCount: Number(debugBase.action_count || 0),
        stopReason: String(debugBase.stop_reason || ''),
      } as any);
    } catch { }
  };

  if (shouldFastOpen(safeInstruction)) {
    const url = extractUrl(safeInstruction);
    if (url) {
      debugBase.compiled_plan_json = [{ type: 'goto' }, { type: 'wait' }];
      debugBase.actions_json = deepRedactForDebug([{ type: 'goto', url }, { type: 'wait', ms: 450 }]);
      debugBase.action_count = 2;
      debugBase.stop_reason = 'fast_open';
      try {
        const exec = await executePlannedActions({
          userId,
          sessionId,
          actions: [{ type: 'goto', url }, { type: 'wait', ms: 450 }] as any,
        });
        if (closeAfterRun) {
          try { await stopSession(sessionId); } catch { }
        }
        emitDebugSnapshot();
        return { ok: true as const, result: exec, debug: debugBase };
      } catch (e: any) {
        const c = classifyBrowserRuntimeError(e);
        try { await stopSession(sessionId); } catch { }
        const ev: BrowserWsEvent = {
          type: 'final_report',
          ts: now(),
          ok: false,
          summary: `${c.code}: ${c.message}`.slice(0, 600),
          steps: [],
          evidence: [],
        };
        broadcastBrowserEvent(sessionId, ev);
        broadcastBrowserEvent(sessionId, { type: 'final_failed', ts: now(), summary: ev.summary, reason: String(c.code || 'browser_unavailable') });
        debugBase.stop_reason = String(c.code || 'browser_unavailable');
        emitDebugSnapshot();
        return { ok: false as const, error: 'browser_unavailable', detail: c, debug: debugBase };
      }
    }
  }

  let planned: Planned | null = null;
  let compilerUsed = false;
  try {
    const runCfg = getSessionRunConfig(sessionId);
    const providerKey = String(runCfg?.provider || '').trim().toLowerCase();
    const provider = providerKey && providerKey !== 'llm' ? providerKey : 'openai';
    const wantsGrounding =
      /(click|type|scroll|assert|انقر|اضغط|اكتب|تمرير|تحقق|login|log\s*in|sign\s*in|signin|تسجيل\s*الدخول|سجل\s*دخول|سجّل\s*دخول|ابحث|بحث|search|find|lookup)/i.test(
        safeInstruction,
      );
    const navUrl = extractUrl(safeInstruction);
    const hasOpenKeyword = /(افتح|افتحي|افتحوا|اذهب|زيارة|open|go to|visit)/i.test(safeInstruction);
    if (wantsGrounding && navUrl && hasOpenKeyword) {
      try {
        const s = await getBrowserSession(sessionId);
        touchSession(sessionId);
        await s.page.goto(navUrl, { waitUntil: 'domcontentloaded', timeout: cfg.navTimeoutMs });
        await s.page.waitForTimeout(350);
      } catch { }
    }
    const grounding = wantsGrounding ? await collectUiGroundingSnapshot(sessionId) : null;
    let screenshotBase64: string | null = null;
    if (wantsGrounding) {
      try {
        const buf = await screenshotSessionJpeg(sessionId, { quality: 40, timeoutMs: 3000 });
        screenshotBase64 = buf.toString('base64');
      } catch { }
    }

    const groundingJson = grounding ? (() => { try { return JSON.stringify(grounding); } catch { return ''; } })() : '';
    const urlBlock = grounding?.url ? `\n\nCURRENT_URL:\n${String(grounding.url).slice(0, 800)}` : '';
    const groundingBlock = groundingJson ? `${urlBlock}\n\nUI_GROUNDING_JSON:\n${groundingJson.slice(0, 24000)}` : urlBlock;

    const userContent: any[] = [{ type: 'text', text: safeInstruction + groundingBlock }];
    if (screenshotBase64) {
      userContent.push({
        type: 'image_url',
        image_url: { url: `data:image/jpeg;base64,${screenshotBase64}` }
      });
    }

    const r = await planNextStep(
      [
        { role: 'system', content: COMPILER_SYSTEM },
        { role: 'user', content: userContent },
      ],
      {
        provider,
        apiKey: runCfg?.apiKey,
        baseUrl: runCfg?.baseUrl,
        model: runCfg?.model,
        userId,
      } as any,
    );
    compilerUsed = true;
    planned = plannedFromUnknown(r);
  } catch {
    planned = null;
  }

  if (planned) {
    planned.actions = planned.actions.slice(0, cfg.maxSteps);
    debugBase.compiled_plan_json = planned.actions.map((a: any) => ({ type: String(a?.type || 'unknown') }));
    debugBase.actions_json = deepRedactForDebug(planned.actions);
    debugBase.action_count = planned.actions.length;
    debugBase.stop_reason = 'compiled';
    const multiStepHint =
      /(click|type|scroll|assert|انقر|اضغط|اكتب|تمرير|تحقق|login|log\s*in|sign\s*in|signin|تسجيل\s*الدخول|سجل\s*دخول|سجّل\s*دخول)/i.test(
        safeInstruction,
      );
    if (multiStepHint && planned.actions.length < 2) {
      const fallback = fallbackActionsFromInstruction(safeInstruction).slice(0, cfg.maxSteps);
      if (fallback.length > planned.actions.length) {
        planned = { actions: fallback };
        debugBase.compiled_plan_json = planned.actions.map((a: any) => ({ type: String(a?.type || 'unknown') }));
        debugBase.actions_json = deepRedactForDebug(planned.actions);
        debugBase.action_count = planned.actions.length;
        debugBase.stop_reason = 'fallback_override';
      }
    }
    const wantsLogin =
      /(login|log\s*in|sign\s*in|signin|تسجيل\s*الدخول|سجل\s*دخول|سجّل\s*دخول|دخول)/i.test(safeInstruction) ||
      /\{\{\s*SECRET\s*:\s*JOE_LOGIN_(?:EMAIL|PASSWORD)\s*\}\}/i.test(safeInstruction);
    const hasTypeOrClick = planned.actions.some((a: any) => {
      const t = String(a?.type || '').toLowerCase();
      return t === 'type' || t === 'click';
    });
    if (wantsLogin && (!hasTypeOrClick || planned.actions.length < 4)) {
      const fallback = fallbackActionsFromInstruction(safeInstruction).slice(0, cfg.maxSteps);
      if (fallback.length > planned.actions.length) {
        planned = { actions: fallback };
        debugBase.compiled_plan_json = planned.actions.map((a: any) => ({ type: String(a?.type || 'unknown') }));
        debugBase.actions_json = deepRedactForDebug(planned.actions);
        debugBase.action_count = planned.actions.length;
        debugBase.stop_reason = 'fallback_override_login';
      }
    }
    if (planned.actions.length === 0) {
      const summary = 'plan_to_actions_empty';
      try {
        broadcastBrowserEvent(sessionId, {
          type: 'action_error',
          ts: now(),
          actionId: 'compiler',
          actionType: 'compiler',
          reason: 'unknown',
          error: summary,
        } as any);
      } catch { }
      const ev: BrowserWsEvent = { type: 'final_report', ts: now(), ok: false, summary, steps: [], evidence: [] };
      broadcastBrowserEvent(sessionId, ev);
      broadcastBrowserEvent(sessionId, { type: 'final_failed', ts: now(), summary, reason: 'plan_to_actions_empty' });
      debugBase.stop_reason = 'plan_to_actions_empty';
      emitDebugSnapshot();
      return { ok: false as const, error: 'plan_to_actions_empty', debug: debugBase };
    }
  }

  if (!planned) {
    const fallback = fallbackActionsFromInstruction(safeInstruction).slice(0, cfg.maxSteps);
    if (fallback.length) {
      planned = { actions: fallback };
      debugBase.compiled_plan_json = planned.actions.map((a: any) => ({ type: String(a?.type || 'unknown') }));
      debugBase.actions_json = deepRedactForDebug(planned.actions);
      debugBase.action_count = planned.actions.length;
      debugBase.stop_reason = compilerUsed ? 'fallback_after_compiler' : 'fallback_no_compiler';
    } else {
      const summary = 'compiler_failed';
      try {
        broadcastBrowserEvent(sessionId, {
          type: 'action_error',
          ts: now(),
          actionId: 'compiler',
          actionType: 'compiler',
          reason: 'unknown',
          error: summary,
        } as any);
      } catch { }
      const ev: BrowserWsEvent = { type: 'final_report', ts: now(), ok: false, summary, steps: [], evidence: [] };
      broadcastBrowserEvent(sessionId, ev);
      broadcastBrowserEvent(sessionId, { type: 'final_failed', ts: now(), summary, reason: 'compiler_failed' });
      debugBase.stop_reason = 'compiler_failed';
      emitDebugSnapshot();
      return { ok: false as const, error: 'compiler_failed', debug: debugBase };
    }
  }

  try {
    const exec = await executePlannedActions({
      userId,
      sessionId,
      actions: planned.actions as any,
    });
    if (closeAfterRun) {
      try { await stopSession(sessionId); } catch { }
    }
    debugBase.stop_reason = debugBase.stop_reason || 'executed';
    emitDebugSnapshot();
    return { ok: true as const, result: exec, debug: debugBase };
  } catch (e: any) {
    const c = classifyBrowserRuntimeError(e);
    try { await stopSession(sessionId); } catch { }
    if (c.code === 'browser_closed') {
      try {
        const exec2 = await executePlannedActions({
          userId,
          sessionId,
          actions: planned.actions as any,
        });
        if (closeAfterRun) {
          try { await stopSession(sessionId); } catch { }
        }
        debugBase.stop_reason = 'browser_closed_retried';
        emitDebugSnapshot();
        return { ok: true as const, result: exec2, debug: debugBase };
      } catch (e2: any) {
        const c2 = classifyBrowserRuntimeError(e2);
        try { await stopSession(sessionId); } catch { }
        const ev2: BrowserWsEvent = {
          type: 'final_report',
          ts: now(),
          ok: false,
          summary: `${c2.code}: ${c2.message}`.slice(0, 600),
          steps: [],
          evidence: [],
        };
        broadcastBrowserEvent(sessionId, ev2);
        broadcastBrowserEvent(sessionId, { type: 'final_failed', ts: now(), summary: ev2.summary, reason: String(c2.code || 'browser_unavailable') });
        debugBase.stop_reason = String(c2.code || 'browser_unavailable');
        emitDebugSnapshot();
        return { ok: false as const, error: 'browser_unavailable', detail: c2, debug: debugBase };
      }
    }
    const ev: BrowserWsEvent = {
      type: 'final_report',
      ts: now(),
      ok: false,
      summary: `${c.code}: ${c.message}`.slice(0, 600),
      steps: [],
      evidence: [],
    };
    broadcastBrowserEvent(sessionId, ev);
    broadcastBrowserEvent(sessionId, { type: 'final_failed', ts: now(), summary: ev.summary, reason: String(c.code || 'browser_unavailable') });
    debugBase.stop_reason = String(c.code || 'browser_unavailable');
    emitDebugSnapshot();
    return { ok: false as const, error: 'browser_unavailable', detail: c, debug: debugBase };
  }
}

import { chromium, type Browser, type BrowserContext, type Page, type Locator, type LaunchOptions } from 'playwright';
import fs from 'fs';
import path from 'path';
import { DEFAULT_BROWSER_CONFIG } from './config';
import { broadcastBrowserEvent } from './wsHub';

type SessionState = {
  browser: Browser;
  context: BrowserContext;
  page: Page;
  allowedOrigin: string | null;
  streaming: boolean;
  streamTimer: NodeJS.Timeout | null;
  maskLocators: Locator[];
  captureLocked: boolean;
  viewport: { w: number; h: number };
  lastUsedAt: number;
};

const sessions = new Map<string, SessionState>();

function broadcastStatus(sessionId: string, s: SessionState, extra?: { workerStatus?: string; blockingReason?: string }) {
  const sid = String(sessionId || '').trim();
  if (!sid) return;
  let url = '';
  try {
    url = s.page.url() || '';
  } catch {
    url = '';
  }
  broadcastBrowserEvent(sid, {
    type: 'session_status',
    ts: Date.now(),
    sessionId: sid,
    url,
    workerStatus: (extra?.workerStatus || 'idle') as any,
    blockingReason: extra?.blockingReason as any,
  });
}

function parseBool(raw: string | undefined) {
  if (raw === undefined) return undefined;
  const s = String(raw).trim().toLowerCase();
  if (['1', 'true', 'yes', 'y', 'on'].includes(s)) return true;
  if (['0', 'false', 'no', 'n', 'off'].includes(s)) return false;
  return undefined;
}

function parseViewport(raw: string | undefined) {
  const fallback = { w: 1280, h: 720 };
  if (!raw) return fallback;
  const m = String(raw).trim().match(/^(\d{2,5})\s*[x,]\s*(\d{2,5})$/i);
  if (!m) return fallback;
  const w = Math.max(320, Math.min(3840, Number(m[1])));
  const h = Math.max(240, Math.min(2160, Number(m[2])));
  if (!Number.isFinite(w) || !Number.isFinite(h)) return fallback;
  return { w, h };
}

export function getBrowserViewport() {
  return parseViewport(process.env.BROWSER_VIEWPORT);
}

export function getChromiumLaunchOptions(): LaunchOptions {
  const headlessEnv = parseBool(process.env.BROWSER_HEADLESS);
  const headedEnv = parseBool(process.env.BROWSER_HEADED) ?? parseBool(process.env.BROWSER_HEADFUL);
  const headless = headlessEnv !== undefined ? headlessEnv : headedEnv ? false : true;

  const args: string[] = [
    '--disable-dev-shm-usage',
    '--disable-gpu',
    '--disable-background-timer-throttling',
    '--disable-backgrounding-occluded-windows',
    '--disable-renderer-backgrounding',
    '--use-gl=swiftshader',
    '--use-angle=swiftshader',
  ];
  const noSandbox = parseBool(process.env.BROWSER_NO_SANDBOX) ?? parseBool(process.env.BROWSER_DISABLE_SANDBOX);
  if (noSandbox) args.push('--no-sandbox', '--disable-setuid-sandbox');

  return { headless, args };
}

function sleep(ms: number) {
  return new Promise<void>((resolve) => setTimeout(resolve, ms));
}

async function tryAcquireCaptureLock(s: SessionState, wait: boolean, timeoutMs: number) {
  const startedAt = Date.now();
  while (s.captureLocked) {
    if (!wait) return false;
    if (Date.now() - startedAt > timeoutMs) return false;
    await sleep(50);
  }
  s.captureLocked = true;
  return true;
}

async function captureJpeg(
  s: SessionState,
  opts: { quality: number; timeoutMs: number; mask?: Locator[]; waitForLock: boolean },
) {
  const locked = await tryAcquireCaptureLock(s, opts.waitForLock, opts.timeoutMs);
  if (!locked) return null;
  try {
    return await s.page.screenshot({
      type: 'jpeg',
      quality: opts.quality,
      animations: 'disabled',
      timeout: opts.timeoutMs,
      mask: opts.mask && opts.mask.length ? opts.mask : undefined,
    });
  } finally {
    s.captureLocked = false;
  }
}

export async function screenshotSessionJpeg(sessionId: string, opts?: { quality?: number; timeoutMs?: number }) {
  const sid = String(sessionId || '').trim();
  const s = await getBrowserSession(sid);
  const quality = Math.max(1, Math.min(100, Number(opts?.quality ?? 55)));
  const timeoutMs = Math.max(1000, Number(opts?.timeoutMs ?? 60000));
  const buf = await captureJpeg(s, { quality, timeoutMs, waitForLock: true });
  if (!buf) throw new Error('screenshot_failed');
  return buf;
}

let activeRuns = 0;
const runWaiters: Array<() => void> = [];

export async function withBrowserConcurrency<T>(fn: () => Promise<T>) {
  const max = Math.max(1, Math.min(8, Number(process.env.BROWSER_MAX_CONCURRENCY || 1)));
  if (activeRuns >= max) {
    await new Promise<void>((resolve) => runWaiters.push(resolve));
  }
  activeRuns += 1;
  try {
    return await fn();
  } finally {
    activeRuns -= 1;
    const next = runWaiters.shift();
    if (next) next();
  }
}

export function touchSession(sessionId: string) {
  const sid = String(sessionId || '').trim();
  const s = sessions.get(sid);
  if (!s) return;
  s.lastUsedAt = Date.now();
}

let cleanupTimer: NodeJS.Timeout | null = null;
function ensureCleanupLoop() {
  if (cleanupTimer) return;
  const tickMs = 60_000;
  cleanupTimer = setInterval(() => {
    const idleMs = Math.max(60_000, Number(process.env.BROWSER_IDLE_TIMEOUT_MS || 900_000));
    const cutoff = Date.now() - idleMs;
    for (const [sid, s] of sessions.entries()) {
      if (s.lastUsedAt < cutoff) {
        void stopSession(sid);
      }
    }
  }, tickMs);
  try {
    (cleanupTimer as any).unref?.();
  } catch { }
}

export async function createSession(sessionId: string) {
  const cfg = DEFAULT_BROWSER_CONFIG;
  const viewport = getBrowserViewport();

  let browser: Browser;
  /* MODIFIED: Logging and Fallback */
  let wsEndpoint = process.env.BROWSER_WS_ENDPOINT || '';

  try {
    const logPath = path.join(__dirname, '../stream_debug.log');
    fs.appendFileSync(logPath, `[createSession] Env WS: '${wsEndpoint}'\n`);
  } catch (e) { }

  if (!wsEndpoint) {
    // No WS endpoint provided, will attempt local launch
  }

  const apiKey = process.env.WORKER_API_KEY || '';

  if (wsEndpoint) {
    // Determine connection URL (with auth if needed)
    // If wsEndpoint is the base URL (http://host:port), we might need to fetch the WS URL first or use connect({ wsEndpoint }) if it's direct.
    // However, playwright expects a direct WS url. 
    // Usually browser-worker returns { wsEndpoint: '...' } on start. But usually we want a persistent connection.
    // If the worker exposes `ws://host:port`, we use that.

    // Assuming standard Playwright server or compatible wrapper
    // If we have an API key, we might need to pass it in headers.
    browser = await chromium.connect(wsEndpoint, {
      headers: apiKey ? { 'Authorization': `Bearer ${apiKey}` } : undefined
    });
  } else {
    browser = await chromium.launch(getChromiumLaunchOptions());
  }

  const context = await browser.newContext({
    viewport: { width: viewport.w, height: viewport.h },
    locale: 'ar',
  });
  context.setDefaultNavigationTimeout(cfg.navTimeoutMs);
  context.setDefaultTimeout(cfg.actionTimeoutMs);
  const page = await context.newPage();

  const state: SessionState = {
    browser,
    context,
    page,
    allowedOrigin: null,
    streaming: false,
    streamTimer: null,
    maskLocators: [],
    captureLocked: false,
    viewport,
    lastUsedAt: Date.now(),
  };

  page.on('framenavigated', (frame) => {
    if (frame !== page.mainFrame()) return;
    try {
      broadcastStatus(sessionId, state, { workerStatus: 'idle' });
    } catch { }
    try {
      const u = new URL(frame.url());
      const origin = u.origin;
      if (!state.allowedOrigin) {
        state.allowedOrigin = origin;
        return;
      }
      if (DEFAULT_BROWSER_CONFIG.strictSameSite && origin !== state.allowedOrigin) {
        broadcastBrowserEvent(sessionId, {
          type: 'goto_blocked',
          stepId: 'policy',
          ts: Date.now(),
          url: frame.url(),
          reason: 'same_site_blocked',
          message: 'cross_site_navigation_blocked',
        });
        try {
          broadcastStatus(sessionId, state, { workerStatus: 'idle', blockingReason: 'same_site_blocked' });
        } catch { }
        try {
          void page.goBack({ waitUntil: 'domcontentloaded' });
        } catch { }
      }
    } catch { }
  });

  try {
    broadcastStatus(sessionId, state, { workerStatus: 'idle' });
  } catch { }

  return state;
}

export async function getBrowserSession(sessionId: string) {
  const sid = String(sessionId || '').trim();
  if (!sid) throw new Error('sessionId_required');
  const existing = sessions.get(sid);
  if (existing) {
    existing.lastUsedAt = Date.now();
    ensureCleanupLoop();
    return existing;
  }
  const created = await createSession(sid);
  sessions.set(sid, created);
  ensureCleanupLoop();
  return created;
}

export function setStreamMask(sessionId: string, maskLocators: Locator[]) {
  const sid = String(sessionId || '').trim();
  const s = sessions.get(sid);
  if (!s) return;
  s.maskLocators = Array.isArray(maskLocators) ? maskLocators : [];
  s.lastUsedAt = Date.now();
}

export function startStreaming(sessionId: string) {
  const sid = String(sessionId || '').trim();
  const s = sessions.get(sid);
  if (!s) return;
  if (s.streaming) return;
  s.streaming = true;
  s.lastUsedAt = Date.now();
  try {
    broadcastStatus(sid, s, { workerStatus: 'idle' });
  } catch { }
  const cfg = DEFAULT_BROWSER_CONFIG;
  const intervalMs = Math.max(50, Math.floor(1000 / Math.max(1, cfg.streamFps)));
  s.streamTimer = setInterval(async () => {
    if (!s.streaming) return;
    try {
      const buf = await captureJpeg(s, {
        quality: 55,
        timeoutMs: Math.max(1000, Math.min(8000, cfg.actionTimeoutMs)),
        waitForLock: false,
        mask: s.maskLocators.length ? s.maskLocators : undefined,
      });

      // DEBUG LOGGING
      try {
        const logPath = path.join(__dirname, '../stream_debug.log');
        const msg = `[${new Date().toISOString()}] SID=${sid} Streaming Loop. Buf? ${!!buf} Len=${buf?.length}\n`;
        fs.appendFileSync(logPath, msg);
      } catch (e) { }

      if (!buf) return;
      broadcastBrowserEvent(sid, {
        type: 'stream_frame',
        ts: Date.now(),
        jpegBase64: Buffer.from(buf).toString('base64'),
        w: s.viewport.w,
        h: s.viewport.h,
      });
      s.lastUsedAt = Date.now();
    } catch { }
  }, intervalMs);
}

export function stopStreaming(sessionId: string) {
  const sid = String(sessionId || '').trim();
  const s = sessions.get(sid);
  if (!s) return;
  s.streaming = false;
  if (s.streamTimer) {
    try { clearInterval(s.streamTimer); } catch { }
    s.streamTimer = null;
  }
  try {
    broadcastStatus(sid, s, { workerStatus: 'idle' });
  } catch { }
}

export async function stopSession(sessionId: string) {
  const sid = String(sessionId || '').trim();
  const s = sessions.get(sid);
  if (!s) return;
  sessions.delete(sid);
  s.streaming = false;
  if (s.streamTimer) {
    try { clearInterval(s.streamTimer); } catch { }
    s.streamTimer = null;
  }
  try { await s.context.close(); } catch { }
  try { await s.browser.close(); } catch { }
}

export async function healthcheckBrowser() {
  const startedAt = Date.now();
  const viewport = getBrowserViewport();
  const browser = await chromium.launch(getChromiumLaunchOptions());
  try {
    const context = await browser.newContext({ viewport: { width: viewport.w, height: viewport.h } });
    try {
      const page = await context.newPage();
      const url = 'https://example.com';
      await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 20000 });
      const buf = await page.screenshot({ type: 'jpeg', quality: 65, animations: 'disabled' });
      const artifactDir = process.env.ARTIFACT_DIR || '/tmp/joe-artifacts';
      try {
        if (!fs.existsSync(artifactDir)) fs.mkdirSync(artifactDir, { recursive: true });
      } catch { }
      const fname = `health-browser-${Date.now()}.jpg`;
      const full = path.join(artifactDir, fname);
      try {
        fs.writeFileSync(full, buf);
      } catch { }
      const href = `/artifacts/${encodeURIComponent(fname)}`;
      return { ok: true as const, ms: Date.now() - startedAt, url, screenshotHref: href };
    } finally {
      try { await context.close(); } catch { }
    }
  } finally {
    try { await browser.close(); } catch { }
  }
  return { ok: true as const, ms: Date.now() - startedAt };
}

/**
 * Advanced Browser Interactions
 * =============================
 * 
 * نظام متقدم للتفاعلات الطبيعية والموشر الذكي
 * يحاكي سلوك الإنسان الحقيقي
 */

import { EventEmitter } from 'events';
import { Page } from 'playwright';

/**
 * بنية التفاعل
 */
export interface Interaction {
  type: 'click' | 'hover' | 'scroll' | 'type' | 'select' | 'drag' | 'focus' | 'blur';
  target: string;
  value?: string;
  duration?: number;
  delay?: number;
  timestamp: number;
}

/**
 * بنية الحركة الطبيعية
 */
export interface NaturalMovement {
  startX: number;
  startY: number;
  endX: number;
  endY: number;
  duration: number;
  curve: 'linear' | 'ease' | 'ease-in' | 'ease-out' | 'ease-in-out' | 'bezier';
  jitter: number; // درجة الارتجاج الطبيعية
}

/**
 * نظام التفاعلات المتقدمة
 */
export class AdvancedInteractionSystem extends EventEmitter {
  private interactions: Interaction[] = [];
  private mouseVelocity: { x: number; y: number } = { x: 0, y: 0 };
  private lastMousePosition: { x: number; y: number } = { x: 0, y: 0 };
  private interactionDelay: number = 100; // تأخير طبيعي بين التفاعلات
  private humanBehavior: boolean = true; // محاكاة السلوك البشري

  constructor() {
    super();
  }

  /**
   * حركة موشر طبيعية مع منحنى بيزيه
   */
  async naturalMouseMove(
    page: Page,
    startX: number,
    startY: number,
    endX: number,
    endY: number,
    duration: number = 500
  ): Promise<void> {
    this.emit('log', `🖱️ Natural mouse move from (${startX}, ${startY}) to (${endX}, ${endY})`);

    const steps = Math.ceil(duration / 16); // 60 FPS
    const deltaX = endX - startX;
    const deltaY = endY - startY;

    for (let i = 0; i <= steps; i++) {
      const progress = i / steps;

      // منحنى بيزيه للحركة الطبيعية
      const easeProgress = this.easeInOutCubic(progress);

      // إضافة ارتجاج طبيعي
      const jitter = this.humanBehavior ? (Math.random() - 0.5) * 2 : 0;

      const currentX = startX + deltaX * easeProgress + jitter;
      const currentY = startY + deltaY * easeProgress + jitter;

      this.mouseVelocity = {
        x: currentX - this.lastMousePosition.x,
        y: currentY - this.lastMousePosition.y
      };

      this.lastMousePosition = { x: currentX, y: currentY };

      try {
        await page.mouse.move(currentX, currentY);
      } catch (e) { }

      this.emit('mouse-move', {
        x: currentX,
        y: currentY,
        velocity: this.mouseVelocity,
        progress: easeProgress
      });

      await this.sleep(16);
    }

    this.emit('log', `✅ اكتملت الحركة الطبيعية`);
  }

  /**
   * نقر طبيعي مع تأخير
   */
  async naturalClick(
    page: Page,
    selector: string,
    x: number,
    y: number,
    options: {
      delay?: number;
      doubleClick?: boolean;
      rightClick?: boolean;
    } = {}
  ): Promise<void> {
    const { delay = 100, doubleClick = false, rightClick = false } = options;

    this.emit('log', `🖱️ نقر طبيعي على ${selector}`);

    // Move execution
    await this.naturalMouseMove(
      page,
      this.lastMousePosition.x,
      this.lastMousePosition.y,
      x,
      y,
      300
    );

    // Natural delay before click
    await this.sleep(delay);

    // Actual Playwright click
    try {
      if (rightClick) await page.mouse.click(x, y, { button: 'right' });
      else await page.mouse.click(x, y, { clickCount: doubleClick ? 2 : 1 });
    } catch { }

    this.emit('click', {
      selector,
      x,
      y,
      button: rightClick ? 'right' : 'left',
      doubleClick
    });

    if (doubleClick) {
      await this.sleep(100);
      // Already handled by clickCount above, but for event parity:
      this.emit('click', {
        selector,
        x,
        y,
        button: rightClick ? 'right' : 'left',
        doubleClick: true
      });
    }

    this.interactions.push({
      type: 'click',
      target: selector,
      timestamp: Date.now()
    });

    this.emit('log', `✅ اكتمل النقر الطبيعي`);
  }

  /**
   * كتابة نصية طبيعية مع تأخيرات عشوائية
   */
  async naturalType(
    page: Page,
    selector: string,
    text: string,
    options: {
      minDelay?: number;
      maxDelay?: number;
      typos?: number; // نسبة الأخطاء الطباعية
    } = {}
  ): Promise<void> {
    const { minDelay = 30, maxDelay = 150, typos = 0 } = options;

    this.emit('log', `⌨️ كتابة طبيعية: "${text}"`);

    for (let i = 0; i < text.length; i++) {
      const char = text[i];

      // Random typos simulation
      if (typos > 0 && Math.random() < typos) {
        const wrongChar = String.fromCharCode(char.charCodeAt(0) + 1);
        try { await page.keyboard.type(wrongChar); } catch { }
        this.emit('type', {
          selector,
          character: wrongChar,
          isTypo: true
        });
        await this.sleep(this.randomDelay(minDelay, maxDelay));

        // Correction
        try { await page.keyboard.press('Backspace'); } catch { }
        this.emit('backspace', { selector });
        await this.sleep(100);
      }

      try { await page.keyboard.type(char); } catch { }
      this.emit('type', {
        selector,
        character: char,
        progress: ((i + 1) / text.length) * 100
      });

      // Random natural delay
      const delay = this.randomDelay(minDelay, maxDelay);
      await this.sleep(delay);
    }

    this.interactions.push({
      type: 'type',
      target: selector,
      value: text,
      timestamp: Date.now()
    });

    this.emit('log', `✅ اكتملت الكتابة الطبيعية`);
  }

  /**
   * التمرير الطبيعي
   */
  async naturalScroll(
    direction: 'up' | 'down',
    amount: number = 300,
    duration: number = 500
  ): Promise<void> {
    this.emit('log', `📜 تمرير طبيعي ${direction === 'down' ? 'لأسفل' : 'لأعلى'}`);

    const steps = Math.ceil(duration / 16);
    const deltaScroll = direction === 'down' ? amount : -amount;

    for (let i = 0; i <= steps; i++) {
      const progress = i / steps;
      const easeProgress = this.easeInOutCubic(progress);
      const currentScroll = deltaScroll * easeProgress;

      this.emit('scroll', {
        direction,
        amount: Math.abs(currentScroll),
        progress: easeProgress
      });

      await this.sleep(16);
    }

    this.interactions.push({
      type: 'scroll',
      target: 'window',
      value: direction,
      timestamp: Date.now()
    });

    this.emit('log', `✅ اكتمل التمرير الطبيعي`);
  }

  /**
   * التحويم على عنصر
   */
  async hover(
    page: Page,
    selector: string,
    x: number,
    y: number,
    duration: number = 500
  ): Promise<void> {
    this.emit('log', `🎯 Hovering on ${selector}`);

    // Move to target
    await this.naturalMouseMove(
      page,
      this.lastMousePosition.x,
      this.lastMousePosition.y,
      x,
      y,
      300
    );

    // Dwell
    await this.sleep(duration);

    try { await page.mouse.move(x, y); } catch { } // Ensure Playwright knows we are there

    this.emit('hover', { selector, x, y });

    this.emit('hover', { selector, x, y });

    this.interactions.push({
      type: 'hover',
      target: selector,
      timestamp: Date.now()
    });

    this.emit('log', `✅ اكتمل التحويم`);
  }

  /**
   * السحب والإفلات
   */
  async dragAndDrop(
    page: Page,
    sourceSelector: string,
    targetSelector: string,
    sourceX: number,
    sourceY: number,
    targetX: number,
    targetY: number
  ): Promise<void> {
    this.emit('log', `🔄 Drag from ${sourceSelector} to ${targetSelector}`);

    // Move to source
    await this.naturalMouseMove(
      page,
      this.lastMousePosition.x,
      this.lastMousePosition.y,
      sourceX,
      sourceY,
      300
    );

    // Mouse down
    try { await page.mouse.down(); } catch { }
    this.emit('mouse-down', { selector: sourceSelector });
    await this.sleep(100);

    // Drag to target
    await this.naturalMouseMove(page, sourceX, sourceY, targetX, targetY, 500);

    // Mouse up
    try { await page.mouse.up(); } catch { }
    this.emit('mouse-up', { selector: targetSelector });

    this.interactions.push({
      type: 'drag',
      target: sourceSelector,
      value: targetSelector,
      timestamp: Date.now()
    });

    this.emit('log', `✅ اكتمل السحب والإفلات`);
  }

  /**
   * التركيز على عنصر
   */
  async focus(selector: string): Promise<void> {
    this.emit('log', `🎯 التركيز على ${selector}`);

    this.emit('focus', { selector });

    this.interactions.push({
      type: 'focus',
      target: selector,
      timestamp: Date.now()
    });

    this.emit('log', `✅ تم التركيز`);
  }

  /**
   * إزالة التركيز
   */
  async blur(selector: string): Promise<void> {
    this.emit('log', `❌ إزالة التركيز من ${selector}`);

    this.emit('blur', { selector });

    this.interactions.push({
      type: 'blur',
      target: selector,
      timestamp: Date.now()
    });

    this.emit('log', `✅ تم إزالة التركيز`);
  }

  /**
   * اختيار من قائمة منسدلة
   */
  async selectOption(
    page: Page,
    selector: string,
    optionValue: string,
    x: number,
    y: number
  ): Promise<void> {
    this.emit('log', `📋 Selecting option: ${optionValue}`);

    // Click dropdown
    await this.naturalClick(page, selector, x, y);
    await this.sleep(300);

    // اختيار الخيار
    this.emit('select', { selector, value: optionValue });

    this.interactions.push({
      type: 'select',
      target: selector,
      value: optionValue,
      timestamp: Date.now()
    });

    this.emit('log', `✅ تم الاختيار`);
  }

  /**
   * منحنى بيزيه للحركة الطبيعية
   */
  private easeInOutCubic(t: number): number {
    return t < 0.5
      ? 4 * t * t * t
      : 1 - Math.pow(-2 * t + 2, 3) / 2;
  }

  /**
   * تأخير عشوائي طبيعي
   */
  private randomDelay(min: number, max: number): number {
    return Math.random() * (max - min) + min;
  }

  /**
   * الانتظار
   */
  private sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  /**
   * الحصول على سجل التفاعلات
   */
  getInteractionHistory(): Interaction[] {
    return [...this.interactions];
  }

  /**
   * مسح السجل
   */
  clearHistory(): void {
    this.interactions = [];
  }

  /**
   * تعيين تأخير التفاعل
   */
  setInteractionDelay(delay: number): void {
    this.interactionDelay = delay;
  }

  /**
   * تفعيل/تعطيل محاكاة السلوك البشري
   */
  setHumanBehavior(enabled: boolean): void {
    this.humanBehavior = enabled;
  }

  /**
   * الحصول على معلومات الموشر
   */
  getMouseInfo(): any {
    return {
      position: this.lastMousePosition,
      velocity: this.mouseVelocity,
      totalInteractions: this.interactions.length
    };
  }
}

/**
 * نسخة مفردة من نظام التفاعلات
 */
export const advancedInteractions = new AdvancedInteractionSystem();

/**
 * Advanced Browser Intelligence
 * Smart page understanding, automatic interaction, and vision capabilities
 */

export interface PageAnalysis {
    url: string;
    title: string;
    pageType: 'form' | 'article' | 'ecommerce' | 'social' | 'search' | 'dashboard' | 'unknown';
    interactiveElements: InteractiveElement[];
    forms: FormElement[];
    articles: ArticleContent[];
    dataExtracts: Record<string, any>;
    screenshot?: string; // Base64 or path
}

export interface InteractiveElement {
    type: 'button' | 'link' | 'input' | 'select' | 'textarea';
    label: string;
    selector: string;
    purpose?: string; // Inferred purpose
    importance: number; // 0-1
}

export interface FormElement {
    action: string;
    method: string;
    fields: Array<{
        name: string;
        type: string;
        label?: string;
        required: boolean;
        placeholder?: string;
    }>;
    submitButton?: string;
}

export interface ArticleContent {
    title: string;
    author?: string;
    date?: string;
    content: string;
    summary?: string;
}

/**
 * Analyze page structure and content
 */
export function analyzePage(html: string, url: string): PageAnalysis {
    // This will be enhanced with actual DOM parsing
    const analysis: PageAnalysis = {
        url,
        title: extractTitle(html),
        pageType: detectPageType(html),
        interactiveElements: extractInteractiveElements(html),
        forms: extractForms(html),
        articles: extractArticles(html),
        dataExtracts: {}
    };

    return analysis;
}

function extractTitle(html: string): string {
    const match = html.match(/<title>(.*?)<\/title>/i);
    return match ? match[1] : 'Untitled';
}

function detectPageType(html: string): PageAnalysis['pageType'] {
    const lower = html.toLowerCase();

    if (/<form/i.test(lower) && (lower.includes('login') || lower.includes('signup') || lower.includes('register'))) {
        return 'form';
    }

    if (/<article/i.test(lower) || /<div[^>]*class="[^"]*article[^"]*"/i.test(lower)) {
        return 'article';
    }

    if (/\b(cart|checkout|product|price|buy|shop)\b/i.test(lower)) {
        return 'ecommerce';
    }

    if (/\b(tweet|post|feed|comment|like|share)\b/i.test(lower)) {
        return 'social';
    }

    if (/<input[^>]*type="search"/i.test(lower) || lower.includes('google.com')) {
        return 'search';
    }

    if (/\b(dashboard|admin|panel|analytics)\b/i.test(lower)) {
        return 'dashboard';
    }

    return 'unknown';
}

function extractInteractiveElements(html: string): InteractiveElement[] {
    const elements: InteractiveElement[] = [];

    // Extract buttons
    const buttonRegex = /<button[^>]*>(.*?)<\/button>/gi;
    let match;
    while ((match = buttonRegex.exec(html)) !== null) {
        const text = match[1].replace(/<[^>]+>/g, '').trim();
        if (text) {
            elements.push({
                type: 'button',
                label: text,
                selector: `button:contains("${text}")`,
                importance: calculateImportance(text)
            });
        }
    }

    // Extract links
    const linkRegex = /<a[^>]*href="([^"]*)"[^>]*>(.*?)<\/a>/gi;
    while ((match = linkRegex.exec(html)) !== null) {
        const href = match[1];
        const text = match[2].replace(/<[^>]+>/g, '').trim();
        if (text && !href.startsWith('#')) {
            elements.push({
                type: 'link',
                label: text,
                selector: `a[href="${href}"]`,
                importance: 0.5
            });
        }
    }

    // Extract inputs
    const inputRegex = /<input[^>]*type="([^"]*)"[^>]*(?:placeholder="([^"]*)")?\s*(?:name="([^"]*)")?[^>]*>/gi;
    while ((match = inputRegex.exec(html)) !== null) {
        const type = match[1];
        const placeholder = match[2] || '';
        const name = match[3] || '';

        elements.push({
            type: 'input',
            label: placeholder || name || type,
            selector: `input[type="${type}"]${name ? `[name="${name}"]` : ''}`,
            importance: type === 'submit' ? 0.9 : 0.6
        });
    }

    return elements.slice(0, 20); // Limit to top 20
}

function extractForms(html: string): FormElement[] {
    const forms: FormElement[] = [];
    const formRegex = /<form[^>]*action="([^"]*)"[^>]*method="([^"]*)"[^>]*>([\s\S]*?)<\/form>/gi;

    let match;
    while ((match = formRegex.exec(html)) !== null) {
        const action = match[1];
        const method = match[2];
        const formContent = match[3];

        const fields = extractFormFields(formContent);

        forms.push({
            action,
            method,
            fields
        });
    }

    return forms;
}

function extractFormFields(formHtml: string): FormElement['fields'] {
    const fields: FormElement['fields'] = [];
    const inputRegex = /<input[^>]*name="([^"]*)"[^>]*type="([^"]*)"[^>]*(?:required)?[^>]*(?:placeholder="([^"]*)")?[^>]*>/gi;

    let match;
    while ((match = inputRegex.exec(formHtml)) !== null) {
        fields.push({
            name: match[1],
            type: match[2],
            required: /required/i.test(match[0]),
            placeholder: match[3]
        });
    }

    return fields;
}

function extractArticles(html: string): ArticleContent[] {
    // Simplified article extraction
    const articles: ArticleContent[] = [];

    const articleRegex = /<article[^>]*>([\s\S]*?)<\/article>/gi;
    let match;

    while ((match = articleRegex.exec(html)) !== null) {
        const content = match[1];
        const title = content.match(/<h[1-3][^>]*>(.*?)<\/h[1-3]>/i)?.[1] || 'Untitled';
        const text = content.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

        articles.push({
            title,
            content: text.substring(0, 1000),
            summary: text.substring(0, 200) + '...'
        });
    }

    return articles;
}

function calculateImportance(text: string): number {
    const lower = text.toLowerCase();

    // High importance keywords
    if (/\b(submit|send|buy|purchase|login|signup|register|confirm|save|cliquez|envoyer)\b/i.test(lower)) {
        return 0.9;
    }

    // Medium  importance
    if (/\b(search|next|continue|cancel|back|close)\b/i.test(lower)) {
        return 0.6;
    }

    return 0.4;
}

/**
 * Smart interaction planner
 */
export function planInteraction(goal: string, pageAnalysis: PageAnalysis): string[] {
    const steps: string[] = [];
    const lower = goal.toLowerCase();

    // Login flow
    if (/\b(login|log in|sign in|تسجيل\s*دخول)\b/i.test(lower)) {
        const usernameField = pageAnalysis.interactiveElements.find(e =>
            e.type === 'input' && /\b(user|email|username)\b/i.test(e.label)
        );
        const passwordField = pageAnalysis.interactiveElements.find(e =>
            e.type === 'input' && /\b(pass|password)\b/i.test(e.label)
        );
        const submitButton = pageAnalysis.interactiveElements.find(e =>
            e.type === 'button' && /\b(login|submit|sign\s*in)\b/i.test(e.label)
        );

        if (usernameField) steps.push(`Type username in ${usernameField.selector}`);
        if (passwordField) steps.push(`Type password in ${passwordField.selector}`);
        if (submitButton) steps.push(`Click ${submitButton.selector}`);
    }

    // Search flow
    else if (/\b(search|بحث|find|ابحث)\b/i.test(lower)) {
        const searchInput = pageAnalysis.interactiveElements.find(e =>
            e.type === 'input' && (/search/i.test(e.label) || e.label.includes('q'))
        );

        if (searchInput) {
            steps.push(`Type search query in ${searchInput.selector}`);
            steps.push(`Press Enter or click search button`);
        }
    }

    // Form filling
    else if (/\b(fill|املأ|complete|اكمل)\b/i.test(lower) && pageAnalysis.forms.length > 0) {
        const form = pageAnalysis.forms[0];
        for (const field of form.fields) {
            steps.push(`Fill ${field.name} (${field.type})`);
        }
        if (form.submitButton) {
            steps.push(`Click submit button`);
        }
    }

    // Navigation
    else if (/\b(go to|navigate|click|انقر|اذهب)\b/i.test(lower)) {
        const targetText = lower.match(/(?:go to|navigate to|click|انقر|اذهب)\s+(.+)/i)?.[1] || '';
        const element = pageAnalysis.interactiveElements.find(e =>
            e.label.toLowerCase().includes(targetText)
        );

        if (element) {
            steps.push(`Click ${element.selector}`);
        }
    }

    if (steps.length === 0) {
        steps.push('Unable to plan interaction - please provide more specific instructions');
    }

    return steps;
}

/**
 * Extract data from page based on schema
 */
export function extractData(html: string, schema: Record<string, string>): Record<string, any> {
    const data: Record<string, any> = {};

    for (const [key, selector] of Object.entries(schema)) {
        // Simple extraction (will be enhanced with actual DOM)
        const regex = new RegExp(`<[^>]*${selector}[^>]*>([^<]+)<`, 'i');
        const match = html.match(regex);
        data[key] = match ? match[1].trim() : null;
    }

    return data;
}

export default {
    analyzePage,
    planInteraction,
    extractData
};

import type { Locator, Page } from 'playwright';
import type { FailureReason } from './types';
import { DEFAULT_BROWSER_CONFIG } from './config';
import { broadcastBrowserEvent } from './wsHub';
import { getBrowserSession, setStreamMask, startStreaming, touchSession, withBrowserConcurrency } from './manager';
import { getSessionSecret, getUserSecret } from '../services/secrets';
import { AdvancedInteractionSystem } from './interactions';

type Action =
  | { type: 'goto'; url: string; optional?: boolean }
  | { type: 'goto'; url: string; optional?: boolean }
  | { type: 'click'; selector?: string; role?: string; name?: string; text?: string; optional?: boolean; x?: number; y?: number }
  | { type: 'hover'; selector?: string; role?: string; name?: string; text?: string; optional?: boolean; x?: number; y?: number }
  | { type: 'type'; selector?: string; role?: string; name?: string; text: string; optional?: boolean; x?: number; y?: number }
  | { type: 'scroll'; direction: 'down' | 'up'; amount?: number; optional?: boolean }
  | { type: 'wait'; ms: number; optional?: boolean }
  | { type: 'assert'; selector?: string; text?: string; optional?: boolean }
  | { type: 'ui_audit'; optional?: boolean };

const SECRET_TOKEN_RE = /^\{\{\s*SECRET\s*:\s*([A-Z0-9_]+)\s*\}\}$/;

function now() {
  return Date.now();
}

function stepId(i: number) {
  return `step_${i + 1}`;
}

function isSameSiteAllowed(allowedOrigin: string | null, nextUrl: string) {
  if (!DEFAULT_BROWSER_CONFIG.strictSameSite) return true;
  if (!allowedOrigin) return true;
  try {
    const u = new URL(nextUrl);
    return u.origin === allowedOrigin;
  } catch {
    return false;
  }
}

function normalizeUrlForGoto(raw: any, baseUrl?: string) {
  let s = String(raw ?? '').trim();
  s = s.replace(/^[`"'“”‘’]+/, '').replace(/[`"'“”‘’]+$/, '').trim();
  if (!s) return s;
  const fixKnownHosts = (u: string) => {
    const input = String(u || '').trim();
    if (!input) return input;
    try {
      const parsed = new URL(input);
      const host = String(parsed.hostname || '').trim().toLowerCase();
      const hadWww = /^www\./i.test(host);
      const hostNoWww = host.replace(/^www\./i, '');
      const isXeliteLike =
        (/xelite/i.test(hostNoWww) && /solution/i.test(hostNoWww)) ||
        /^xelitesolutions(?:\.(?:co|com))?$/i.test(hostNoWww);
      if (isXeliteLike) {
        const tld = /\.com$/i.test(hostNoWww) ? 'com' : 'co';
        parsed.hostname = `${hadWww ? 'www.' : ''}xelitesolutions.${tld}`;
        return parsed.toString();
      }
      return input;
    } catch {
      return input;
    }
  };
  if (/^https?:\/\//i.test(s)) return fixKnownHosts(s);
  if (/^\/\//.test(s)) return `https:${s}`;
  if (/^\//.test(s)) {
    try {
      if (baseUrl) return fixKnownHosts(new URL(s, baseUrl).toString());
    } catch { }
    return s;
  }
  const candidate = s.replace(/^\/\//, '');
  const isLocal =
    /^localhost(?::\d+)?(?:\/|$)/i.test(candidate) ||
    /^127\.0\.0\.1(?::\d+)?(?:\/|$)/.test(candidate) ||
    /^\d+\.\d+\.\d+\.\d+(?::\d+)?(?:\/|$)/.test(candidate);
  const looksDomain =
    /^(?:www\.)?[a-z0-9][a-z0-9-]{0,62}(?:\.[a-z0-9-]{1,63})+(?::\d+)?(?:\/[^\s"'<>]*)?$/i.test(candidate);
  if (isLocal) return `http://${candidate}`;
  if (looksDomain) return fixKnownHosts(`https://${candidate}`);
  if (/^xelite/i.test(candidate) && /solution/i.test(candidate)) {
    if (!/\./.test(candidate)) return 'https://xelitesolutions.co';
    return fixKnownHosts(`https://${candidate}`);
  }
  return s;
}

function locatorForAction(page: Page, a: any): Locator | null {
  if (a?.selector) return page.locator(String(a.selector));
  if (a?.role && a?.name) return (page as any).getByRole(String(a.role), { name: String(a.name) });
  if (a?.text) return page.getByText(String(a.text), { exact: false });
  return null;
}

async function findCredentialField(page: Page, kind: 'email' | 'password') {
  const css =
    kind === 'email'
      ? [
        'input[type="email"]',
        'input[autocomplete="email"]',
        'input[name*="email" i]',
        'input[id*="email" i]',
        'input[name="login"]',
        'input#login_field',
        'input[id*="login" i]',
        'input[name*="user" i]',
        'input[id*="user" i]',
        'input[placeholder*="email" i]',
        'input[aria-label*="email" i]',
        'input[placeholder*="mail" i]',
        'input[aria-label*="mail" i]',
        'input[placeholder*="ايميل" i]',
        'input[placeholder*="إيميل" i]',
        'input[placeholder*="البريد" i]',
        'input[aria-label*="ايميل" i]',
        'input[aria-label*="إيميل" i]',
        'input[aria-label*="البريد" i]',
      ]
      : [
        'input[type="password"]',
        'input[autocomplete="current-password"]',
        'input[autocomplete="new-password"]',
        'input[name*="pass" i]',
        'input[id*="pass" i]',
        'input[placeholder*="pass" i]',
        'input[aria-label*="pass" i]',
        'input[placeholder*="password" i]',
        'input[aria-label*="password" i]',
        'input[placeholder*="كلمة" i]',
        'input[placeholder*="المرور" i]',
        'input[placeholder*="باسورد" i]',
        'input[aria-label*="كلمة" i]',
        'input[aria-label*="المرور" i]',
        'input[aria-label*="باسورد" i]',
      ];

  for (const sel of css) {
    try {
      const loc = page.locator(sel).first();
      if ((await loc.count().catch(() => 0)) === 0) continue;
      await loc.waitFor({ state: 'visible', timeout: 800 }).catch(() => null);
      if (await loc.isVisible().catch(() => false)) return page.locator(sel);
    } catch { }
  }

  const labels =
    kind === 'email'
      ? [/email/i, /e-mail/i, /mail/i, /user(name)?/i, /login/i, /البريد/i, /ايميل/i, /إيميل/i]
      : [/password/i, /passcode/i, /كلمة\s*المرور/i, /باسورد/i, /باسوورد/i, /الباسورد/i, /الباسوورد/i];

  for (const r of labels) {
    try {
      const loc = page.getByLabel(r, { exact: false }).first();
      if ((await loc.count().catch(() => 0)) === 0) continue;
      await loc.waitFor({ state: 'visible', timeout: 800 }).catch(() => null);
      if (await loc.isVisible().catch(() => false)) return loc;
    } catch { }
  }

  const roleNames =
    kind === 'email'
      ? [/email/i, /e-mail/i, /mail/i, /user(name)?/i, /login/i, /البريد/i, /ايميل/i, /إيميل/i]
      : [/password/i, /passcode/i, /كلمة\s*المرور/i, /باسورد/i, /باسوورد/i, /الباسورد/i, /الباسوورد/i];

  for (const r of roleNames) {
    try {
      const loc = (page as any).getByRole('textbox', { name: r }).first();
      if ((await loc.count().catch(() => 0)) === 0) continue;
      await loc.waitFor({ state: 'visible', timeout: 800 }).catch(() => null);
      if (await loc.isVisible().catch(() => false)) return loc;
    } catch { }
  }

  return null;
}

async function boxFor(locator: Locator) {
  try {
    await locator.first().scrollIntoViewIfNeeded();
  } catch { }
  try {
    const b = await locator.first().boundingBox();
    if (!b) return null;
    return { x: b.x, y: b.y, width: b.width, height: b.height };
  } catch {
    return null;
  }
}

async function tryDismissOverlays(page: Page) {
  const candidates = [
    'button:has-text("Accept")',
    'button:has-text("I agree")',
    'button:has-text("Agree")',
    'button:has-text("Accept all")',
    'button:has-text("أوافق")',
    'button:has-text("قبول")',
    'button:has-text("موافق")',
    'button:has-text("رفض الكل")',
    'button:has-text("Reject all")',
    'div[role="button"]:has-text("Accept all")',
    'div[role="button"]:has-text("I agree")',
    'button:has-text("Before you continue")', // Google sometimes has this as title, button is 'Accept'
    'button[aria-label="Accept all"]',
  ];
  for (const sel of candidates) {
    try {
      const loc = page.locator(sel).first();
      if ((await loc.count()) === 0) continue;
      await loc.click({ timeout: 1500 });
      await page.waitForTimeout(250);
    } catch { }
  }
}

async function screenshotJpegBase64(page: Page, maskLocators?: Locator[]) {
  const buf = await page.screenshot({
    type: 'jpeg',
    quality: 65,
    animations: 'disabled',
    mask: maskLocators && maskLocators.length ? maskLocators : undefined,
  });
  return Buffer.from(buf).toString('base64');
}

export async function executePlannedActions(params: {
  userId: string;
  sessionId: string;
  actions: Action[];
}) {
  return await withBrowserConcurrency(async () => {
    const userId = String(params.userId || '').trim();
    const sessionId = String(params.sessionId || '').trim();
    const actions = Array.isArray(params.actions) ? params.actions : [];
    const cfg = DEFAULT_BROWSER_CONFIG;

    const s = await getBrowserSession(sessionId);
    startStreaming(sessionId);

    const page = s.page;
    const interactions = new AdvancedInteractionSystem();
    try {
      broadcastBrowserEvent(sessionId, {
        type: 'session_status',
        ts: now(),
        sessionId,
        url: page.url(),
        workerStatus: 'running',
      });
    } catch { }
    const results: Array<{ stepId: string; name: string; ok: boolean; reason?: FailureReason; message?: string }> = [];
    const evidence: Array<{ kind: 'screenshot'; jpegBase64: string; ts: number; stepId: string }> = [];

    for (let i = 0; i < Math.min(cfg.maxSteps, actions.length); i += 1) {
      touchSession(sessionId);
      const a: any = actions[i];
      const name = String(a?.type || 'unknown');
      const sid = stepId(i);
      try {
        const rawText = name === 'type' ? String(a?.text || '') : '';
        const secretMatch = name === 'type' ? rawText.match(SECRET_TOKEN_RE) : null;
        const summary =
          name === 'goto'
            ? `goto ${normalizeUrlForGoto(a?.url, (() => { try { return page.url(); } catch { return ''; } })()).trim()}`
            : name === 'type'
              ? secretMatch
                ? `type (secret:${String(secretMatch[1] || '').trim() || 'KEY'})`
                : `type (len=${rawText.length})`
              : name;
        broadcastBrowserEvent(sessionId, { type: 'action_sent', ts: now(), actionId: sid, actionType: name, summary });
      } catch { }
      broadcastBrowserEvent(sessionId, { type: 'step_start', stepId: sid, name, ts: now() });
      try {
        broadcastBrowserEvent(sessionId, { type: 'action_ack', ts: now(), actionId: sid, actionType: name });
      } catch { }

      let mask: Locator[] = [];
      try {
        if (name === 'goto') {
          const optional = Boolean(a?.optional);
          const url = normalizeUrlForGoto(a?.url, (() => { try { return page.url(); } catch { return ''; } })());
          if (!url) {
            if (optional) {
              broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now(), data: { skipped: true } });
              results.push({ stepId: sid, name, ok: true });
              try {
                broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name });
              } catch { }
              continue;
            }
            results.push({ stepId: sid, name, ok: false, reason: 'unknown', message: 'missing_url' });
            broadcastBrowserEvent(sessionId, { type: 'step_error', stepId: sid, name, ts: now(), reason: 'unknown', message: 'missing_url' });
            continue;
          }
          if (!isSameSiteAllowed(s.allowedOrigin, url)) {
            if (optional) {
              broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now(), data: { skipped: true, reason: 'same_site_blocked' } });
              results.push({ stepId: sid, name, ok: true });
              try {
                broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name });
              } catch { }
              continue;
            }
            results.push({ stepId: sid, name, ok: false, reason: 'same_site_blocked', message: url });
            broadcastBrowserEvent(sessionId, { type: 'goto_blocked', stepId: sid, ts: now(), url, reason: 'same_site_blocked', message: 'cross_site_blocked' });
            try {
              broadcastBrowserEvent(sessionId, {
                type: 'action_error',
                ts: now(),
                actionId: sid,
                actionType: name,
                reason: 'same_site_blocked',
                error: 'cross_site_blocked',
              });
            } catch { }
            continue;
          }
          broadcastBrowserEvent(sessionId, { type: 'cursor_move', ts: now(), x: 30, y: 20 });
          broadcastBrowserEvent(sessionId, { type: 'highlight_boxes', ts: now(), boxes: [{ x: 10, y: 8, width: 520, height: 38, label: 'goto' }] });

          setStreamMask(sessionId, []);
          const before = await screenshotJpegBase64(page);
          evidence.push({ kind: 'screenshot', jpegBase64: before, ts: now(), stepId: sid });

          const navReason = (msg: string): FailureReason => {
            const m = String(msg || '').toLowerCase();
            if (/err_name_not_resolved|enotfound|dns|name not resolved/.test(m)) return 'dns_failed';
            if (/err_cert|ssl|tls|certificate|net::err/.test(m)) return 'navigation_failed';
            if (/timeout/i.test(m)) return 'timeout';
            return 'navigation_failed';
          };
          const gotoCandidates = (() => {
            const out: string[] = [];
            const push = (u: string) => {
              const v = String(u || '').trim();
              if (!v) return;
              if (!out.includes(v)) out.push(v);
            };
            push(url);
            try {
              const u = new URL(url);
              const hostNoWww = u.hostname.replace(/^www\./i, '');
              const isXeliteLike =
                (/xelite/i.test(hostNoWww) && /solution/i.test(hostNoWww)) ||
                /^xelitesolutions(?:\.(?:co|com))?$/i.test(hostNoWww);
              if (isXeliteLike) {
                u.hostname = hostNoWww.endsWith('.com') ? 'xelitesolutions.com' : 'xelitesolutions.co';
                push(u.toString());
                u.hostname = 'www.' + u.hostname.replace(/^www\./i, '');
                push(u.toString());
                u.hostname = u.hostname.replace(/xelitesolutions\.(?:co|com)/i, 'xelitesolutions.co');
                push(u.toString());
                u.hostname = u.hostname.replace(/xelitesolutions\.co/i, 'xelitesolutions.com');
                push(u.toString());
              } else {
                if (!/^www\./i.test(u.hostname) && u.hostname.includes('.')) {
                  u.hostname = `www.${u.hostname}`;
                  push(u.toString());
                }
              }
              if (u.protocol === 'https:') {
                u.protocol = 'http:';
                push(u.toString());
              }
            } catch { }
            return out.slice(0, 6);
          })();

          let navigated = false;
          let lastErr = '';
          for (const u of gotoCandidates) {
            try {
              await page.goto(u, { waitUntil: 'domcontentloaded', timeout: cfg.navTimeoutMs });
              navigated = true;
              break;
            } catch (e: any) {
              lastErr = String(e?.message || e || '');
            }
          }
          if (!navigated) {
            const msg = lastErr.trim() || 'navigation_failed';
            const reason = navReason(msg);
            results.push({ stepId: sid, name, ok: false, reason, message: msg.slice(0, 600) });
            broadcastBrowserEvent(sessionId, { type: 'step_error', stepId: sid, name, ts: now(), reason, message: msg.slice(0, 600) });
            try {
              broadcastBrowserEvent(sessionId, { type: 'action_error', ts: now(), actionId: sid, actionType: name, reason, error: msg.slice(0, 600) });
            } catch { }
            continue;
          }
          await page.waitForTimeout(250);

          const after = await screenshotJpegBase64(page);
          evidence.push({ kind: 'screenshot', jpegBase64: after, ts: now(), stepId: sid });

          broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now(), data: { url: page.url() } });
          results.push({ stepId: sid, name, ok: true });
          try {
            broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name });
          } catch { }
          continue;
        }

        if (name === 'wait') {
          const ms = Math.max(0, Math.min(30000, Number(a?.ms || 0)));
          const before = await screenshotJpegBase64(page);
          evidence.push({ kind: 'screenshot', jpegBase64: before, ts: now(), stepId: sid });
          await page.waitForTimeout(ms);
          const after = await screenshotJpegBase64(page);
          evidence.push({ kind: 'screenshot', jpegBase64: after, ts: now(), stepId: sid });
          broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now() });
          results.push({ stepId: sid, name, ok: true });
          try {
            broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name });
          } catch { }
          continue;
        }

        if (name === 'scroll') {
          const direction = a?.direction === 'up' ? 'up' : 'down';
          const amount = Math.max(120, Math.min(2400, Number(a?.amount || 800)));
          const before = await screenshotJpegBase64(page);
          evidence.push({ kind: 'screenshot', jpegBase64: before, ts: now(), stepId: sid });

          // Center mouse first to ensure we scroll the main view
          try {
            const vp = page.viewportSize();
            if (vp) {
              await page.mouse.move(vp.width / 2, vp.height / 2);
            }
          } catch { }

          await page.mouse.wheel(0, direction === 'down' ? amount : -amount);
          await page.waitForTimeout(250);
          const after = await screenshotJpegBase64(page);
          evidence.push({ kind: 'screenshot', jpegBase64: after, ts: now(), stepId: sid });
          broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now() });
          results.push({ stepId: sid, name, ok: true });
          try {
            broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name });
          } catch { }
          continue;
        }

        if (name === 'hover') {
          const loc = locatorForAction(page, a);
          if (loc && (await loc.count().catch(() => 0)) > 0) {
            const b = await boxFor(loc);
            if (b) {
              const cx = Math.round(b.x + b.width / 2);
              const cy = Math.round(b.y + b.height / 2);
              broadcastBrowserEvent(sessionId, { type: 'cursor_move', ts: now(), x: cx, y: cy });
              broadcastBrowserEvent(sessionId, { type: 'highlight_boxes', ts: now(), boxes: [{ ...b, label: 'hover' }] });
              try { await page.mouse.move(cx, cy, { steps: 15 }); } catch { }
            }
            try { await loc.first().hover({ timeout: cfg.actionTimeoutMs }); } catch { }
          }
          await page.waitForTimeout(500);
          const after = await screenshotJpegBase64(page);
          evidence.push({ kind: 'screenshot', jpegBase64: after, ts: now(), stepId: sid });
          broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now() });
          results.push({ stepId: sid, name, ok: true });
          try {
            broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name });
          } catch { }
          continue;
        }

        if (name === 'ui_audit') {
          const before = await screenshotJpegBase64(page);
          evidence.push({ kind: 'screenshot', jpegBase64: before, ts: now(), stepId: sid });
          const after = await screenshotJpegBase64(page);
          evidence.push({ kind: 'screenshot', jpegBase64: after, ts: now(), stepId: sid });
          broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now(), data: { ok: true } });
          results.push({ stepId: sid, name, ok: true });
          try {
            broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name });
          } catch { }
          continue;
        }

        if (name === 'assert') {
          const selector = typeof a?.selector === 'string' ? a.selector : '';
          const text = typeof a?.text === 'string' ? a.text : '';
          const before = await screenshotJpegBase64(page);
          evidence.push({ kind: 'screenshot', jpegBase64: before, ts: now(), stepId: sid });
          if (selector) {
            const loc = page.locator(selector).first();
            await loc.waitFor({ state: 'visible', timeout: cfg.actionTimeoutMs });
          } else if (text) {
            const loc = page.getByText(text, { exact: false }).first();
            await loc.waitFor({ state: 'visible', timeout: cfg.actionTimeoutMs });
          } else {
            throw new Error('assert_missing_target');
          }
          const after = await screenshotJpegBase64(page);
          evidence.push({ kind: 'screenshot', jpegBase64: after, ts: now(), stepId: sid });
          broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now() });
          results.push({ stepId: sid, name, ok: true });
          try {
            broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name });
          } catch { }
          continue;
        }

        if (name === 'click' || name === 'type') {
          if (name === 'click') {
            const xNum = Number(a?.x);
            const yNum = Number(a?.y);
            if (Number.isFinite(xNum) && Number.isFinite(yNum)) {
              const x = Math.max(0, Math.round(xNum));
              const y = Math.max(0, Math.round(yNum));
              try {
                broadcastBrowserEvent(sessionId, { type: 'cursor_move', ts: now(), x, y });
                broadcastBrowserEvent(sessionId, {
                  type: 'highlight_boxes',
                  ts: now(),
                  boxes: [{ x: Math.max(0, x - 6), y: Math.max(0, y - 6), width: 12, height: 12, label: 'click' }],
                });
              } catch { }

              setStreamMask(sessionId, []);
              const before = await screenshotJpegBase64(page);
              evidence.push({ kind: 'screenshot', jpegBase64: before, ts: now(), stepId: sid });

              await interactions.naturalClick(page, 'click', x, y);

              await page.waitForTimeout(120);
              const after = await screenshotJpegBase64(page);
              evidence.push({ kind: 'screenshot', jpegBase64: after, ts: now(), stepId: sid });

              broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now() });
              results.push({ stepId: sid, name, ok: true });
              try {
                broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name });
              } catch { }
              continue;
            }
          }

          // Global type (interactive mode, no selector/coords)
          if (name === 'type' && !a?.selector && !a?.role && !a?.name && !a?.textTarget && (!Number.isFinite(Number(a?.x)) || !Number.isFinite(Number(a?.y)))) {
            const text = String(a?.text || '');
            setStreamMask(sessionId, []);
            const before = await screenshotJpegBase64(page);
            evidence.push({ kind: 'screenshot', jpegBase64: before, ts: now(), stepId: sid });

            if (text === '\n') await page.keyboard.press('Enter');
            else if (text === '\t') await page.keyboard.press('Tab');
            else if (text === '\b') await page.keyboard.press('Backspace');
            else await interactions.naturalType(page, 'global_type', text);

            await page.waitForTimeout(50);
            const after = await screenshotJpegBase64(page);
            evidence.push({ kind: 'screenshot', jpegBase64: after, ts: now(), stepId: sid });

            broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now() });
            results.push({ stepId: sid, name, ok: true });
            try { broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name }); } catch { }
            continue;
          }

          if (name === 'type') {
            const xNum = Number(a?.x);
            const yNum = Number(a?.y);
            if (Number.isFinite(xNum) && Number.isFinite(yNum) && !a?.selector && !a?.role && !a?.name && !a?.textTarget) {
              const x = Math.max(0, Math.round(xNum));
              const y = Math.max(0, Math.round(yNum));
              const raw = String(a?.text || '');
              const secretMatch = raw.match(SECRET_TOKEN_RE);
              const secretKey = secretMatch ? String(secretMatch[1] || '').trim() : '';
              const secretIsPassword = secretKey ? /(?:^|_)PASSWORD(?:$|_)/i.test(secretKey) : false;
              if (!secretIsPassword) {
                let textToType = raw;
                if (secretMatch) {
                  const secretValue =
                    (secretKey ? getSessionSecret(sessionId, secretKey) : null) ||
                    (secretKey ? await getUserSecret(userId, 'internal', secretKey) : null) ||
                    '';
                  if (!secretValue) {
                    results.push({ stepId: sid, name, ok: false, reason: 'unknown', message: `missing_secret:${secretKey}` });
                    broadcastBrowserEvent(sessionId, { type: 'step_error', stepId: sid, name, ts: now(), reason: 'unknown', message: `missing_secret:${secretKey}` });
                    try {
                      broadcastBrowserEvent(sessionId, {
                        type: 'action_error',
                        ts: now(),
                        actionId: sid,
                        actionType: name,
                        reason: 'unknown',
                        error: `missing_secret:${secretKey}`,
                      });
                    } catch { }
                    continue;
                  }
                  textToType = secretValue;
                }

                try {
                  broadcastBrowserEvent(sessionId, { type: 'cursor_move', ts: now(), x, y });
                  broadcastBrowserEvent(sessionId, {
                    type: 'highlight_boxes',
                    ts: now(),
                    boxes: [{ x: Math.max(0, x - 6), y: Math.max(0, y - 6), width: 12, height: 12, label: 'type' }],
                  });
                } catch { }

                setStreamMask(sessionId, []);
                const before = await screenshotJpegBase64(page);
                evidence.push({ kind: 'screenshot', jpegBase64: before, ts: now(), stepId: sid });

                await interactions.naturalClick(page, 'type_click', x, y);
                try {
                  await page.keyboard.press('Meta+A');
                } catch {
                  try {
                    await page.keyboard.press('Control+A');
                  } catch { }
                }
                try {
                  await page.keyboard.press('Backspace');
                } catch { }
                await interactions.naturalType(page, 'type_secret', textToType);

                await page.waitForTimeout(120);
                const after = await screenshotJpegBase64(page);
                evidence.push({ kind: 'screenshot', jpegBase64: after, ts: now(), stepId: sid });

                broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now() });
                results.push({ stepId: sid, name, ok: true });
                try {
                  broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name });
                } catch { }
                continue;
              }
            }

            const textRaw = String(a?.text || '');
            if (textRaw && !a?.selector && !a?.role && !a?.name && !a?.textTarget) {
              const secretMatch = textRaw.match(SECRET_TOKEN_RE);
              if (secretMatch) {
                const secretKey = String(secretMatch[1] || '').trim();
                const secretValue =
                  (secretKey ? getSessionSecret(sessionId, secretKey) : null) ||
                  (secretKey ? await getUserSecret(userId, 'internal', secretKey) : null) ||
                  '';
                if (!secretValue) {
                  results.push({ stepId: sid, name, ok: false, reason: 'unknown', message: `missing_secret:${secretKey}` });
                  broadcastBrowserEvent(sessionId, { type: 'step_error', stepId: sid, name, ts: now(), reason: 'unknown', message: `missing_secret:${secretKey}` });
                  try {
                    broadcastBrowserEvent(sessionId, {
                      type: 'action_error',
                      ts: now(),
                      actionId: sid,
                      actionType: name,
                      reason: 'unknown',
                      error: `missing_secret:${secretKey}`,
                    });
                  } catch { }
                  continue;
                }

                const optional = Boolean(a?.optional);
                const kind =
                  /(?:^|_)EMAIL(?:$|_)/i.test(secretKey) ? ('email' as const) : /(?:^|_)PASSWORD(?:$|_)/i.test(secretKey) ? ('password' as const) : null;
                const fieldLoc = kind ? await findCredentialField(page, kind) : null;
                const count = fieldLoc ? await fieldLoc.count().catch(() => 0) : 0;
                if (!fieldLoc || !count) {
                  if (optional) {
                    broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now(), data: { skipped: true } });
                    results.push({ stepId: sid, name, ok: true });
                    try {
                      broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name });
                    } catch { }
                    continue;
                  }
                  results.push({ stepId: sid, name, ok: false, reason: 'element_not_found', message: 'no_locator' });
                  broadcastBrowserEvent(sessionId, { type: 'step_error', stepId: sid, name, ts: now(), reason: 'element_not_found', message: 'no_locator' });
                  try {
                    broadcastBrowserEvent(sessionId, {
                      type: 'action_error',
                      ts: now(),
                      actionId: sid,
                      actionType: name,
                      reason: 'element_not_found',
                      error: 'no_locator',
                    });
                  } catch { }
                  continue;
                }

                const isSensitive = kind === 'password';
                if (isSensitive) {
                  mask = [fieldLoc.first()];
                  setStreamMask(sessionId, mask);
                } else {
                  setStreamMask(sessionId, []);
                }
                const b = await boxFor(fieldLoc);
                if (b) {
                  const cx = Math.round(b.x + b.width / 2);
                  const cy = Math.round(b.y + b.height / 2);
                  try {
                    broadcastBrowserEvent(sessionId, { type: 'cursor_move', ts: now(), x: cx, y: cy });
                    broadcastBrowserEvent(sessionId, { type: 'highlight_boxes', ts: now(), boxes: [{ ...b, label: 'type' }] });
                  } catch { }
                }
                const before = await screenshotJpegBase64(page, isSensitive ? mask : undefined);
                evidence.push({ kind: 'screenshot', jpegBase64: before, ts: now(), stepId: sid });
                await fieldLoc.first().click({ timeout: cfg.actionTimeoutMs });
                await fieldLoc.first().fill(secretValue, { timeout: cfg.actionTimeoutMs });
                const after = await screenshotJpegBase64(page, isSensitive ? mask : undefined);
                evidence.push({ kind: 'screenshot', jpegBase64: after, ts: now(), stepId: sid });
                if (isSensitive) setStreamMask(sessionId, []);
                broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now() });
                results.push({ stepId: sid, name, ok: true });
                try {
                  broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name });
                } catch { }
                continue;
              } else {
                setStreamMask(sessionId, []);
                const before = await screenshotJpegBase64(page);
                evidence.push({ kind: 'screenshot', jpegBase64: before, ts: now(), stepId: sid });

                await interactions.naturalType(page, 'type_text', textRaw);

                await page.waitForTimeout(80);
                const after = await screenshotJpegBase64(page);
                evidence.push({ kind: 'screenshot', jpegBase64: after, ts: now(), stepId: sid });

                broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now() });
                results.push({ stepId: sid, name, ok: true });
                try {
                  broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name });
                } catch { }
                continue;
              }
            }
          }

          const optional = Boolean(a?.optional);
          const loc = locatorForAction(page, a);
          if (!loc) {
            if (optional) {
              broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now(), data: { skipped: true } });
              results.push({ stepId: sid, name, ok: true });
              try {
                broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name });
              } catch { }
              continue;
            }
            results.push({ stepId: sid, name, ok: false, reason: 'element_not_found', message: 'no_locator' });
            broadcastBrowserEvent(sessionId, { type: 'step_error', stepId: sid, name, ts: now(), reason: 'element_not_found', message: 'no_locator' });
            try {
              broadcastBrowserEvent(sessionId, {
                type: 'action_error',
                ts: now(),
                actionId: sid,
                actionType: name,
                reason: 'element_not_found',
                error: 'no_locator',
              });
            } catch { }
            continue;
          }

          const count = await loc.count().catch(() => 0);
          if (!count) {
            if (optional) {
              broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now(), data: { skipped: true, reason: 'element_not_found' } });
              results.push({ stepId: sid, name, ok: true });
              try {
                broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name });
              } catch { }
              continue;
            }
            results.push({ stepId: sid, name, ok: false, reason: 'element_not_found', message: 'not_found' });
            broadcastBrowserEvent(sessionId, { type: 'step_error', stepId: sid, name, ts: now(), reason: 'element_not_found', message: 'not_found' });
            try {
              broadcastBrowserEvent(sessionId, {
                type: 'action_error',
                ts: now(),
                actionId: sid,
                actionType: name,
                reason: 'element_not_found',
                error: 'not_found',
              });
            } catch { }
            continue;
          }

          const b = await boxFor(loc);
          let targetCenter: { x: number; y: number } | null = null;
          if (b) {
            const cx = Math.round(b.x + b.width / 2);
            const cy = Math.round(b.y + b.height / 2);
            targetCenter = { x: cx, y: cy };
            broadcastBrowserEvent(sessionId, { type: 'cursor_move', ts: now(), x: cx, y: cy });
            broadcastBrowserEvent(sessionId, { type: 'highlight_boxes', ts: now(), boxes: [{ ...b, label: name }] });
            try { await interactions.hover(page, name, cx, cy); } catch { }
          }

          const textRaw = name === 'type' ? String(a?.text || '') : '';
          const secretMatch = name === 'type' ? textRaw.match(SECRET_TOKEN_RE) : null;
          if (secretMatch) {
            const secretKey = String(secretMatch[1] || '').trim();
            const secretValue =
              getSessionSecret(sessionId, secretKey) ||
              (await getUserSecret(userId, 'internal', secretKey)) ||
              '';
            if (!secretValue) {
              results.push({ stepId: sid, name, ok: false, reason: 'unknown', message: `missing_secret:${secretKey}` });
              broadcastBrowserEvent(sessionId, { type: 'step_error', stepId: sid, name, ts: now(), reason: 'unknown', message: `missing_secret:${secretKey}` });
              try {
                broadcastBrowserEvent(sessionId, {
                  type: 'action_error',
                  ts: now(),
                  actionId: sid,
                  actionType: name,
                  reason: 'unknown',
                  error: `missing_secret:${secretKey}`,
                });
              } catch { }
              continue;
            }
            mask = [loc.first()];
            setStreamMask(sessionId, mask);
            const before = await screenshotJpegBase64(page, mask);
            evidence.push({ kind: 'screenshot', jpegBase64: before, ts: now(), stepId: sid });
            await loc.first().click({ timeout: cfg.actionTimeoutMs });
            await loc.first().fill(secretValue, { timeout: cfg.actionTimeoutMs });
            const after = await screenshotJpegBase64(page, mask);
            evidence.push({ kind: 'screenshot', jpegBase64: after, ts: now(), stepId: sid });
            setStreamMask(sessionId, []);
            broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now() });
            results.push({ stepId: sid, name, ok: true });
            try {
              broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name });
            } catch { }
            continue;
          }

          const isSensitiveType =
            name === 'type' &&
            (typeof a?.selector === 'string'
              ? /type\s*=\s*["']password["']|password|current-password/i.test(String(a.selector))
              : typeof a?.name === 'string'
                ? /password|كلمة المرور/i.test(String(a.name))
                : false);
          if (isSensitiveType) {
            mask = [loc.first()];
            setStreamMask(sessionId, mask);
          } else {
            setStreamMask(sessionId, []);
          }
          const before = await screenshotJpegBase64(page, isSensitiveType ? mask : undefined);
          evidence.push({ kind: 'screenshot', jpegBase64: before, ts: now(), stepId: sid });

          try {
            if (name === 'click') {
              if (targetCenter) await interactions.naturalClick(page, 'selector_click', targetCenter.x, targetCenter.y);
              else await loc.first().click({ timeout: cfg.actionTimeoutMs });
            } else {
              if (targetCenter) {
                await interactions.naturalClick(page, 'type_click', targetCenter.x, targetCenter.y);
                await interactions.naturalType(page, 'type_text', textRaw);
              } else {
                await loc.first().click({ timeout: cfg.actionTimeoutMs });
                await loc.first().fill(textRaw);
              }
            }
          } catch (e: any) {
            await tryDismissOverlays(page);
            try {
              if (name === 'click') {
                if (targetCenter) await interactions.naturalClick(page, 'selector_click_retry', targetCenter.x, targetCenter.y);
                else await loc.first().click({ timeout: cfg.actionTimeoutMs });
              } else {
                if (targetCenter) {
                  await interactions.naturalClick(page, 'type_click_retry', targetCenter.x, targetCenter.y);
                  await interactions.naturalType(page, 'type_text_retry', textRaw);
                } else {
                  await loc.first().click({ timeout: cfg.actionTimeoutMs });
                  await loc.first().fill(textRaw);
                }
              }
            } catch (e2: any) {
              const msg = String(e2?.message || e2);
              const reason: FailureReason = /timeout/i.test(msg) ? 'timeout' : /overlay|intercept|not clickable/i.test(msg) ? 'overlay_blocking_click' : 'unknown';
              broadcastBrowserEvent(sessionId, { type: 'step_error', stepId: sid, name, ts: now(), reason, message: msg });
              results.push({ stepId: sid, name, ok: false, reason, message: msg });
              try {
                broadcastBrowserEvent(sessionId, { type: 'action_error', ts: now(), actionId: sid, actionType: name, reason, error: msg });
              } catch { }
              if (isSensitiveType) setStreamMask(sessionId, []);
              continue;
            }
          }

          await page.waitForTimeout(250);
          const after = await screenshotJpegBase64(page, isSensitiveType ? mask : undefined);
          evidence.push({ kind: 'screenshot', jpegBase64: after, ts: now(), stepId: sid });
          if (isSensitiveType) setStreamMask(sessionId, []);

          if (cfg.strictSameSite && s.allowedOrigin) {
            const cur = page.url();
            try {
              const u = new URL(cur);
              if (u.origin !== s.allowedOrigin) {
                broadcastBrowserEvent(sessionId, { type: 'goto_blocked', stepId: sid, ts: now(), url: cur, reason: 'same_site_blocked', message: 'cross_site_blocked' });
                try { await page.goBack({ waitUntil: 'domcontentloaded', timeout: cfg.navTimeoutMs }); } catch { }
                results.push({ stepId: sid, name, ok: false, reason: 'same_site_blocked', message: cur });
                try {
                  broadcastBrowserEvent(sessionId, {
                    type: 'action_error',
                    ts: now(),
                    actionId: sid,
                    actionType: name,
                    reason: 'same_site_blocked',
                    error: 'cross_site_blocked',
                  });
                } catch { }
                continue;
              }
            } catch { }
          }

          broadcastBrowserEvent(sessionId, { type: 'step_done', stepId: sid, name, ts: now() });
          results.push({ stepId: sid, name, ok: true });
          try {
            broadcastBrowserEvent(sessionId, { type: 'action_done', ts: now(), actionId: sid, actionType: name });
          } catch { }
          continue;
        }

        results.push({ stepId: sid, name, ok: false, reason: 'unknown', message: 'unsupported_action' });
        broadcastBrowserEvent(sessionId, { type: 'step_error', stepId: sid, name, ts: now(), reason: 'unknown', message: 'unsupported_action' });
        try {
          broadcastBrowserEvent(sessionId, {
            type: 'action_error',
            ts: now(),
            actionId: sid,
            actionType: name,
            reason: 'unknown',
            error: 'unsupported_action',
          });
        } catch { }
      } catch (e: any) {
        const msg = String(e?.message || e);
        const reason: FailureReason = /timeout/i.test(msg) ? 'timeout' : 'unknown';
        results.push({ stepId: sid, name, ok: false, reason, message: msg });
        broadcastBrowserEvent(sessionId, { type: 'step_error', stepId: sid, name, ts: now(), reason, message: msg });
        try {
          broadcastBrowserEvent(sessionId, {
            type: 'action_error',
            ts: now(),
            actionId: sid,
            actionType: name,
            reason,
            error: msg,
          });
        } catch { }
        setStreamMask(sessionId, []);
      }
    }

    const ok = results.every((r) => r.ok);
    const summary = ok ? 'تم تنفيذ المهمة بنجاح.' : 'فشل تنفيذ بعض الخطوات.';
    broadcastBrowserEvent(sessionId, {
      type: 'final_report',
      ts: now(),
      ok,
      summary,
      steps: results,
      evidence,
    });
    if (ok) {
      broadcastBrowserEvent(sessionId, { type: 'final_success', ts: now(), summary });
    } else {
      broadcastBrowserEvent(sessionId, { type: 'final_failed', ts: now(), summary, reason: 'some_steps_failed' });
    }
    try {
      broadcastBrowserEvent(sessionId, { type: 'session_status', ts: now(), sessionId, url: page.url(), workerStatus: 'idle' });
    } catch { }

    touchSession(sessionId);
    return { ok, summary, steps: results, evidence };
  });
}

