    }
}

import { BaseTool } from '../base';
import { executeTool } from '../../services/ToolService'; // Import the dispatcher
import { ToolPermission } from '../types';

export class TaskLoopTool extends BaseTool {
    name = 'task_loop';
    description = 'Execute a multi-step plan with self-correction and context preservation.';
    version = '1.0.1'; // 1.0.1: Extracted to class
    tags = ['agent', 'recursive', 'loop', 'automation'];

    inputSchema = {
        type: 'object' as const,
        properties: {
            goal: { type: 'string' },
            steps: {
                type: 'array',
                items: {
                    type: 'object',
                    properties: {
                        name: { type: 'string' },
                        tool: { type: 'string' },
                        args: { type: 'object' }
                    }
                }
            },
            maxIterations: { type: 'number' }
        },
        required: ['goal', 'steps']
    };

    outputSchema = {
        type: 'object' as const,
        properties: {
            success: { type: 'boolean' },
            completedSteps: { type: 'number' },
            results: { type: 'array' }
        }
    };

    permissions: ToolPermission[] = ['execute', 'internet', 'read', 'write'];
    sideEffects: ToolPermission[] = ['execute', 'write'];
    rateLimitPerMinute = 2;
    auditFields = ['goal'];

    async execute(input: any) {
        const logs: string[] = [];
        const steps = Array.isArray(input.tasks) ? input.tasks : (input.steps || []);
        const results: any[] = [];
        let success = true;

        logs.push(`Starting TaskLoop for: ${input.goal || 'unspecified'} (${steps.length} steps)`);

        for (let i = 0; i < steps.length; i++) {
            const step = steps[i];
            logs.push(`Step ${i + 1}: ${step.name || step.tool}`);

            try {
                // Execute the tool via Registry Dispatcher
                const result = await executeTool(step.tool, step.args || {});
                results.push({ step: i, tool: step.tool, ok: result.ok, output: result.output, error: result.error });

                if (!result.ok) {
                    logs.push(`Step failed: ${result.error}`);
                    // Simple self-correction: retry once
                    logs.push('Retrying step...');
                    const retry = await executeTool(step.tool, step.args || {});
                    results[i] = { step: i, tool: step.tool, ok: retry.ok, output: retry.output, error: retry.error, retried: true };

                    if (!retry.ok) {
                        success = false;
                        logs.push(`Retry failed. Aborting loop.`);
                        break;
                    }
                }
            } catch (e: any) {
                logs.push(`Exception in step: ${e.message}`);
                success = false;
                break;
            }
        }

        return { ok: success, output: { success, completedSteps: results.length, results }, logs };
    }
}

import { BaseTool } from '../base';
import { ToolPermission } from '../types';
import { broadcast } from '../../ws';

export class TaskLifecycleTool extends BaseTool {
    name = 'task_lifecycle';
    description = 'Manage the lifecycle of an agent task loop. Use this to update the UI with your current status, summary, and mode.';
    version = '1.0.0';
    tags = ['system', 'ui', 'lifecycle'];
    inputSchema = {
        type: 'object' as const,
        properties: {
            action: { type: 'string', enum: ['update', 'complete', 'fail'] },
            taskName: { type: 'string' },
            taskStatus: { type: 'string', description: 'What you are doing right now (e.g. "Scanning files...")' },
            taskSummary: { type: 'string', description: 'What you have done so far.' },
            mode: { type: 'string', enum: ['PLANNING', 'EXECUTION', 'VERIFICATION'] }
        },
        required: ['action']
    };
    outputSchema = { type: 'object' as const, properties: { success: { type: 'boolean' } } };
    permissions: ToolPermission[] = [];
    sideEffects: ToolPermission[] = [];

    async execute(input: any) {
        const action = input.action || 'update';

        // Broadcast event to specific listening frontend components
        // "task_update" is a new event type we will support in the frontend
        broadcast({
            type: 'task_update',
            data: {
                action,
                taskName: input.taskName || 'Task',
                taskStatus: input.taskStatus,
                taskSummary: input.taskSummary,
                mode: input.mode || 'EXECUTION',
                timestamp: Date.now()
            }
        });

        return { ok: true, output: { success: true }, logs: [`Task ${action}: ${input.taskStatus}`] };
    }
}

import { BaseTool } from '../base';
import { ToolPermission } from '../types';
import fs from 'fs';
import path from 'path';
import { broadcast } from '../../ws';
// Store for persistent terminals
export const terminals = new Map<string, { pty: any, history: string[] }>();


/**
 * TerminalManagerTool: Persistent terminal sessions.
 * Equivalent to `read_terminal` / `create_terminal`.
 */
export class TerminalManagerTool extends BaseTool {
    name = 'terminal_manager';
    description = 'Manage persistent interactive terminal sessions (create, read, write, kill, resize).';
    version = '2.0.0';
    tags = ['shell', 'terminal', 'persistent', 'interactive'];
    inputSchema = {
        type: 'object' as const,
        properties: {
            action: { type: 'string', enum: ['create', 'read', 'write', 'kill', 'list', 'resize'] },
            id: { type: 'string' },
            command: { type: 'string', description: 'For write (input)' },
            cols: { type: 'number' },
            rows: { type: 'number' },
            shell: { type: 'string', default: 'bash' }
        },
        required: ['action']
    };
    outputSchema = { type: 'object' as const, properties: { output: { type: 'string' } } };
    permissions: ToolPermission[] = ['execute'];
    sideEffects: ToolPermission[] = ['execute'];

    async execute(input: any) {
        const action = input.action;
        const id = input.id || 'default';

        if (action === 'create') {
            if (terminals.has(id)) return { ok: false, error: 'Terminal already exists', logs: [] };

            try {
                let pty: any;
                try {
                    // Lazy load node-pty to prevent startup crashes if native bindings fail
                    pty = require('node-pty');
                } catch (e) {
                    return { ok: false, error: 'node-pty module not found or failed to load on this system.', logs: [] };
                }

                const shell = input.shell || (process.platform === 'win32' ? 'powershell.exe' : 'bash');
                const ptyProcess = pty.spawn(shell, [], {
                    name: 'xterm-color',
                    cols: input.cols || 80,
                    rows: input.rows || 30,
                    cwd: process.cwd(),
                    env: process.env
                });

                const term = { pty: ptyProcess, history: [] as string[] };
                terminals.set(id, term);

                ptyProcess.onData((data: string) => {
                    term.history.push(data);
                    if (term.history.length > 5000) term.history.shift();
                    broadcast({ type: 'terminal_output', id, data });
                });

                return { ok: true, output: { id, pid: ptyProcess.pid, message: 'Terminal created.' }, logs: [`term_create=${id}`] };
            } catch (e: any) {
                return { ok: false, error: `Failed to spawn PTY: ${e.message}`, logs: [] };
            }
        }

        if (action === 'read') {
            const term = terminals.get(id);
            if (!term) return { ok: false, error: 'Terminal not found', logs: [] };
            // Return concatenated history
            return { ok: true, output: { history: term.history.join('') }, logs: [] };
        }

        if (action === 'write') {
            const term = terminals.get(id);
            if (!term) return { ok: false, error: 'Terminal not found', logs: [] };

            if (!input.command) return { ok: false, error: 'command input required', logs: [] };
            term.pty.write(input.command);

            // Wait a bit for output
            await new Promise(r => setTimeout(r, 200));

            return { ok: true, output: { message: 'Input sent' }, logs: [`term_write=${id}`] };
        }

        if (action === 'resize') {
            const term = terminals.get(id);
            if (!term) return { ok: false, error: 'Terminal not found', logs: [] };
            term.pty.resize(input.cols || 80, input.rows || 30);
            return { ok: true, output: { message: 'Resized' }, logs: [] };
        }

        if (action === 'kill') {
            const term = terminals.get(id);
            if (!term) return { ok: false, error: 'Terminal not found', logs: [] };
            term.pty.kill();
            terminals.delete(id);
            return { ok: true, output: { message: 'Terminal killed' }, logs: [] };
        }

        if (action === 'list') {
            return { ok: true, output: { terminals: Array.from(terminals.keys()) }, logs: [] };
        }

        return { ok: false, error: 'Unknown action', logs: [] };
    }
}

/**
 * SafeReadFileTool: Paginated file reading.
 * Equivalent to `view_file`.
 */
export class SafeReadFileTool extends BaseTool {
    name = 'read_file';
    description = 'Read file content safely with pagination limits.';
    version = '1.0.0';
    tags = ['fs', 'read', 'safe'];
    inputSchema = {
        type: 'object' as const,
        properties: {
            path: { type: 'string' },
            startLine: { type: 'number', default: 1 },
            endLine: { type: 'number', default: 1000 }
        },
        required: ['path']
    };
    outputSchema = { type: 'object' as const, properties: { content: { type: 'string' }, totalLines: { type: 'number' } } };
    permissions: ToolPermission[] = ['read'];
    sideEffects: ToolPermission[] = [];

    async execute(input: any) {
        const filePath = input.path ? (path.isAbsolute(input.path) ? input.path : path.resolve(process.cwd(), input.path)) : '';
        if (!fs.existsSync(filePath)) return { ok: false, error: 'File not found', logs: [] };

        try {
            const content = fs.readFileSync(filePath, 'utf-8');
            const lines = content.split('\n');
            const start = Math.max(0, (input.startLine || 1) - 1);
            const end = Math.min(lines.length, (input.endLine || 1000));

            return {
                ok: true,
                output: {
                    content: lines.slice(start, end).join('\n'),
                    totalLines: lines.length,
                    truncated: lines.length > end
                },
                logs: [`read=${filePath} lines=${start + 1}-${end}`]
            };
        } catch (e: any) {
            return { ok: false, error: e.message, logs: [] };
        }
    }
}

/**
 * AskUserTool: Blocking input request.
 * Equivalent to `notify_user` with input expectation.
 */
export class AskUserTool extends BaseTool {
    name = 'ask_user';
    description = 'Ask the user a question and wait for a response. Use this if you are blocked or need clarification.';
    version = '1.0.0';
    tags = ['user', 'interaction', 'blocking'];
    inputSchema = {
        type: 'object' as const,
        properties: {
            question: { type: 'string' },
            options: { type: 'array', items: { type: 'string' } }
        },
        required: ['question']
    };
    outputSchema = { type: 'object' as const, properties: { response: { type: 'string' } } };
    permissions: ToolPermission[] = [];
    sideEffects: ToolPermission[] = []; // Technically blocks, but doesn't modify system

    async execute(input: any) {
        broadcast({
            type: 'user_input_request',
            data: {
                question: input.question,
                options: input.options,
                timestamp: Date.now()
            }
        });

        return {
            ok: true,
            output: { status: 'waiting_for_user_input', message: 'Request sent. Agent loop should now pause.' },
            logs: [`ask="${input.question}"`]
        };
    }
}

import { BaseTool } from '../base';
import { ToolPermission } from '../types';
import path from 'path';
import fs from 'fs';
import { exec } from 'child_process';
import util from 'util';
import { commandRouter } from '../../terminal/command-router';

// Background Process Store
const backgroundProcesses = new Map<string, { pid: number, command: string, startTime: number, process: any }>();

const execAsync = util.promisify(exec);
const spawn = require('child_process').spawn;

// Helper
function repoRoot() {
    const cwd = process.cwd();
    return path.basename(cwd) === 'api' ? path.resolve(cwd, '..') : cwd;
}

function resolveToolPath(p: string) {
    const root = repoRoot();
    const val = String(p ?? '').trim();
    if (!val || val === '.') return root;
    if (path.isAbsolute(val)) return val;
    const fromCwd = path.resolve(process.cwd(), val);
    if (fs.existsSync(fromCwd)) return fromCwd;
    return path.resolve(root, val);
}

