export class FileEditTool extends BaseTool {
    name = 'file_edit';
    description = 'Replace text in a file.';
    version = '1.0.0';
    tags = ['fs', 'edit', 'write'];
    inputSchema = {
        type: 'object' as const,
        properties: {
            filename: { type: 'string' },
            find: { type: 'string' },
            replace: { type: 'string' }
        },
        required: ['filename', 'find', 'replace']
    };
    outputSchema = { type: 'object' as const, properties: { success: { type: 'boolean' } } };
    permissions: ToolPermission[] = ['write', 'read'];
    sideEffects: ToolPermission[] = ['write'];
    rateLimitPerMinute = 60;
    auditFields = ['filename'];

    async execute(input: any) {
        const logs: string[] = [];
        const filename = String(input?.filename ?? '');
        const find = String(input?.find ?? '');
        const replace = String(input?.replace ?? '');
        const full = path.isAbsolute(filename) ? filename : path.resolve(process.cwd(), filename);

        if (!fs.existsSync(full)) return { ok: false, error: 'File not found', logs };

        let content = fs.readFileSync(full, 'utf-8');
        if (!content.includes(find)) {
            return { ok: false, error: 'Text to replace not found', logs };
        }
        content = content.replace(find, replace);
        fs.writeFileSync(full, content);
        logs.push(`edit=${filename}`);
        return { ok: true, output: { success: true }, logs };
    }
}

export class WriteFileTool extends BaseTool {
    name = 'write_file';
    description = 'Write content to a file. Overwrites if exists.';
    version = '1.0.0';
    tags = ['fs', 'write', 'create'];
    inputSchema = {
        type: 'object' as const,
        properties: {
            filename: { type: 'string' },
            content: { type: 'string' }
        },
        required: ['filename', 'content']
    };
    outputSchema = { type: 'object' as const, properties: { success: { type: 'boolean' } } };
    permissions: ToolPermission[] = ['write'];
    sideEffects: ToolPermission[] = ['write'];
    rateLimitPerMinute = 60;
    auditFields = ['filename'];

    async execute(input: any) {
        const logs: string[] = [];
        const filename = String(input?.filename ?? '');
        const content = String(input?.content ?? '');
        const full = path.isAbsolute(filename) ? filename : path.resolve(process.cwd(), filename);

        // Ensure directory exists
        const dir = path.dirname(full);
        if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });

        fs.writeFileSync(full, content);
        logs.push(`write=${filename}`);
        return { ok: true, output: { success: true }, logs };
    }
}

export class GrepSearchTool extends BaseTool {
    name = 'grep_search';
    description = 'Search for text patterns in files using grep.';
    version = '1.0.0';
    tags = ['fs', 'search', 'read'];
    inputSchema = {
        type: 'object' as const,
        properties: {
            query: { type: 'string' },
            path: { type: 'string' },
            include: { type: 'string' },
            exclude: { type: 'string' }
        },
        required: ['query']
    };
    outputSchema = { type: 'object' as const, properties: { matches: { type: 'array' }, count: { type: 'number' } } };
    permissions: ToolPermission[] = ['read', 'execute']; // Execute because it runs grep
    sideEffects: ToolPermission[] = [];
    rateLimitPerMinute = 60;
    auditFields = ['query', 'path'];

    async execute(input: any) {
        const logs: string[] = [];
        const query = String(input?.query ?? '');
        const searchPath = String(input?.path ?? '.');
        const include = String(input?.include ?? '');
        const exclude = String(input?.exclude ?? '');

        const root = repoRoot();
        const workDir = path.isAbsolute(searchPath) ? searchPath : path.resolve(root, searchPath);

        // Escape quotes
        let cmd = `grep -rnI "${query.replace(/"/g, '\\"')}" "${workDir}"`;

        if (include) {
            cmd += ` --include="${include}"`;
        }
        if (exclude) {
            cmd += ` --exclude-dir="${exclude}"`;
        } else {
            cmd += ` --exclude-dir="node_modules" --exclude-dir=".git" --exclude-dir="dist" --exclude-dir="build"`;
        }

        logs.push(`grep.cmd=${cmd}`);
        try {
            const { stdout } = await execAsync(cmd, { maxBuffer: 1024 * 1024 * 5 });
            const lines = stdout.split('\n').filter(Boolean).slice(0, 100);
            return { ok: true, output: { matches: lines, count: lines.length, truncated: lines.length === 100 }, logs };
        } catch (err: any) {
            // grep exit code 1 means no match
            if (err.code === 1) {
                return { ok: true, output: { matches: [], count: 0 }, logs };
            }
            logs.push(`grep.error=${err.message}`);
            return { ok: false, error: err.message, logs };
        }
    }
}

export class NpmManagerTool extends BaseTool {
    name = 'npm_manager';
    description = 'Manage npm dependencies and run scripts.';
    version = '1.0.0';
    tags = ['npm', 'package', 'install'];
    inputSchema = {
        type: 'object' as const,
        properties: { command: { type: 'string' }, packages: { type: 'array', items: { type: 'string' } }, dev: { type: 'boolean' } },
        required: ['command']
    };
    outputSchema = { type: 'object' as const, properties: { output: { type: 'string' } } };
    permissions: ToolPermission[] = ['execute', 'write', 'internet'];
    sideEffects: ToolPermission[] = ['execute', 'write', 'internet'];
    rateLimitPerMinute = 10;

    async execute(input: any) {
        const logs: string[] = [];
        const cmd = String(input?.command);
        const pkgs = (input?.packages as string[]) || [];
        const isDev = !!input?.dev;

        try {
            let fullCmd = `npm ${cmd}`;
            if (pkgs.length > 0) fullCmd += ` ${pkgs.join(' ')}`;
            if (isDev && (cmd === 'install' || cmd === 'i')) fullCmd += ' -D';

            logs.push(`npm.cmd=${fullCmd}`);
            const { stdout } = await execAsync(fullCmd, { cwd: process.cwd() });

            if ((cmd === 'install' || cmd === 'i') && pkgs.length > 0) {
                const typesToInstall = pkgs.filter(p => !p.startsWith('@types/')).map(p => `@types/${p.split('@')[0]}`);
                if (typesToInstall.length) {
                    try {
                        await execAsync(`npm install -D ${typesToInstall.join(' ')}`, { cwd: process.cwd() });
                        logs.push(`npm.auto_types=${typesToInstall.join(' ')}`);
                    } catch { }
                }
            }

            return { ok: true, output: { output: stdout }, logs };
        } catch (e: any) {
            return { ok: false, error: e.message || e.stderr, logs };
        }
    }
}

export class ScaffoldProjectTool extends BaseTool {
    name = 'scaffold_project';
    description = 'Scaffold a project structure from a definition object.';
    version = '1.0.0';
    tags = ['scaffold', 'fs', 'generate'];
    inputSchema = {
        type: 'object' as const,
        properties: { structure: { type: 'object' }, baseDir: { type: 'string' } },
        required: ['structure']
    };
    outputSchema = { type: 'object' as const, properties: { created: { type: 'array' }, errors: { type: 'array' } } };
    permissions: ToolPermission[] = ['write'];
    sideEffects: ToolPermission[] = ['write'];

    async execute(input: any) {
        const logs: string[] = [];
        const structure = input?.structure || {};
        const baseDir = String(input?.baseDir || '.');
        const resolvedBase = path.isAbsolute(baseDir) ? baseDir : path.resolve(process.cwd(), baseDir);
        const created: string[] = [];
        const errors: string[] = [];

        for (const [relativePath, content] of Object.entries(structure)) {
            const fullPath = path.join(resolvedBase, relativePath);
            try {
                if (content === null) {
                    if (!fs.existsSync(fullPath)) {
                        fs.mkdirSync(fullPath, { recursive: true });
                        created.push(`${relativePath}/`);
                    }
                } else {
                    const dir = path.dirname(fullPath);
                    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
                    fs.writeFileSync(fullPath, String(content));
                    created.push(relativePath);
                }
            } catch (e: any) {
                errors.push(`${relativePath}: ${e.message}`);
            }
        }
        return { ok: errors.length === 0, output: { created, errors }, logs };
    }
}

export class ShellExecuteTool extends BaseTool {
    name = 'shell_execute';
    description = 'Execute shell commands with persistent CWD state.';
    version = '1.0.0';
    tags = ['shell', 'execute', 'terminal'];
    inputSchema = {
        type: 'object' as const,
        properties: {
            cwd: { type: 'string' },
            serverId: { type: 'string', description: 'ID of the remote server to execute on' },
            timeout: { type: 'number' },
            background: { type: 'boolean', description: 'Run command in background (fire and forget)' },
            dryRun: { type: 'boolean' }
        },
        required: ['command']
    };
    outputSchema = { type: 'object' as const, properties: { status: { type: 'string' }, stdout: { type: 'string' }, stderr: { type: 'string' }, exitCode: { type: 'number' } } };
    permissions: ToolPermission[] = ['execute'];
    sideEffects: ToolPermission[] = ['execute'];
    rateLimitPerMinute = 20;
    auditFields = ['command', 'cwd'];

    async execute(input: any) {
        const startedAt = Date.now();
        const logs: string[] = [];
        const command = String(input?.command ?? '');
        let cwdInput = String(input?.cwd ?? '');
        const timeoutVal = Number(input?.timeout ?? 30000);
        const background = !!input?.background;
        const dryRun = !!input?.dryRun;

        const redactCmd = (s: string) => {
            let out = String(s || '');
            out = out.replace(/(authorization\s*:\s*bearer\s+)[^\s]+/gi, '$1[REDACTED]');
            out = out.replace(/(\btoken\s*=\s*)[^&\s]+/gi, '$1[REDACTED]');
            out = out.replace(/(\bpassword\s*=\s*)[^&\s]+/gi, '$1[REDACTED]');
            out = out.replace(/(\bapi[_-]?key\s*=\s*)[^&\s]+/gi, '$1[REDACTED]');
            out = out.replace(/(\bsecret\s*=\s*)[^&\s]+/gi, '$1[REDACTED]');
            out = out.replace(/(\b--token\s+)[^\s]+/gi, '$1[REDACTED]');
            return out; // Shortened for brevity
        };

        if (dryRun) {
            const safeCmd = redactCmd(command);
            return { ok: true, output: { dryRun: true, status: 'success', command: safeCmd, stdout: `[dry run] ${safeCmd}`, exitCode: 0 }, logs: [`dryRun: ${safeCmd}`] };
        }

        // Simplistic safety
        if (command.includes('rm -rf /') || command.includes('sudo')) {
            const safeCmd = redactCmd(command);
            logs.push(`exec=${safeCmd} blocked=1`);
            return { ok: false, error: 'command_not_allowed', logs };
        }

        // Persistent CWD
        const stateFile = path.join(process.cwd(), '.joe', 'shell_state.json');
        if (!cwdInput && fs.existsSync(stateFile)) {
            try {
                const state = JSON.parse(fs.readFileSync(stateFile, 'utf-8'));
                if (state.cwd && fs.existsSync(state.cwd)) cwdInput = state.cwd;
            } catch { }
        }

        const workDir = cwdInput ? (path.isAbsolute(cwdInput) ? cwdInput : path.resolve(process.cwd(), cwdInput)) : process.cwd();



        try {
            if (background) {
                // Background Execution (Local only for now)
                if (input.serverId) {
                    throw new Error('Background execution not yet supported for remote servers');
                }
                const id = 'bg_' + Date.now() + '_' + Math.floor(Math.random() * 1000);
                // ... (rest of background logic remains same for local)
                const child = spawn(command, [], {
                    cwd: workDir,
                    shell: true,
                    detached: true,
                    stdio: 'ignore'
                });

                child.unref();

                backgroundProcesses.set(id, {
                    pid: child.pid,
                    command: command,
                    startTime: Date.now(),
                    process: child
                });

                logs.push(`exec_bg=${redactCmd(command)} id=${id} pid=${child.pid}`);
                return {
                    ok: true,
                    output: { status: 'background', id, pid: child.pid, message: 'Command started in background.' },
                    logs
                };
            }

            // Route execution (Local or Remote)
            const result = await commandRouter.execute({
                command,
                serverId: input.serverId,
                workingDirectory: workDir,
                timeout: timeoutVal
            });

            const durationMs = Date.now() - startedAt;
            logs.push(`exec=${redactCmd(command)} server=${input.serverId || 'local'} exit=${result.code}`);

            return {
                ok: result.code === 0,
                output: {
                    status: result.code === 0 ? 'success' : 'failed',
                    stdout: result.stdout,
                    stderr: result.stderr,
                    exitCode: result.code,
                    cwd: workDir,
                    durationMs,
                    executedOn: result.executedOn,
                    serverId: result.serverId
                },
                logs
            };

        } catch (e: any) {
            const durationMs = Date.now() - startedAt;
            const logCmd = redactCmd(command);
            logs.push(`exec_error=${logCmd} err=${e.message}`);
            return { ok: false, error: e.message || 'Command failed', output: { status: 'failed', stdout: e.stdout || '', stderr: e.stderr || e.message, exitCode: e.code || 1, cwd: workDir, durationMs }, logs };
        }
    }
}

export class ShellStatusTool extends BaseTool {
    name = 'shell_check_status';
    description = 'Check the status of a background command.';
    version = '1.0.0';
    tags = ['shell', 'status'];
    inputSchema = { type: 'object' as const, properties: { id: { type: 'string' } }, required: ['id'] };
    outputSchema = { type: 'object' as const, properties: { running: { type: 'boolean' } } };
    permissions: ToolPermission[] = [];
    sideEffects: ToolPermission[] = [];

    async execute(input: any) {
        const id = String(input.id);
        const proc = backgroundProcesses.get(id);
        if (!proc) return { ok: false, error: 'Process not found', logs: [] };

        // Check if PID is running
        let running = true;
        try {
            process.kill(proc.pid, 0); // signal 0 just checks existence
        } catch (e) {
            running = false;
        }

        if (!running) {
            backgroundProcesses.delete(id); // Cleanup dead
        }

        return {
            ok: true,
            output: { running, pid: proc.pid, command: proc.command, uptime: Date.now() - proc.startTime },
            logs: []
        };
    }
}

import { ToolDefinition } from '../types';
import fs from 'fs';
import path from 'path';

/**
 * SecurityScannerTool - Security vulnerability scanner
 * Detects common security issues in code
 */
export class SecurityScannerTool implements ToolDefinition {
    name = 'security_scanner';
    version = '1.0.0';
    description = 'Scan code for security vulnerabilities and best practices';
    tags = ['security', 'scanner', 'vulnerabilities'];

    inputSchema = {
        type: 'object' as const,
        properties: {
            files: {
                type: 'array' as const,
                items: { type: 'string' as const },
                description: 'Files to scan'
            },
            projectPath: {
                type: 'string' as const,
                description: 'Project base path'
            }
        },
        required: ['files']
    };

    outputSchema = {
        type: 'object' as const,
        properties: {
            vulnerabilities: {
                type: 'array' as const,
                items: { type: 'object' as const }
            },
            riskScore: { type: 'number' as const }
        }
    };

    permissions = ['read' as const];
    sideEffects = [];
    rateLimitPerMinute = 20;
    auditFields = ['projectPath'];
    mockSupported = false;

    async execute(input: { files: string[]; projectPath?: string }) {
        const { files, projectPath = '.' } = input;
        const logs: string[] = [];

        try {
            logs.push(`Scanning ${files.length} files for security vulnerabilities`);

            const vulnerabilities: any[] = [];

            for (const file of files) {
                const filePath = path.isAbsolute(file) ? file : path.resolve(projectPath, file);

                if (!fs.existsSync(filePath)) continue;

                const content = fs.readFileSync(filePath, 'utf-8');
                const vulns = this.scanFile(filePath, content);

                vulnerabilities.push(...vulns);
            }

            const riskScore = this.calculateRiskScore(vulnerabilities);

            logs.push(`Scan complete. Found ${vulnerabilities.length} potential issues. Risk: ${riskScore}/100`);

            return {
                ok: true,
                output: {
                    vulnerabilities,
                    riskScore,
                    summary: {
                        critical: vulnerabilities.filter(v => v.severity === 'critical').length,
                        high: vulnerabilities.filter(v => v.severity === 'high').length,
                        medium: vulnerabilities.filter(v => v.severity === 'medium').length,
                        low: vulnerabilities.filter(v => v.severity === 'low').length
                    }
                },
                logs
            };

        } catch (error: any) {
            logs.push(`Error: ${error.message}`);
            return {
                ok: false,
                error: error.message,
                logs
            };
        }
    }

    private scanFile(filePath: string, content: string): any[] {
        const vulnerabilities: any[] = [];
        const fileName = path.basename(filePath);

        // SQL Injection patterns
        if (content.match(/query.*\+.*req\.(body|params|query)/i)) {
            vulnerabilities.push({
                file: fileName,
                severity: 'critical',
                type: 'SQL Injection',
                message: 'Potential SQL injection vulnerability. Use parameterized queries.',
                cwe: 'CWE-89'
            });
        }

        // XSS patterns
        if (content.match(/innerHTML.*=.*req\.(body|params|query)/i)) {
            vulnerabilities.push({
                file: fileName,
                severity: 'high',
                type: 'XSS',
                message: 'Potential XSS vulnerability. Sanitize user input before rendering.',
                cwe: 'CWE-79'
            });
        }

        // Hardcoded secrets
        if (content.match(/(password|secret|api_key|token)\s*=\s*['"][^'"]{8,}['"]/i)) {
            vulnerabilities.push({
                file: fileName,
                severity: 'critical',
                type: 'Hardcoded Secret',
                message: 'Hardcoded credentials detected. Use environment variables.',
                cwe: 'CWE-798'
            });
        }

        // Insecure randomness
        if (content.includes('Math.random()') && content.match(/(password|token|session)/i)) {
            vulnerabilities.push({
                file: fileName,
                severity: 'medium',
                type: 'Weak Randomness',
                message: 'Math.random() is not cryptographically secure. Use crypto.randomBytes().',
                cwe: 'CWE-330'
            });
        }

        // eval() usage
        if (content.match(/eval\s*\(/)) {
            vulnerabilities.push({
                file: fileName,
                severity: 'high',
                type: 'Code Injection',
                message: 'eval() is dangerous and should be avoided.',
                cwe: 'CWE-95'
            });
        }

        // Insecure HTTP
        if (content.match(/http:\/\/[^'"]*api/i)) {
            vulnerabilities.push({
                file: fileName,
                severity: 'medium',
                type: 'Insecure Communication',
                message: 'Use HTTPS for API communications.',
                cwe: 'CWE-319'
            });
        }

        // Missing input validation
        if (content.match(/req\.(body|params|query)\.\w+/) && !content.includes('validate')) {
            vulnerabilities.push({
                file: fileName,
                severity: 'low',
                type: 'Missing Validation',
                message: 'Consider adding input validation.',
                cwe: 'CWE-20'
            });
        }

        return vulnerabilities;
    }

    private calculateRiskScore(vulnerabilities: any[]): number {
        const weights = {
            critical: 25,
            high: 15,
            medium: 8,
            low: 3
        };

        const score = vulnerabilities.reduce((sum, v) => {
            return sum + (weights[v.severity as keyof typeof weights] || 0);
        }, 0);

        return Math.min(100, score);
    }
}

import { BaseTool } from '../base';
import { ToolPermission } from '../types';
import { search, SafeSearchType } from 'duck-duck-scrape';

export class SearchApiTool extends BaseTool {
    name = 'search_api';
    description = 'Perform a fast web search using DuckDuckGo API. Best for quick answers and finding URLs.';
    version = '1.0.0';
    tags = ['search', 'web', 'fast'];
    inputSchema = {
        type: 'object' as const,
        properties: {
            query: { type: 'string' },
            limit: { type: 'number', default: 5 }
        },
        required: ['query']
    };
    outputSchema = {
        type: 'object' as const,
        properties: {
            results: { type: 'array' }
        }
    };
    permissions: ToolPermission[] = ['internet'];
    sideEffects: ToolPermission[] = [];
    rateLimitPerMinute = 20;
    auditFields = ['query'];

    async execute(input: any) {
        const query = String(input.query || '');
        const limit = Number(input.limit || 5);

        if (!query) return { ok: false, error: 'query is required', logs: [] };

        try {
            const results = await search(query, {
                safeSearch: SafeSearchType.STRICT,
                offset: 0
            });

            if (results.noResults) {
                return { ok: true, output: { results: [] }, logs: ['No results found'] };
            }

            const simplified = results.results.slice(0, limit).map((r: any) => ({
                title: r.title,
                url: r.url,
                description: r.description
            }));

            return {
                ok: true,
                output: { results: simplified },
                logs: [`searched="${query}" found=${simplified.length}`]
            };

        } catch (e: any) {
            return { ok: false, error: `Search Failed: ${e.message}`, logs: [] };
        }
    }
}

import { ToolDefinition } from '../types';

/**
 * RetryManagerTool - Intelligent retry logic with exponential backoff
 * Provides resilient operation retry capabilities
 */
export class RetryManagerTool implements ToolDefinition {
    name = 'retry_manager';
    version = '1.0.0';
    description = 'Manage retries with exponential backoff and success tracking';
    tags = ['retry', 'resilience', 'error-handling'];

    inputSchema = {
        type: 'object' as const,
        properties: {
            action: {
                type: 'string' as const,
                enum: ['configure', 'execute', 'stats'],
                description: 'Action to perform'
            },
            operationId: {
                type: 'string' as const,
                description: 'Operation identifier'
            },
            maxAttempts: {
                type: 'number' as const,
                description: 'Maximum retry attempts (default: 3)'
            },
            initialDelay: {
                type: 'number' as const,
                description: 'Initial delay in ms (default: 1000)'
            },
            maxDelay: {
                type: 'number' as const,
                description: 'Maximum delay in ms (default: 30000)'
            },
            backoffMultiplier: {
                type: 'number' as const,
                description: 'Backoff multiplier (default: 2)'
            },
            operation: {
                type: 'object' as const,
                description: 'Operation to retry',
                properties: {
                    type: { type: 'string' as const },
                    params: { type: 'object' as const }
                }
            }
        },
        required: ['action']
    };

    outputSchema = {
        type: 'object' as const,
        properties: {
            success: { type: 'boolean' as const },
            attempts: { type: 'number' as const },
            result: { type: 'object' as const },
            stats: { type: 'object' as const }
        }
    };

    permissions = [];
    sideEffects = ['execute' as const];
    rateLimitPerMinute = 30;
    auditFields = ['action', 'operationId'];
    mockSupported = false;

    // In-memory retry configuration and stats
    private static configs = new Map<string, {
        maxAttempts: number;
        initialDelay: number;
        maxDelay: number;
        backoffMultiplier: number;
    }>();

    private static stats = new Map<string, {
        totalAttempts: number;
        successfulRetries: number;
        failedRetries: number;
        averageAttempts: number;
    }>();

    async execute(input: { action: string; operationId?: string; maxAttempts?: number; initialDelay?: number; maxDelay?: number; backoffMultiplier?: number; operation?: any }) {
        const { action, operationId, maxAttempts, initialDelay, maxDelay, backoffMultiplier, operation } = input;
        const logs: string[] = [];

        try {
            logs.push(`RetryManager: ${action}`);

            switch (action) {
                case 'configure':
                    return this.configureRetry(operationId || 'default', maxAttempts, initialDelay, maxDelay, backoffMultiplier, logs);

                case 'execute':
                    return this.executeWithRetry(operationId || 'default', operation, logs);

                case 'stats':
                    return this.getStats(operationId, logs);

                default:
                    throw new Error(`Unknown action: ${action}`);
            }

        } catch (error: any) {
            logs.push(`Error: ${error.message}`);
            return {
                ok: false,
                error: error.message,
                logs
            };
        }
    }

    private configureRetry(operationId: string, maxAttempts: number | undefined, initialDelay: number | undefined, maxDelay: number | undefined, backoffMultiplier: number | undefined, logs: string[]) {
        const config = {
            maxAttempts: maxAttempts || 3,
            initialDelay: initialDelay || 1000,
            maxDelay: maxDelay || 30000,
            backoffMultiplier: backoffMultiplier || 2
        };

        RetryManagerTool.configs.set(operationId, config);

        logs.push(`Configured retry for ${operationId}: ${config.maxAttempts} attempts, ${config.initialDelay}ms initial delay`);

        return {
            ok: true,
            output: {
                success: true,
                operationId,
                config,
                message: `Retry configuration set for ${operationId}`
            },
            logs
        };
    }

    private async executeWithRetry(operationId: string, operation: any, logs: string[]) {
        const config = RetryManagerTool.configs.get(operationId) || {
            maxAttempts: 3,
            initialDelay: 1000,
            maxDelay: 30000,
            backoffMultiplier: 2
        };

        let attempts = 0;
        let lastError: any = null;
        let delay = config.initialDelay;

        while (attempts < config.maxAttempts) {
            attempts++;
            logs.push(`Attempt ${attempts}/${config.maxAttempts}`);

            try {
                // Simulate operation execution
                // In production, this would call the actual operation
                const result = await this.simulateOperation(operation);

                // Update stats
                this.updateStats(operationId, attempts, true);

                logs.push(`Operation succeeded on attempt ${attempts}`);

                return {
                    ok: true,
                    output: {
                        success: true,
                        attempts,
                        result,
                        message: `Operation succeeded after ${attempts} attempt(s)`
                    },
                    logs
                };

            } catch (error: any) {
                lastError = error;
                logs.push(`Attempt ${attempts} failed: ${error.message}`);

                if (attempts < config.maxAttempts) {
                    logs.push(`Waiting ${delay}ms before retry...`);
                    await this.sleep(delay);
                    delay = Math.min(delay * config.backoffMultiplier, config.maxDelay);
                }
            }
        }

        // All attempts failed
        this.updateStats(operationId, attempts, false);

        logs.push(`All ${attempts} attempts failed`);

        return {
            ok: false,
            error: `Operation failed after ${attempts} attempts: ${lastError?.message || 'Unknown error'}`,
            output: {
                success: false,
                attempts,
                lastError: lastError?.message
            },
            logs
        };
    }

    private async simulateOperation(operation: any): Promise<any> {
        // Simulate operation with 70% success rate
        const random = Math.random();
        if (random > 0.7) {
            throw new Error('Simulated operation failure');
        }

        return {
            status: 'success',
            data: operation?.params || {},
            timestamp: new Date().toISOString()
        };
    }

    private sleep(ms: number): Promise<void> {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

    private updateStats(operationId: string, attempts: number, success: boolean) {
        const stats = RetryManagerTool.stats.get(operationId) || {
            totalAttempts: 0,
            successfulRetries: 0,
            failedRetries: 0,
            averageAttempts: 0
        };

        stats.totalAttempts += attempts;
        if (success) {
            stats.successfulRetries++;
        } else {
            stats.failedRetries++;
        }

        const totalOperations = stats.successfulRetries + stats.failedRetries;
        stats.averageAttempts = stats.totalAttempts / totalOperations;

        RetryManagerTool.stats.set(operationId, stats);
    }

    private getStats(operationId: string | undefined, logs: string[]) {
        if (operationId) {
            const stats = RetryManagerTool.stats.get(operationId);
            if (!stats) {
                throw new Error(`No stats found for operation ${operationId}`);
            }

            logs.push(`Retrieved stats for ${operationId}`);

            return {
                ok: true,
                output: {
                    success: true,
                    operationId,
                    stats
                },
                logs
            };
        }

        // Return all stats
        const allStats = Object.fromEntries(RetryManagerTool.stats);

        logs.push(`Retrieved stats for ${Object.keys(allStats).length} operations`);

        return {
            ok: true,
            output: {
                success: true,
                stats: allStats
            },
            logs
        };
    }
}

import { ToolDefinition } from '../types';
import { callLLM } from '../../llm';

/**
 * RequestAnalyzerTool - Advanced request analysis using LLM
 * Analyzes complex build requests to extract requirements, modules, and complexity
 */
export class RequestAnalyzerTool implements ToolDefinition {
    name = 'request_analyzer';
    version = '1.0.0';
    description = 'Analyze complex build requests to extract requirements, modules, and estimate complexity';
    tags = ['analysis', 'planning', 'llm'];

    inputSchema = {
        type: 'object' as const,
        properties: {
            userRequest: {
                type: 'string' as const,
                description: 'The user\'s build request to analyze'
            },
            context: {
                type: 'object' as const,
                description: 'Optional context (session info, previous messages, etc.)',
                properties: {
                    sessionId: { type: 'string' as const },
                    previousMessages: {
                        type: 'array' as const,
                        items: { type: 'object' as const },
                        description: 'Previous conversation messages'
                    }
                }
            }
        },
        required: ['userRequest']
    };

    outputSchema = {
        type: 'object' as const,
        properties: {
            projectType: { type: 'string' as const },
            complexity: { type: 'string' as const },
            modules: { type: 'array' as const },
            estimatedFiles: { type: 'number' as const },
            techStack: { type: 'object' as const },
            requirements: { type: 'array' as const }
        }
    };

    permissions = [];
    sideEffects = [];
    rateLimitPerMinute = 10; // Limit LLM calls
    auditFields = ['userRequest'];
    mockSupported = false;

    async execute(input: { userRequest: string; context?: any }) {
        const { userRequest, context } = input;
        const logs: string[] = [];

        try {
            logs.push(`Analyzing request: "${userRequest.slice(0, 100)}..."`);

            // Construct analysis prompt
            const analysisPrompt = `You are an expert software architect. Analyze the following build request and provide a structured analysis.

USER REQUEST:
${userRequest}

Provide your analysis in the following JSON format:
{
  "projectType": "fullstack|api|website|dashboard|cms|ecommerce|mobile|other",
  "complexity": "simple|medium|complex|very_complex",
  "estimatedFiles": <number>,
  "modules": ["module1", "module2", ...],
  "techStack": {
    "frontend": "react|vue|angular|html|none",
    "backend": "node|python|java|none",
    "database": "mongodb|postgresql|mysql|none",
    "other": ["tool1", "tool2"]
  },
  "requirements": [
    {
      "category": "functional|technical|design",
      "description": "requirement description",
      "priority": "high|medium|low"
    }
  ],
  "phases": [
    {
      "name": "Phase name",
      "tasks": ["task1", "task2"],
      "estimatedTime": "X minutes"
    }
  ]
}

IMPORTANT: Return ONLY valid JSON, no markdown, no explanations.`;

            // Call LLM for analysis using correct signature
            const llmContext = [
                { role: 'system', content: 'You are a software architect that returns only valid JSON.' }
            ];

            const response = await callLLM(analysisPrompt, llmContext);

            logs.push(`LLM analysis completed`);

            // Parse LLM response
            let analysis;
            try {
                // Extract JSON from response (in case LLM adds markdown)
                const jsonMatch = response.match(/\{[\s\S]*\}/);
                const jsonStr = jsonMatch ? jsonMatch[0] : response;
                analysis = JSON.parse(jsonStr);
            } catch (parseError) {
                logs.push(`JSON parse error: ${parseError}`);
                // Fallback to basic analysis
                analysis = this.fallbackAnalysis(userRequest);
            }

            // Validate and enrich analysis
            analysis = this.validateAnalysis(analysis, userRequest);

            logs.push(`Analysis complete: ${analysis.projectType}, ${analysis.complexity}, ${analysis.modules.length} modules`);

            return {
                ok: true,
                output: analysis,
                logs
            };

        } catch (error: any) {
            logs.push(`Error: ${error.message}`);
            return {
                ok: false,
                error: error.message,
                output: this.fallbackAnalysis(userRequest),
                logs
            };
        }
    }

    /**
     * Fallback analysis when LLM fails
     */
    private fallbackAnalysis(userRequest: string): any {
        const text = userRequest.toLowerCase();

        // Simple keyword-based detection
        const hasAuth = /auth|login|register|signup/i.test(text);
        const hasDatabase = /database|mongodb|postgres|sql|data/i.test(text);
        const hasUI = /ui|interface|dashboard|page|component/i.test(text);
        const hasAPI = /api|endpoint|rest|graphql/i.test(text);

        const modules: string[] = [];
        if (hasAuth) modules.push('authentication');
        if (hasDatabase) modules.push('database');
        if (hasUI) modules.push('ui');
        if (hasAPI) modules.push('api');

        // Estimate complexity based on keywords
        const complexityScore = modules.length +
            (text.split('module').length - 1) +
            (text.split('feature').length - 1);

        const complexity = complexityScore < 3 ? 'simple' :
            complexityScore < 6 ? 'medium' :
                complexityScore < 10 ? 'complex' : 'very_complex';

        return {
            projectType: hasUI && hasAPI ? 'fullstack' : hasAPI ? 'api' : 'website',
            complexity,
            modules,
            estimatedFiles: modules.length * 5,
            techStack: {
                frontend: hasUI ? 'react' : 'none',
                backend: hasAPI ? 'node' : 'none',
                database: hasDatabase ? 'mongodb' : 'none',
                other: []
            },
            requirements: [],
            phases: [],
            fallback: true
        };
    }

    /**
     * Validate and ensure analysis has required fields
     */
    private validateAnalysis(analysis: any, userRequest: string): any {
        return {
            projectType: analysis.projectType || 'other',
            complexity: analysis.complexity || 'medium',
            modules: Array.isArray(analysis.modules) ? analysis.modules : [],
            estimatedFiles: typeof analysis.estimatedFiles === 'number' ? analysis.estimatedFiles : 10,
            techStack: analysis.techStack || { frontend: 'none', backend: 'none', database: 'none', other: [] },
            requirements: Array.isArray(analysis.requirements) ? analysis.requirements : [],
            phases: Array.isArray(analysis.phases) ? analysis.phases : [],
            originalRequest: userRequest.slice(0, 200)
        };
    }
}

import { BaseTool } from '../base';
import { ToolPermission } from '../types';
import { exec } from 'child_process';
import { promisify } from 'util';

const execAsync = promisify(exec);

export class SonarAnalysisTool extends BaseTool {
    name = 'sonar_analysis';
    description = 'Run Static Code Analysis using SonarScanner (or mock if missing).';
    version = '1.0.0';
    tags = ['quality', 'security', 'static-analysis'];
    inputSchema = {
        type: 'object' as const,
        properties: {
            projectKey: { type: 'string' },
            sources: { type: 'string', default: '.' }
        },
        required: ['projectKey']
    };
    outputSchema = { type: 'object' as const, properties: { summary: { type: 'string' } } };
    permissions: ToolPermission[] = ['execute', 'internet'];
    sideEffects: ToolPermission[] = ['execute'];

    async execute(input: any) {
        // Check if sonar-scanner exists
        try {
            const key = input.projectKey;
            // Assume sonar-scanner is in path or use npx sonar-scanner
            // For now, we'll try to run it, if it fails, we report that it needs installation
            const cmd = `npx sonar-scanner -Dsonar.projectKey=${key} -Dsonar.sources=${input.sources}`;
            const { stdout } = await execAsync(cmd);
            return { ok: true, output: { summary: stdout.slice(0, 2000) }, logs: ['sonar scan complete'] };
        } catch (e: any) {
            if (String(e.message).includes('command not found') || String(e.message).includes('ENOENT')) {
                return { ok: false, error: 'sonar-scanner/npx not available. Please install dependencies.', logs: [] };
            }
            return { ok: false, error: `Sonar failed: ${e.message}`, logs: [] };
        }
    }
}

export class DependencyAuditorTool extends BaseTool {
    name = 'dependency_auditor';
    description = 'Check project dependencies for known security vulnerabilities.';
    version = '1.0.0';
