    private manageDependencies(dependencies: string[], logs: string[]) {
        logs.push(`Managing Go modules`);
        logs.push(`Dependencies: ${dependencies.join(', ')}`);

        return {
            ok: true,
            output: {
                success: true,
                dependencies,
                message: 'Run "go mod tidy" to install dependencies'
