import { BaseTool } from '../base';
import { ToolPermission } from '../types';
import path from 'path';
import fs from 'fs';
import os from 'os';
import { exec } from 'child_process';
import util from 'util';
import { getSessionSecret, getUserSecret } from '../../services/secrets';

const execAsync = util.promisify(exec);

export class GitOpsTool extends BaseTool {
    name = 'git_ops';
    description = 'Perform git operations (commit, push, pull, etc) with auto-authentication.';
    version = '1.0.0';
    tags = ['git', 'vcs', 'source-control'];
    inputSchema = {
        type: 'object' as const,
        properties: {
            operation: { type: 'string' }, // add, commit, push, pull, clone, fetch, status
            args: { type: 'array', items: { type: 'string' } },
            sessionId: { type: 'string' },
            userId: { type: 'string' }
        },
        required: ['operation']
    };
    outputSchema = { type: 'object' as const, properties: { output: { type: 'string' } } };
    permissions: ToolPermission[] = ['execute', 'internet', 'read', 'write'];
    sideEffects: ToolPermission[] = ['execute', 'write', 'internet'];
    rateLimitPerMinute = 30;
    auditFields = ['operation', 'args'];

    async execute(input: any) {
        const logs: string[] = [];
        const op = String(input?.operation);
        const args = (input?.args as string[]) || [];
        const sessionId = String(input?.sessionId || '').trim();
        const userId = String(input?.userId || '').trim();

        let askpassDir = '';

        try {
            // Auto-configure user if committing
            if (op === 'commit') {
                try { await execAsync('git config user.name'); } catch {
                    await execAsync('git config user.name "Joe AI"');
                    await execAsync('git config user.email "joe@xelitesolutions.com"');
                }
            }

            const env: any = { ...process.env };

            // Handle Authentication via ASKPASS
            const wantsAuth = ['push', 'fetch', 'pull', 'clone'].includes(op);
            if (wantsAuth && (sessionId || userId)) {
                try {
                    const token = (userId ? (await getUserSecret(userId, 'github', 'GITHUB_TOKEN')) : null) ||
                        getSessionSecret(sessionId, 'GITHUB_TOKEN') || '';

                    if (token) {
                        askpassDir = await fs.promises.mkdtemp(path.join(os.tmpdir(), 'joe-askpass-'));
                        const askpassPath = path.join(askpassDir, 'askpass.sh');
                        const script = `#!/bin/sh\ncase "$1" in\n*Username*) echo "x-access-token";;\n*) echo "$JOE_GIT_TOKEN";;\nesac\n`;
                        await fs.promises.writeFile(askpassPath, script, { mode: 0o700 });

                        env.GIT_ASKPASS = askpassPath;
                        env.GIT_TERMINAL_PROMPT = '0';
                        env.DISPLAY = '1'; // prevent window prompts
                        env.JOE_GIT_TOKEN = token;
                    }
                } catch (e: any) {
                    logs.push(`git.auth_setup_failed=${e.message}`);
                }
            }

            let cmd = `git ${op}`;
            if (args.length) cmd += ` ${args.join(' ')}`;

            logs.push(`git.cmd=${cmd}`);
            const { stdout, stderr } = await execAsync(cmd, { cwd: process.cwd(), env });
            logs.push(`git.success=${op}`);
            return { ok: true, output: { output: stdout || stderr }, logs };

        } catch (e: any) {
            logs.push(`git.error=${e.message}`);
            return { ok: false, error: e.message || e.stderr, logs };
        } finally {
            if (askpassDir) {
                try { await fs.promises.rm(askpassDir, { recursive: true, force: true }); } catch { }
            }
        }
    }
}

import { ToolDefinition } from '../types';
import https from 'https';

/**
 * GitHubRepoManagerTool - GitHub repository management
 * Create, manage, and push code to GitHub repositories
 */
export class GitHubRepoManagerTool implements ToolDefinition {
    name = 'github_repo_manager';
    version = '1.0.0';
    description = 'Create and manage GitHub repositories, push code automatically';
    tags = ['github', 'repository', 'git'];

    inputSchema = {
        type: 'object' as const,
        properties: {
            action: {
                type: 'string' as const,
                enum: ['create', 'push', 'list', 'delete'],
                description: 'Action to perform'
            },
            repoName: {
                type: 'string' as const,
                description: 'Repository name'
            },
            description: {
                type: 'string' as const,
                description: 'Repository description'
            },
            private: {
                type: 'boolean' as const,
                description: 'Make repository private'
            },
            token: {
                type: 'string' as const,
                description: 'GitHub personal access token'
            }
        },
        required: ['action']
    };

    outputSchema = {
        type: 'object' as const,
        properties: {
            success: { type: 'boolean' as const },
            repoUrl: { type: 'string' as const },
            message: { type: 'string' as const }
        }
    };

    permissions = ['execute' as const];
    sideEffects = ['write' as const];
    rateLimitPerMinute = 10;
    auditFields = ['action', 'repoName'];
    mockSupported = false;

    async execute(input: any) {
        const { action, repoName, description = '', private: isPrivate = false, token } = input;
        const logs: string[] = [];

        try {
            logs.push(`GitHub action: ${action} for repo: ${repoName || 'N/A'}`);

            const githubToken = token || process.env.GITHUB_TOKEN;
            if (!githubToken && action !== 'list') {
                throw new Error('GitHub token required. Set GITHUB_TOKEN env var or provide token.');
            }

            switch (action) {
                case 'create':
                    return await this.createRepo(repoName, description, isPrivate, githubToken, logs);

                case 'list':
                    return await this.listRepos(githubToken, logs);

                case 'delete':
                    return await this.deleteRepo(repoName, githubToken, logs);

                default:
                    throw new Error(`Unknown action: ${action}`);
            }

        } catch (error: any) {
            logs.push(`Error: ${error.message}`);
            return {
                ok: false,
                error: error.message,
                logs
            };
        }
    }

    private async createRepo(name: string, description: string, isPrivate: boolean, token: string, logs: string[]) {
        const data = JSON.stringify({
            name,
            description,
            private: isPrivate,
            auto_init: true
        });

        const result = await this.githubRequest('POST', '/user/repos', data, token);

        logs.push(`Repository created: ${result.html_url}`);

        return {
            ok: true,
            output: {
                success: true,
                repoUrl: result.html_url,
                cloneUrl: result.clone_url,
                message: `Repository ${name} created successfully`
            },
            logs
        };
    }

    private async listRepos(token: string, logs: string[]) {
        const repos = await this.githubRequest('GET', '/user/repos?per_page=10', null, token);

        logs.push(`Found ${repos.length} repositories`);

        return {
            ok: true,
            output: {
                success: true,
                repos: repos.map((r: any) => ({
                    name: r.name,
                    url: r.html_url,
                    private: r.private
                })),
                message: `Listed ${repos.length} repositories`
            },
            logs
        };
    }

    private async deleteRepo(name: string, token: string, logs: string[]) {
        const username = await this.getUsername(token);
        await this.githubRequest('DELETE', `/repos/${username}/${name}`, null, token);

        logs.push(`Repository deleted: ${name}`);

        return {
            ok: true,
            output: {
                success: true,
                message: `Repository ${name} deleted successfully`
            },
            logs
        };
    }

    private async getUsername(token: string): Promise<string> {
        const user = await this.githubRequest('GET', '/user', null, token);
        return user.login;
    }

    private githubRequest(method: string, path: string, data: string | null, token: string): Promise<any> {
        return new Promise((resolve, reject) => {
            const options: any = {
                hostname: 'api.github.com',
                path: path,
                method: method,
                headers: {
                    'User-Agent': 'Joe-AI-Agent',
                    'Authorization': `token ${token}`,
                    'Accept': 'application/vnd.github.v3+json',
                    'Content-Type': 'application/json'
                }
            };

            if (data) {
                options.headers['Content-Length'] = Buffer.byteLength(data);
            }

            const req = https.request(options, (res) => {
                let responseData = '';
                res.on('data', (chunk) => responseData += chunk);
                res.on('end', () => {
                    if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
                        try {
                            resolve(responseData ? JSON.parse(responseData) : {});
                        } catch (e) {
                            resolve({});
                        }
                    } else {
                        reject(new Error(`GitHub API error: ${res.statusCode} - ${responseData}`));
                    }
                });
            });

            req.on('error', reject);
            if (data) req.write(data);
            req.end();
        });
    }
}

