    };

    outputSchema = {
        type: 'string' as const
    };

    // Legacy compatibility
    get parameters() {
        return this.inputSchema;
    }

    permissions = [];
    sideEffects = [];
    rateLimitPerMinute = 0;
    auditFields = [];
    mockSupported = false;

    async execute(input: { question: string }) {
        const { question } = input;

        const providers = [
            {
                name: 'OpenAI',
                run: async () => {
                    const { applyNeuralProtocol } = require('../../llm');
                    const systemPrompt = applyNeuralProtocol(`You are **Joe**, the Elite AI Engine of **XElite Solutions**.
You are a world-class specialist in **Web Development, App Architecture, and Complex System Engineering**.
Your responses should be **powerful, enticing, and professional**. Use language that captivates the user and demonstrates superior expertise ("Elite", "Advanced", "Premium State-of-the-Art").
You have full autonomous capabilities (Files, Terminal, Browser).
Always identify as **Joe**. Never mention ChatGPT or OpenAI.
Your goal is to build the extraordinary.`);

                    const OpenAI = require('openai').default;
                    const apiKey = process.env.OPENAI_API_KEY;
                    if (!apiKey) throw new Error('OPENAI_API_KEY not found');
                    const client = new OpenAI({ apiKey });
                    const res = await client.chat.completions.create({
                        model: 'gpt-4o',
                        messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: question }],
                        max_tokens: 1000
                    });
                    return res.choices[0]?.message?.content;
                }
            },
            {
                name: 'Groq (Free)',
                run: async () => {
                    if (!process.env.GROQ_API_KEY || process.env.GROQ_API_KEY === 'gsk_placeholder') throw new Error('Skipping Groq: No API Key');
                    const { GroqProvider } = require('../../llm/providers/groq');
                    const gp = new GroqProvider();
                    const { applyNeuralProtocol } = require('../../llm');
                    const prompt = applyNeuralProtocol(`You are **Joe** (XElite Solutions). Elite Expert in Web/App Dev. Powerful, enticing, professional. Never ChatGPT.`);
                    return await gp.chatComplete([{ role: 'system', content: prompt }, { role: 'user', content: question }]);
                }
            },
            {
                name: 'OpenRouter (Free)',
                run: async () => {
                    if (!process.env.OPENROUTER_API_KEY) throw new Error('Skipping OpenRouter: No API Key');
                    const { OpenRouterProvider } = require('../../llm/providers/openrouter');
                    const op = new OpenRouterProvider(process.env.OPENROUTER_API_KEY || undefined);
                    const { applyNeuralProtocol } = require('../../llm');
                    const prompt = applyNeuralProtocol(`You are **Joe** (XElite Solutions). Elite Expert in Web/App Dev. Powerful, enticing, professional. Never ChatGPT.`);
                    return await op.chatComplete([{ role: 'system', content: prompt }, { role: 'user', content: question }]);
                }
            },
            {
                name: 'Pollinations (Backup)',
                run: async () => {
                    const { PollinationsProvider } = require('../../llm/providers/pollinations');
                    const pp = new PollinationsProvider();
                    const { applyNeuralProtocol } = require('../../llm');
                    const prompt = applyNeuralProtocol(`You are **Joe** (XElite Solutions). Elite Expert in Web/App Dev. Powerful, enticing, professional. Never ChatGPT.`);
                    return await pp.chatComplete([{ role: 'system', content: prompt }, { role: 'user', content: question }]);
                }
            }
        ];

        let lastError = '';
        for (const p of providers) {
            try {
                // Skip if key missing for paid (except Pollinations)
                if (p.name === 'OpenAI' && !process.env.OPENAI_API_KEY) continue;
                if (p.name.includes('Groq') && (!process.env.GROQ_API_KEY || process.env.GROQ_API_KEY === 'gsk_placeholder')) continue;
                if (p.name.includes('OpenRouter') && !process.env.OPENROUTER_API_KEY) continue;

                const answer = await p.run();
                if (answer) {
                    return {
                        ok: true,
                        output: answer,
                        logs: [`central_answer: Answered via ${p.name}`]
                    };
                }
            } catch (e: any) {
                console.warn(`[CentralAnswer] ${p.name} failed: ${e.message}`);
                lastError = e.message;
                // continue to next provider
            }
        }

        return {
            ok: false,
            error: `All AI providers failed. Last error: ${lastError}`,
            logs: [`central_answer: Failed all providers`]
        };
    }
}

import { ToolDefinition } from '../types';
import crypto from 'crypto';

/**
 * CacheManagerTool - Smart caching system
 * Manages in-memory cache with TTL, statistics, and invalidation
 */
export class CacheManagerTool implements ToolDefinition {
    name = 'cache_manager';
    version = '1.0.0';
    description = 'Manage in-memory cache with TTL, stats, and invalidation';
    tags = ['cache', 'performance', 'optimization'];

    inputSchema = {
        type: 'object' as const,
        properties: {
            action: {
                type: 'string' as const,
                enum: ['get', 'set', 'delete', 'clear', 'stats'],
                description: 'Cache action'
            },
            key: {
                type: 'string' as const,
                description: 'Cache key'
            },
            value: {
                type: 'string' as const,
                description: 'Value to cache (for set action)'
            },
            ttl: {
                type: 'number' as const,
                description: 'Time to live in seconds (default: 3600)'
            }
        },
        required: ['action']
    };

    outputSchema = {
        type: 'object' as const,
        properties: {
            success: { type: 'boolean' as const },
            value: { type: 'string' as const },
            stats: { type: 'object' as const }
        }
    };

    permissions = [];
    sideEffects = [];
    rateLimitPerMinute = 100;
    auditFields = ['action'];
    mockSupported = false;

    // In-memory cache storage
    private static cache = new Map<string, { value: any; expires: number }>();
    private static stats = {
        hits: 0,
        misses: 0,
        sets: 0,
        deletes: 0,
        clears: 0
    };

    async execute(input: { action: string; key?: string; value?: any; ttl?: number }) {
        const { action, key, value, ttl = 3600 } = input;
        const logs: string[] = [];

        try {
            switch (action) {
                case 'get':
                    return this.get(key!, logs);

                case 'set':
                    return this.set(key!, value, ttl, logs);

                case 'delete':
                    return this.delete(key!, logs);

                case 'clear':
                    return this.clear(logs);

                case 'stats':
                    return this.getStats(logs);

                default:
                    throw new Error(`Unknown action: ${action}`);
            }

        } catch (error: any) {
            logs.push(`Error: ${error.message}`);
            return {
                ok: false,
                error: error.message,
                logs
            };
        }
    }

    private get(key: string, logs: string[]) {
        const entry = CacheManagerTool.cache.get(key);

        if (!entry) {
            CacheManagerTool.stats.misses++;
            logs.push(`Cache miss: ${key}`);
            return {
                ok: true,
                output: { success: false, hit: false },
                logs
            };
        }

        // Check if expired
        if (Date.now() > entry.expires) {
            CacheManagerTool.cache.delete(key);
            CacheManagerTool.stats.misses++;
            logs.push(`Cache expired: ${key}`);
            return {
                ok: true,
                output: { success: false, hit: false, expired: true },
                logs
            };
        }

        CacheManagerTool.stats.hits++;
        logs.push(`Cache hit: ${key}`);
        return {
            ok: true,
            output: { success: true, hit: true, value: entry.value },
            logs
        };
    }

    private set(key: string, value: any, ttl: number, logs: string[]) {
        const expires = Date.now() + (ttl * 1000);
        CacheManagerTool.cache.set(key, { value, expires });
        CacheManagerTool.stats.sets++;

        logs.push(`Cache set: ${key} (TTL: ${ttl}s)`);
        return {
            ok: true,
            output: { success: true, key, ttl },
            logs
        };
    }

    private delete(key: string, logs: string[]) {
        const deleted = CacheManagerTool.cache.delete(key);
        if (deleted) {
            CacheManagerTool.stats.deletes++;
        }

        logs.push(`Cache delete: ${key} (${deleted ? 'found' : 'not found'})`);
        return {
            ok: true,
            output: { success: deleted },
            logs
        };
    }

    private clear(logs: string[]) {
        const size = CacheManagerTool.cache.size;
        CacheManagerTool.cache.clear();
        CacheManagerTool.stats.clears++;

        logs.push(`Cache cleared: ${size} entries`);
        return {
            ok: true,
            output: { success: true, cleared: size },
            logs
        };
    }

    private getStats(logs: string[]) {
        const total = CacheManagerTool.stats.hits + CacheManagerTool.stats.misses;
        const hitRate = total > 0 ? (CacheManagerTool.stats.hits / total * 100).toFixed(2) : '0.00';

        const stats = {
            ...CacheManagerTool.stats,
            total,
            hitRate: `${hitRate}%`,
            cacheSize: CacheManagerTool.cache.size
        };

        logs.push(`Cache stats: ${hitRate}% hit rate, ${stats.cacheSize} entries`);
        return {
            ok: true,
            output: { success: true, stats },
            logs
        };
    }
}

import { ToolDefinition, ToolExecutionResult } from '../types';
import fs from 'fs';
import path from 'path';

export const BulkFileGeneratorTool: ToolDefinition = {
    name: 'bulk_file_generator',
    version: '1.0.0',
    tags: ['filesystem', 'bulk', 'scaffold'],
    description: 'Create or overwrite multiple files at once. Essential for efficient project scaffolding.',
    inputSchema: {
        type: 'object',
        properties: {
            files: {
                type: 'array',
                items: {
                    type: 'object',
                    properties: {
                        path: { type: 'string', description: 'Absolute path or relative to cwd' },
                        content: { type: 'string' }
                    },
                    required: ['path', 'content']
                },
                description: 'List of files to create'
            },
            cwd: { type: 'string', description: 'Base directory for relative paths' }
        },
        required: ['files']
    },
    outputSchema: {
        type: 'object',
        properties: {
            success: { type: 'boolean' },
            created: { type: 'array', items: { type: 'string' } },
            errors: { type: 'array' }
        }
    },
    permissions: ['write'],
    sideEffects: ['write'],
    rateLimitPerMinute: 60,
    auditFields: ['cwd'],
    mockSupported: true,
    execute: async (input) => {
        const files = input.files;
        const cwd = input.cwd || process.cwd();
        const created: string[] = [];
        const errors: string[] = [];
        const logs: string[] = [];

        const totalFiles = files.length;
        logs.push(`[BulkGen] Processing ${totalFiles} files in ${cwd}...`);

        // PHASE 5 ENHANCEMENT: Support for large batches (50+ files)
        const BATCH_SIZE = 10;
        let processed = 0;

        for (let i = 0; i < files.length; i += BATCH_SIZE) {
            const batch = files.slice(i, i + BATCH_SIZE);

            for (const file of batch) {
                try {
                    const targetPath = path.isAbsolute(file.path) ? file.path : path.resolve(cwd, file.path);

                    // Security check: Ensure we are not writing outside allowed dirs
                    // For "God Mode" we assume trusted agent for now, but in prod we restrict.

                    const dir = path.dirname(targetPath);
                    if (!fs.existsSync(dir)) {
                        fs.mkdirSync(dir, { recursive: true });
                    }

                    fs.writeFileSync(targetPath, file.content, 'utf-8');
                    created.push(targetPath);
                    processed++;

                    // Progress reporting every 10 files
                    if (processed % 10 === 0) {
                        logs.push(`Progress: ${processed}/${totalFiles} files (${Math.round(processed / totalFiles * 100)}%)`);
                    }
                } catch (e: any) {
                    errors.push(`Failed to write ${file.path}: ${e.message}`);
                    logs.push(`Error: ${file.path} - ${e.message}`);
                }
            }

            // Small delay between batches to avoid overwhelming the system
            if (i + BATCH_SIZE < files.length) {
                await new Promise(resolve => setTimeout(resolve, 10));
            }
        }

        logs.push(`[BulkGen] Complete: ${created.length} created, ${errors.length} errors`);

        return {
            ok: errors.length === 0,
            output: {
                success: errors.length === 0,
                created,
                errors,
                stats: {
                    total: totalFiles,
                    created: created.length,
                    failed: errors.length
                }
            },
            logs
        };
    }
};

import { BaseTool } from '../base';
import { ToolPermission } from '../types';
import { chromium } from 'playwright';
import path from 'path';

export class BrowserVisionTool extends BaseTool {
    name = 'browser_vision';
    description = 'Visit a website and take a screenshot (simulated vision).';
    version = '1.0.0';
    tags = ['browser', 'vision', 'screenshot'];
    inputSchema = {
        type: 'object' as const,
        properties: {
            url: { type: 'string' },
            width: { type: 'number', default: 1280 },
            height: { type: 'number', default: 720 }
        },
        required: ['url']
    };
    outputSchema = {
        type: 'object' as const,
        properties: {
            screenshotPath: { type: 'string' },
            base64: { type: 'string' }
        }
    };
    permissions: ToolPermission[] = ['internet', 'read', 'write'];
    sideEffects: ToolPermission[] = ['write'];

    async execute(input: any) {
        const url = String(input.url);
        const browser = await chromium.launch({ headless: true });
        const page = await browser.newPage();

        try {
            await page.setViewportSize({ width: input.width || 1280, height: input.height || 720 });
            await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 30000 });

            const filename = `screenshot_${Date.now()}.png`;
            const outDir = path.join(process.cwd(), 'screenshots');
            // Ensure dir exists
            const fs = require('fs');
            if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });

            const fullPath = path.join(outDir, filename);
            await page.screenshot({ path: fullPath });

            // For now, we won't return giant base64 to avoid context bloat, just the path
            // If the frontend can serve it, great.

            await browser.close();

            return {
                ok: true,
                output: { screenshotPath: fullPath, message: 'Screenshot captured.' },
                logs: [`screenshot=${url} path=${fullPath}`]
            };
        } catch (e: any) {
            await browser.close();
            return { ok: false, error: e.message, logs: [] };
        }
    }
}

