    sideEffects: ToolPermission[] = [];
    async execute(input: any) {
        const root = String(input?.path || process.cwd()).trim();
        try {
            const result = Analyst.analyze(root);
            return { ok: true, output: result, logs: [`analyst.analyze.success=${root}`] };
        } catch (e: any) {
            return { ok: false, error: e.message, logs: [] };
        }
    }
}

export class AnalyzeCodebaseTool extends BaseTool {
    name = 'analyze_codebase';
    description = 'Deep analyze of codebase using file structure and LLM summarization.';
    version = '1.0.0';
    tags = ['analysis', 'fs', 'llm'];
    inputSchema = { type: 'object' as const, properties: { path: { type: 'string' } }, required: [] };
    outputSchema = { type: 'object' as const, properties: { summary: { type: 'string' } } };
    permissions: ToolPermission[] = ['read', 'internet']; // LLM access
    sideEffects: ToolPermission[] = [];

    async execute(input: any) {
        const p = String(input?.path || '.');
        const root = resolveToolPath(p);
        const logs: string[] = [];

        if (!fs.existsSync(root)) return { ok: false, error: 'Path not found', logs };

        logs.push(`analyze.root=${root}`);

        // 1. Structure
        const getStructure = (dir: string, depth: number): string[] => {
            if (depth > 3) return [];
            try {
                const items = fs.readdirSync(dir, { withFileTypes: true });
                let res: string[] = [];
                for (const item of items) {
                    if (item.name.startsWith('.') || item.name === 'node_modules' || item.name === 'dist' || item.name === 'build' || item.name === 'coverage') continue;
                    if (item.isDirectory()) {
                        res.push(`${item.name}/`);
                        const subs = getStructure(path.join(dir, item.name), depth + 1);
                        res = res.concat(subs.map(s => `${item.name}/${s}`));
                    } else {
                        res.push(item.name);
                    }
                }
                return res;
            } catch { return []; }
        };
        const allFiles = getStructure(root, 0);
        const structure = allFiles
            .filter(f => !f.includes('test/') && !f.includes('__tests__/'))
            .slice(0, 60)
            .join('\n');

        // 2. Key Files
        const keyFiles = ['package.json', 'README.md', 'tsconfig.json', 'Dockerfile', 'docker-compose.yml', 'go.mod', 'requirements.txt', 'Cargo.toml', 'Gemfile', 'pyproject.toml'];
        const fileContents: string[] = [];
        for (const kf of keyFiles) {
            const kp = path.join(root, kf);
            if (fs.existsSync(kp)) {
                const content = fs.readFileSync(kp, 'utf-8');
                if (kf === 'package.json') {
                    try {
                        const pkg = JSON.parse(content);
                        const slim = { name: pkg.name, version: pkg.version, scripts: pkg.scripts, dependencies: pkg.dependencies, devDependencies: pkg.devDependencies };
                        fileContents.push(`=== ${kf} ===\n${JSON.stringify(slim, null, 2)}\n`);
                    } catch {
                        fileContents.push(`=== ${kf} ===\n${content.slice(0, 1000)}\n`);
                    }
                } else {
                    fileContents.push(`=== ${kf} ===\n${content.slice(0, 1500)}\n`);
                }
            }
        }

        // 3. LLM Summary
        const apiKey = process.env.OPENAI_API_KEY;
        if (!apiKey) {
            return { ok: true, output: { summary: `## Structure\n${structure}\n\n## Files\n${fileContents.map(f => f.split('\n')[0]).join('\n')}` }, logs };
        }

        try {
            // Determine client (Assuming OpenAI direct usage as per registry)
            const OpenAIConstructor = require('openai').default;
            const client = new OpenAIConstructor({ apiKey, baseURL: process.env.OPENAI_BASE_URL });

            const completion = await client.chat.completions.create({
                model: 'gpt-4o',
                messages: [
                    { role: 'system', content: 'You are a Senior Software Architect. Analyze the provided codebase context and generate a high-level architectural summary. Focus on: Tech Stack, Key Components, Entry Points, and Project Structure. Be concise.' },
                    { role: 'user', content: `File Structure (partial):\n${structure}\n\nKey File Contents:\n${fileContents.join('\n')}` }
                ]
            });
            const summary = completion.choices[0].message.content || 'Analysis failed';
            return { ok: true, output: { summary }, logs };
        } catch (e: any) {
            logs.push(`analyze.llm_error=${e.message}`);
            return { ok: true, output: { summary: `## Structure\n${structure}\n\n## Files (LLM Failed)\n${fileContents.map(f => f.split('\n')[0]).join('\n')}` }, logs };
        }
    }
}

import { ToolDefinition } from '../types';

/**
 * AlertManagerTool - Alert management with conditions and notifications
 * Provides alerting capabilities for production monitoring
 */
export class AlertManagerTool implements ToolDefinition {
    name = 'alert_manager';
    version = '1.0.0';
    description = 'Manage alerts with conditions, notifications, and history tracking';
    tags = ['alerts', 'monitoring', 'notifications'];

    inputSchema = {
        type: 'object' as const,
        properties: {
            action: {
                type: 'string' as const,
                enum: ['create', 'trigger', 'resolve', 'list', 'history'],
                description: 'Action to perform'
            },
            alertId: {
                type: 'string' as const,
                description: 'Alert identifier'
            },
            name: {
                type: 'string' as const,
                description: 'Alert name'
            },
            condition: {
                type: 'object' as const,
                description: 'Alert condition',
                properties: {
                    metric: { type: 'string' as const },
                    operator: { type: 'string' as const },
                    threshold: { type: 'number' as const }
                }
            },
            severity: {
                type: 'string' as const,
                enum: ['low', 'medium', 'high', 'critical'],
                description: 'Alert severity'
            },
            message: {
                type: 'string' as const,
                description: 'Alert message'
            },
            metadata: {
                type: 'object' as const,
                description: 'Additional alert metadata'
            }
        },
        required: ['action']
    };

    outputSchema = {
        type: 'object' as const,
        properties: {
            success: { type: 'boolean' as const },
            alertId: { type: 'string' as const },
            alerts: { type: 'array' as const },
            history: { type: 'array' as const }
        }
    };

    permissions = [];
    sideEffects = ['write' as const];
    rateLimitPerMinute = 60;
    auditFields = ['action', 'alertId', 'severity'];
    mockSupported = false;

    // In-memory alert storage
    private static alerts = new Map<string, {
        id: string;
        name: string;
        condition: any;
        severity: string;
        status: 'active' | 'triggered' | 'resolved';
        createdAt: string;
        triggeredAt?: string;
        resolvedAt?: string;
    }>();

    private static history: Array<{
        alertId: string;
        action: string;
        timestamp: string;
        message: string;
        metadata: any;
    }> = [];

    async execute(input: { action: string; alertId?: string; name?: string; condition?: any; severity?: string; message?: string; metadata?: any }) {
        const { action, alertId, name, condition, severity, message, metadata } = input;
        const logs: string[] = [];

        try {
            logs.push(`AlertManager: ${action}`);

            switch (action) {
                case 'create':
                    return this.createAlert(name || '', condition, severity || 'medium', logs);

                case 'trigger':
                    return this.triggerAlert(alertId || '', message || '', metadata, logs);

                case 'resolve':
                    return this.resolveAlert(alertId || '', message || '', logs);

                case 'list':
                    return this.listAlerts(logs);

                case 'history':
                    return this.getHistory(alertId, logs);

                default:
                    throw new Error(`Unknown action: ${action}`);
            }

        } catch (error: any) {
            logs.push(`Error: ${error.message}`);
            return {
                ok: false,
                error: error.message,
                logs
            };
        }
    }

    private createAlert(name: string, condition: any, severity: string, logs: string[]) {
        const alertId = `alert_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
        const timestamp = new Date().toISOString();

        const alert = {
            id: alertId,
            name,
            condition: condition || {},
            severity,
            status: 'active' as const,
            createdAt: timestamp
        };

        AlertManagerTool.alerts.set(alertId, alert);

        // Add to history
        AlertManagerTool.history.push({
            alertId,
            action: 'created',
            timestamp,
            message: `Alert "${name}" created`,
            metadata: { severity, condition }
        });

        logs.push(`Alert created: ${name} (${severity})`);

        return {
            ok: true,
            output: {
                success: true,
                alertId,
                alert,
                message: `Alert "${name}" created successfully`
            },
            logs
        };
    }

    private triggerAlert(alertId: string, message: string, metadata: any, logs: string[]) {
        const alert = AlertManagerTool.alerts.get(alertId);

        if (!alert) {
            throw new Error(`Alert ${alertId} not found`);
        }

        const timestamp = new Date().toISOString();
        alert.status = 'triggered';
        alert.triggeredAt = timestamp;

        AlertManagerTool.alerts.set(alertId, alert);

        // Add to history
        AlertManagerTool.history.push({
            alertId,
            action: 'triggered',
            timestamp,
            message: message || `Alert "${alert.name}" triggered`,
            metadata: metadata || {}
        });

        logs.push(`Alert triggered: ${alert.name}`);

        return {
            ok: true,
            output: {
                success: true,
                alertId,
                alert,
                message: `Alert "${alert.name}" triggered`,
                severity: alert.severity
            },
            logs
        };
    }

    private resolveAlert(alertId: string, message: string, logs: string[]) {
        const alert = AlertManagerTool.alerts.get(alertId);

        if (!alert) {
            throw new Error(`Alert ${alertId} not found`);
        }

        const timestamp = new Date().toISOString();
        alert.status = 'resolved';
        alert.resolvedAt = timestamp;

        AlertManagerTool.alerts.set(alertId, alert);

        // Add to history
        AlertManagerTool.history.push({
            alertId,
            action: 'resolved',
            timestamp,
            message: message || `Alert "${alert.name}" resolved`,
            metadata: {}
        });

        logs.push(`Alert resolved: ${alert.name}`);

        return {
            ok: true,
            output: {
                success: true,
                alertId,
                alert,
                message: `Alert "${alert.name}" resolved`
            },
            logs
        };
    }

    private listAlerts(logs: string[]) {
        const alerts = Array.from(AlertManagerTool.alerts.values());

        const summary = {
            total: alerts.length,
            active: alerts.filter(a => a.status === 'active').length,
            triggered: alerts.filter(a => a.status === 'triggered').length,
            resolved: alerts.filter(a => a.status === 'resolved').length
        };

        logs.push(`Listed ${alerts.length} alerts`);

        return {
            ok: true,
            output: {
                success: true,
                alerts,
                summary
            },
            logs
        };
    }

    private getHistory(alertId: string | undefined, logs: string[]) {
        let history = [...AlertManagerTool.history];

        if (alertId) {
            history = history.filter(h => h.alertId === alertId);
        }

        logs.push(`Retrieved ${history.length} history entries`);

        return {
            ok: true,
            output: {
                success: true,
                history,
                count: history.length
            },
            logs
        };
    }
}

